/* 千题库 v2（对照 OSG 重写，360 题） */
var GBANK=[{"id":"v2d1-1","d":"域1 安全与风险管理","w":3,"q":"某跨国集团董事会要求信息安全部门证明安全投入的价值。CISO 最适合采用哪种方法向管理层展示风险敞口的货币化结果？","o":["定性风险评估矩阵","年损失期望（ALE）的定量计算","风险 Appetite 声明","安全成熟度模型（CMMI）评估"],"a":1,"e":"定量分析用 AV×EF=SLE、SLE×ARO=ALE，将风险换算为货币损失，便于管理层做成本收益决策。定性矩阵不产出货币化数字；风险偏好声明表达承受意愿；成熟度模型衡量安全体系水平，均不能直接量化风险敞口。（OSG 第1章 风险管理）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-2","d":"域1 安全与风险管理","w":3,"q":"一家制药公司数据中心的资产价值为 2000 万元，一次水灾预计造成 40% 的损失，此类水灾平均每 5 年发生一次。该风险的 ALE 是多少？","o":["160 万元","800 万元","2000 万元","400 万元"],"a":0,"e":"SLE=AV×EF=2000万×40%=800 万；ARO=1/5=0.2；ALE=SLE×ARO=800万×0.2=160 万元。其余选项漏乘 ARO 或算错 EF。（OSG 第1章 定量风险分析）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-3","d":"域1 安全与风险管理","w":3,"q":"组织评估某风险后认为：处置成本远高于潜在损失，且该风险在风险偏好范围内。最恰当的处置方式是？","o":["风险转移","风险拒绝","风险接受","风险威慑"],"a":2,"e":"当处置成本超过潜在损失且风险在可承受范围内时，风险接受（Acceptance）是理性选择，但需管理层正式批准并记录。风险转移（如买保险）适合低可能性高影响；不存在'风险拒绝'这一处置方式；威慑只降低可能性，不解决成本权衡。（OSG 第1章 风险响应）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-4","d":"域1 安全与风险管理","w":3,"q":"以下哪类文件由高级管理层制定、篇幅最短、具有组织内最高约束力，并为整座'文件金字塔'定调？","o":["标准","规程","政策","基线"],"a":2,"e":"政策（Policy）位于文件层级顶端，由最高管理层批准，概述性、强制性强；标准规定强制性要求细节；规程是逐步操作说明；基线是最低安全实现水平。（OSG 第1章 安全文件层次）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-5","d":"域1 安全与风险管理","w":3,"q":"某岗位既负责审批采购订单，又负责核对付款记录。从人员安全角度看，这主要违反了什么？","o":["岗位轮换","双人控制（Two-person control）","职责分离（SoD）","强制休假"],"a":2,"e":"职责分离要求把存在利益冲突的职能分给不同人，防止单人舞弊。岗位轮换和强制休假是检测性控制；双人控制要求两人同时在场才能完成敏感操作，与题设场景不符。（OSG 第2章 人员安全）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-6","d":"域1 安全与风险管理","w":3,"q":"新员工入职时必须签署的、约定其对组织信息资产保密义务的文件是？","o":[" 可接受使用政策（AUP）","NDA（保密协议）","隐私政策","安全意识培训记录"],"a":1,"e":"NDA/保密协议用于法律上约束员工不得泄露敏感信息，入职与离职时均应签署。可接受使用政策规定资源使用方式；隐私政策面向个人数据处理；培训记录不具约束力。（OSG 第2章 人员安全）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-7","d":"域1 安全与风险管理","w":3,"q":"员工离职流程中，以下哪项应最先执行以将风险降到最低？","o":["安排离职面谈","立即撤销其所有账户和访问权限","收回门禁卡和笔记本","发送全员通报"],"a":1,"e":"离职即时撤销账户与访问权限是防止离职员工越权访问的首要控制；物归原主、面谈等也应做，但撤销权限时效性最强、风险削减最大。（OSG 第2章 员工生命周期）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-8","d":"域1 安全与风险管理","w":3,"q":"第三方服务商人员拥有与正式员工同等的系统访问权限。为管理外包风险，组织最应坚持的做法是？","o":["与服务商签署 SLA 即可，无需再管","对服务商人员执行与员工同等的安全审查与访问治理","把责任全部转移给服务商并在合同中免责","限制服务商只能远程访问"],"a":1,"e":"外包不转移最终的数据保护责任；应对第三方人员执行背景审查、最小权限、监督审计等与内部员工一致的治理。SLA 只是服务指标；合同免责不能免除数据泄露的法律责任；仅限远程访问不解决权限滥用。（OSG 第2章 第三方治理）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-9","d":"域1 安全与风险管理","w":3,"q":"制定业务连续性计划（BCP）时，确定哪些业务流程对组织生存最关键、可容忍的最长中断时间是哪一步？","o":["业务影响分析（BIA）","连续性计划测试","灾难恢复计划实施","危机通信演练"],"a":0,"e":"BIA 识别关键业务流程并量化 MTD/RTO/RPO，是 BCP 的核心输入。测试与演练发生在计划编制之后；DRP 是 BCP 的子集而非前置步骤；危机通信是响应环节。（OSG 第3章 业务连续性计划）","f":"3 业务连续性计划","v":[]},{"id":"v2d1-10","d":"域1 安全与风险管理","w":3,"q":"RTO（恢复时间目标）与 MTD/MTPD 的关系，正确的是？","o":["RTO 必须大于 MTD","RTO 应小于等于 MTD","两者没有关系","RTO 等于 RPO"],"a":1,"e":"MTD 是业务可容忍的最长中断时间，恢复必须在 MTD 内完成，因此 RTO≤MTD，否则业务无法存活。RPO 针对数据而非时间恢复能力。（OSG 第3章 恢复目标）","f":"3 业务连续性计划","v":[]},{"id":"v2d1-11","d":"域1 安全与风险管理","w":3,"q":"BIA 中，RPO 决定了什么？","o":["灾难后恢复运营所需的最长时间","可容忍的最大数据丢失量（以时间计）","备份介质的保存期限","备用站点的启用顺序"],"a":1,"e":"RPO（恢复点目标）定义可接受的数据丢失时间窗，直接驱动备份频率与复制方式（如 RPO 接近 0 需实时同步复制）。RTO 才是时间恢复目标；RPO 与介质保存期、站点启用无直接关系。（OSG 第3章 恢复目标）","f":"3 业务连续性计划","v":[]},{"id":"v2d1-12","d":"域1 安全与风险管理","w":2,"q":"一家欧洲公司向中国用户提供服务并收集其个人信息。评估其合规义务时，最先应该审查的是？","o":["ISO 27001 认证范围","服务所在国及用户所在国的数据保护法律（如 PIPL）","公司内部安全政策","NIST CSF 覆盖度"],"a":1,"e":"跨境数据处理必须首先满足相关司法辖区法律（如中国 PIPL、欧盟 GDPR），再考虑认证与内部标准。ISO/NIST 是最佳实践框架，不替代法律义务；内部政策从属于法律。（OSG 第4章 法律法规）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-13","d":"域1 安全与风险管理","w":3,"q":"公司要求保留所有交易日志至少 5 年以备监管检查。从日志管理角度，5 年后正确的做法是？","o":["永久保留以防万一","按数据保留政策安全销毁（如净化/粉碎）","打包发给云厂商存档","降低权限后继续在线保存"],"a":1,"e":"保留期满的数据应按政策安全销毁，以降低泄露面与存储成本；随意继续保留反而扩大风险。移交第三方需评估合规；在线保留无必要。（OSG 第4章/第5章 数据生命周期）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-14","d":"域1 安全与风险管理","w":3,"q":"组织担心员工因担心被报复而不报告违规行为，最应建立的是？","o":["强制休假制度","匿名举报渠道（Whistleblower 热线）","更严格的上网行为审计","背景调查制度"],"a":1,"e":"匿名/保密举报机制保护报告人，鼓励内部违规曝光，是治理与合规体系（如 SOX 举报人保护）的关键控制。其余选项不能解决'不敢报'的问题。（OSG 第1/4章 报告机制）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-15","d":"域1 安全与风险管理","w":2,"q":"以下哪项属于 GDPR 中'被遗忘权'的正确含义？","o":["监管机构有权遗忘小额违规","数据主体可要求控制者在特定条件下删除其个人数据","被解密的数据不能再加密","执法机构可豁免数据保留义务"],"a":1,"e":"被遗忘权（删除权）指数据主体在数据不再必要、撤回同意等法定条件下，可要求控制者删除其个人数据。其余选项均为杜撰或曲解。（OSG 第4章 隐私法）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-16","d":"域1 安全与风险管理","w":3,"q":"安全治理中，'责任最终承担者'与'日常运营管理者'通常分别是？","o":["CISO；董事会","高级管理层/董事会；CISO 及安全团队","审计师；CISO","数据所有者；数据管理员"],"a":1,"e":"治理模型中最高管理层对安全负最终责任并批准政策与预算；CISO 负责落地执行。审计师独立鉴证；数据所有者/管理员是数据治理角色而非组织级安全责任主体。（OSG 第1章 安全治理）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-17","d":"域1 安全与风险管理","w":2,"q":"某公司规定'所有笔记本必须全盘加密'。该文件属于哪一类？","o":["政策","标准","指南","规程"],"a":1,"e":"标准规定强制性的、可度量的一致性要求（如'必须全盘加密'）；政策是高层概述；指南是建议性；规程是逐步操作说明。（OSG 第1章 文件类型）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-18","d":"域1 安全与风险管理","w":2,"q":"以下哪个概念描述组织'愿意承受多少风险'的正式声明？","o":["风险容量（Capacity）","风险偏好（Appetite）","风险容忍度（Tolerance）","剩余风险（Residual）"],"a":1,"e":"风险偏好是组织为实现目标而愿意接受的风险总量与类型的高层声明；容忍度是对具体场景可接受的偏差范围；容量是理论承受上限；剩余风险是处置后仍存在的风险。（OSG 第1章 风险术语）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-19","d":"域1 安全与风险管理","w":3,"q":"攻击面分析发现：服务器暴露了 10 个端口，其中 6 个业务不需要。最直接的处置措施是？","o":["在端口上部署 IDS","关闭并下线不需要的端口/服务","增加防火墙规则白名单所有端口","对该服务器加密"],"a":1,"e":"减少攻击面的最直接手段是移除不需要的服务与端口（默认关闭）。IDS 只检测不减少暴露面；白名单所有端口没有收敛；加密不减少网络暴露。（OSG 第1章 攻击面管理）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-20","d":"域1 安全与风险管理","w":3,"q":"零日漏洞（0-day）与常规漏洞的主要区别是？","o":["零日漏洞无法被利用","零日漏洞是公开后才被利用的","零日漏洞在厂商发布补丁/公开前即被利用或可被利用","零日漏洞只影响操作系统"],"a":2,"e":"零日漏洞指厂商尚无补丁、公众未知的漏洞，防御方'零天'应对时间。其余说法均错误：零日漏洞危害更大且可被利用，也不仅限操作系统。（OSG 第1章 威胁与脆弱性）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-21","d":"域1 安全与风险管理","w":2,"q":"威胁建模中，STRIDE 分类里'Repudiation'指的是哪类威胁？","o":["攻击者伪装成他人","用户否认执行过某操作","数据被未授权修改","服务被压垮不可用"],"a":1,"e":"R=抵赖，指行为人否认自己的操作，用审计日志、数字签名等对抗。伪装他人对应 Spoofing；篡改对应 Tampering；拒绝服务对应 DoS。（OSG 第1章 威胁建模）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-22","d":"域1 安全与风险管理","w":2,"q":"把风险'投保网络安全险'属于哪种风险处置？","o":["风险缓解","风险转移","风险规避","风险接受"],"a":1,"e":"保险把损失的财务后果转移给第三方，是典型的风险转移。缓解是降低可能性/影响；规避是停止引发风险的活动；接受是有意承担。（OSG 第1章 风险处置）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-23","d":"域1 安全与风险管理","w":3,"q":"某控制措施部署后，风险从'高'降到'中'但仍未消除。残余的那部分风险称为？","o":["总体风险","控制风险","剩余风险","内在风险"],"a":2,"e":"处置/控制实施后仍存在的风险即剩余风险（Residual Risk），须由管理层确认接受或继续处置。总体/内在风险是处置前水平；'控制风险'指控制本身失效的可能。（OSG 第1章 剩余风险）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-24","d":"域1 安全与风险管理","w":3,"q":"内控体系（如 COSO）中，'补偿性控制'的作用是？","o":["替代失效的预防性控制并弥补其缺口","加快系统性能","为主控制提供冗余电力","仅用于财务审计"],"a":0,"e":"补偿性控制在主控制不可行或失效时提供替代保障，弥补残余缺口。它与性能、电力冗余无关，也不仅限财务场景。（OSG 第1章 安全控制类型）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-25","d":"域1 安全与风险管理","w":2,"q":"CIA 三要素中，'宕机导致客户无法下单'主要破坏的是？","o":["保密性","完整性","可用性","真实性"],"a":2,"e":"服务中断使授权用户无法访问资源，属于可用性破坏。保密性是未授权泄露；完整性是未授权篡改。（OSG 第1章 CIA）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-26","d":"域1 安全与风险管理","w":2,"q":"DAD 三元组中，'披露（Disclosure）'对应破坏 CIA 中的哪一项？","o":["可用性","完整性","保密性","不可否认性"],"a":2,"e":"DAD（披露、篡改、破坏）与 CIA 一一对应：披露→保密性、篡改→完整性、破坏→可用性。（OSG 第1章 CIA/DAD）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-27","d":"域1 安全与风险管理","w":3,"q":"审计发现某部门的专用控制与全局政策冲突且成本高昂。若保留该控制，它应被归类为？","o":["主要控制","补偿性控制","检测性控制","纠正性控制"],"a":1,"e":"当无法部署首选/主要控制时使用的替代控制即补偿性控制，常伴随更高成本或更弱效果。检测与纠正是按功能时点分类，与题设场景无关。（OSG 第1章 控制分类）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-28","d":"域1 安全与风险管理","w":3,"q":"安全意识培训属于哪类控制？","o":["预防性-管理性控制","检测性-技术控制","纠正性-物理控制","威慑性-物理控制"],"a":0,"e":"培训改变人的行为、在事前降低违规概率，属预防性；它通过管理制度落实，属管理性控制。不是技术或物理控制，也不在事后起检测/纠正作用。（OSG 第1章 控制分类）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-29","d":"域1 安全与风险管理","w":3,"q":"为满足'员工每年至少完成一次安全培训'的要求，以下证据中最有效的是？","o":["培训签到表扫描件","学习平台记录的完成状态与成绩（含时间戳）","部门经理口头确认","培训预算发票"],"a":1,"e":"审计证据要求可验证、防篡改、关联到人，带时间戳的系统记录最有效。口头确认无证明力；发票只证明花钱未证明完成；纸质签到易伪造且无法证明学习效果。（OSG 第2章 安全意识）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-30","d":"域1 安全与风险管理","w":3,"q":"关键岗位员工连续 5 年未休假、独自掌握核心财务系统权限。强制休假制度在此场景中的主要价值是？","o":["提高员工福利","检测潜在舞弊（如需要他离开才能暴露的违规）","减少人力成本","满足劳动法要求"],"a":1,"e":"强制休假是检测性管理控制：许多舞弊需要作案人持续在岗掩盖，强制离岗可使异常暴露。福利与合规是附带效果，不是安全上的主要目的。（OSG 第2章 人员安全控制）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-31","d":"域1 安全与风险管理","w":3,"q":"开发人员抱怨安全要求拖慢迭代。为在 DevOps 中落地'安全左移'，最有效的治理措施是？","o":["在管理层认可下将安全要求纳入定义完成（DoD）与质量门禁","增加上线前人工渗透测试","豁免内部项目的安全审查","仅对外包项目执行安全评审"],"a":0,"e":"治理层面将安全嵌入流程（DoD、流水线门禁）才能持续、可扩展地左移；仅靠上线前渗透太晚；豁免或只管外包都会留下更大缺口。（OSG 第1章 治理与管理对齐）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-32","d":"域1 安全与风险管理","w":3,"q":"下列关于 PCI DSS 的说法正确的是？","o":["它是各国的成文法律","它是针对支付卡行业的合同性安全标准","它只适用于发卡银行","它由 ISO 制定"],"a":1,"e":"PCI DSS 是支付卡品牌对处理卡数据的商户/服务商施加的合同性合规要求，不是法律，适用于所有存储/处理/传输持卡人数据的实体，由 PCI SSC 维护。（OSG 第4章 行业合规）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-33","d":"域1 安全与风险管理","w":3,"q":"一家医院遭受勒索软件攻击导致病历系统瘫痪。从法律角度，除通报监管机构外还需特别注意的义务是？","o":["《商标法》下的通知义务","个人信息/医疗数据泄露通知义务（如按 HIPAA/个保法）","反垄断申报义务","进出口管制申报"],"a":1,"e":"医疗数据属高度敏感个人信息，泄露/不可用通常触发法定通知义务（HIPAA、GDPR、PIPL 等）。商标、反垄断、进出口管制与本场景无关。（OSG 第4章 隐私与合规）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-34","d":"域1 安全与风险管理","w":2,"q":"以下关于《网络安全法》/关基保护的说法，正确的是？","o":["关键信息基础设施运营者可不履行数据本地化义务","关键信息基础设施运营者应履行更高的安全保护义务并接受重点监管","只有外资企业适用关基条例","等保测评可完全替代关基保护要求"],"a":1,"e":"关键信息基础设施运营者承担更严格的安全保护、检测通报与数据本地化等义务并受重点监管。其余选项均与法规要求相悖。（OSG 第4章 法律法规）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-35","d":"域1 安全与风险管理","w":3,"q":"BCP 项目获得了预算，但业务部门拒绝参与 BIA 访谈。CISO 应如何处置最符合治理原则？","o":["自己替业务部门填写 BIA","将问题升级至发起 BCP 的高层管理者（发起人）寻求支持","暂停项目直到业务部门主动配合","绕过 BIA 直接写计划"],"a":1,"e":"BCP 必须由高层发起并获得业务支持；遇到阻力应升级到发起人/指导委员会解决。替填或绕过 BIA 会导致关键性判断失真；暂停项目同样失职。（OSG 第3章 BCP 组织与范围）","f":"3 业务连续性计划","v":[]},{"id":"v2d1-36","d":"域1 安全与风险管理","w":3,"q":"BIA 中将流程按'关键/重要/一般'排序，主要依据是？","o":["流程负责人的职级","中断对组织使命的影响（安全、财务、声誉、合规等）","流程使用的人数","流程 IT 系统的造价"],"a":1,"e":"BIA 以对组织生存与使命的影响为核心判据，量化 MTD 并排序。职级、用户数、造价都不是关键性本身的度量。（OSG 第3章 BIA）","f":"3 业务连续性计划","v":[]},{"id":"v2d1-37","d":"域1 安全与风险管理","w":3,"q":"'键盘清理者'（shoulder surfing、dumpster diving 等）攻击主要利用的脆弱性是？","o":["加密算法强度不足","人的行为与物理环境弱点","路由协议缺陷","操作系统内核漏洞"],"a":1,"e":"这类攻击针对人员与物理层面的弱点（窥视、翻垃圾获取信息），与技术漏洞无关，需靠意识培训与物理/文档管理对抗。（OSG 第2章 社会工程）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-38","d":"域1 安全与风险管理","w":3,"q":"针对 CEO 的高度定向钓鱼（含精准个人信息的欺诈邮件）称为？","o":["撒网式钓鱼（Phishing）","捕鲸（Whaling）","网址诈骗（Pharming）","语音钓鱼（Vishing）"],"a":1,"e":"针对高管等高价值目标的定向钓鱼称捕鲸（Whaling）。撒网式钓鱼面向大众；Pharming 污染域名解析；Vishing 通过电话实施。（OSG 第2章 社会工程）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-39","d":"域1 安全与风险管理","w":3,"q":"供应链风险管理（SCRM）中，对关键软件供应商最应评估的是？","o":["供应商市场份额","软件物料清单（SBOM）与安全开发实践、漏洞响应能力","供应商办公室装修水平","供应商广告投入"],"a":1,"e":"SCRM 关注供应商产品与过程的安全：SBOM、SDL/DevSecOps 实践、漏洞披露与补丁时效等。市场份额与形象指标与风险无直接关系。（OSG 第2/20章 供应链安全）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d1-40","d":"域1 安全与风险管理","w":3,"q":"管理层问：'我们买的 DLP、EDR、SIEM 齐全，为什么还会被入侵？'从风险治理角度最恰当的回答是？","o":["说明产品有质量问题","工具需配合流程、人员与治理才能有效，且永远存在剩余风险","说明黑客不可防范","说明预算仍然不足"],"a":1,"e":"安全是人员、流程、技术协同的体系，控制只能将风险降到可接受水平，剩余风险必须被识别与管理。归咎产品或预算、宣称不可防范均不成立。（OSG 第1章 风险治理）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-41","d":"域1 安全与风险管理","w":3,"q":"年度风险评估采用'高/中/低'打分。这种风险评估方式称为？","o":["定量评估","定性评估","德尔菲预测","精算定价"],"a":1,"e":"用等级/主观尺度而非货币数值的风险评估是定性评估。定量需产出 AV/SLE/ALE 等数值；德尔菲是专家共识方法的一种实现，不是与定性并列的分类。（OSG 第1章 风险评估方法）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-42","d":"域1 安全与风险管理","w":3,"q":"审计师质疑某政策已 4 年未更新。安全团队应依据什么判断政策是否需要修订？","o":["政策评审周期规定与内外部环境变化（法规、组织、威胁）","是否有人投诉","政策页数是否够多","上次培训的出勤率"],"a":0,"e":"政策应按既定评审周期（通常至少每年）并结合法规、组织结构与威胁变化进行评审与修订。投诉、篇幅、出勤率均非评审依据。（OSG 第1章 政策管理）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-43","d":"域1 安全与风险管理","w":3,"q":"组织希望向客户独立证明其信息安全管理体系符合国际标准。最合适的方式是？","o":["自我声明符合 ISO 27001","通过认可的第三方认证机构进行 ISO 27001 认证审核","购买网络安全保险","参加行业威胁情报共享组织"],"a":1,"e":"向外部提供独立保证需第三方认证审核；自我声明缺乏独立性；保险与情报共享不能证明体系符合标准。（OSG 第1/4章 认证认可）","f":"4 法律、法规和合规","v":[]},{"id":"v2d1-44","d":"域1 安全与风险管理","w":3,"q":"在 COBIT 等治理框架中，'企业治理 of IT'与'IT 管理'的区别，最准确的表述是？","o":["治理由董事会/高管层负责、定方向并评估风险与收益；管理由执行层负责落地实现目标","治理就是技术标准，管理就是人事制度","治理只针对财务，管理只针对 IT","两者完全相同，只是翻译差异"],"a":0,"e":"治理（Governance）在最高层设定方向、权衡风险与收益并监督绩效；管理（Management）按治理意图规划、建设、运行。其余表述均错误。（OSG 第1章 治理与管理）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"v2d1-45","d":"域1 安全与风险管理","w":3,"q":"某 SaaS 客户要求查看渗透测试报告，服务商只提供了一份盖章的'测试通过证明'。从第三方治理角度最合理的改进是？","o":["直接提供完整渗透报告给所有客户","提供摘要保证信（SOC 2 Type II 报告等）证明控制有效性","拒绝任何形式证明","让客户自行测试生产环境"],"a":1,"e":"SOC 2 等独立审计摘要报告可在不泄露可被利用细节的前提下提供合理保证。给所有客户完整报告会泄露攻击路径；拒绝或放任客户测生产都不合理。（OSG 第2章 第三方评估）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"v2d2-1","d":"域2 资产安全","w":3,"q":"一家云服务商存储客户数据。关于'数据控制者'与'数据处理者'的角色，正确的是？","o":["两者责任完全相同","控制者决定处理目的与方式，处理者受控于控制者并按其指示处理数据","处理者法律责任更大","云服务商天然是数据控制者"],"a":1,"e":"按 GDPR 等隐私法，控制者决定处理目的与手段并承担主要合规责任，处理者（如云商）代表控制者处理数据。两者义务不同，责任也不对等。（OSG 第5章 数据角色）","f":"5 保护资产安全","v":[]},{"id":"v2d2-2","d":"域2 资产安全","w":3,"q":"数据所有者（Data Owner）与数据管理员（Data Custodian）的职责划分，正确的是？","o":["所有者负责备份执行；管理员负责分类","所有者负责分类与保护要求；管理员负责日常备份、访问控制等技术执行","两者都由外部审计师担任","所有者是 IT 部门，管理员是业务部门"],"a":1,"e":"数据所有者（通常业务高管）对数据分类与保护要求负最终责任；管理员（通常 IT）执行日常防护操作。选项把职责颠倒或角色错配。（OSG 第5章 数据角色）","f":"5 保护资产安全","v":[]},{"id":"v2d2-3","d":"域2 资产安全","w":3,"q":"某企业数据分类为：公开、内部、秘密、机密。一份文档被错误地标为'公开'并放上官网。最根本的改进措施是？","o":["给官网加 WAF","明确每类数据的定义、判定标准与标注流程并对员工培训","增加 DLP 设备","限制网站上传速度"],"a":1,"e":"误分类源于分类标准与标注流程不清、培训不足；先治理分类体系才能治本。WAF/DLP 是技术补充，不能纠正人对数据级别的判断。（OSG 第5章 数据分类）","f":"5 保护资产安全","v":[]},{"id":"v2d2-4","d":"域2 资产安全","w":3,"q":"政府/军事分类体系（如绝密、机密、秘密、未分类）与商业分类的主要区别是？","o":["商业分类必须完全复制军事分类","政府分类由法律法规强制定义并由政府统一管理，商业分类由各组织按业务自定义","两者没有区别","商业分类更严格"],"a":1,"e":"政府/军事分级是法定、跨机构统一的；商业分级（如公开/内部/机密）由组织按自身业务风险自定义。两者结构与驱动力不同。（OSG 第5章 数据分类）","f":"5 保护资产安全","v":[]},{"id":"v2d2-5","d":"域2 资产安全","w":3,"q":"确定数据资产安全保护水平时应最先考虑的因素是？","o":["数据的分类/敏感性与其对组织的价值","存储设备的品牌","文件格式是否流行","数据大小"],"a":0,"e":"数据分类与价值决定保护投入与控制选择，是资产安全管理的出发点。品牌、格式、大小本身不决定保护水平。（OSG 第5章 资产分类）","f":"5 保护资产安全","v":[]},{"id":"v2d2-6","d":"域2 资产安全","w":3,"q":"数据生命周期'使用'阶段最主要的泄露渠道是？","o":["备份介质丢失","人员在不安全渠道（屏幕、打印、邮件、协作工具）中不当共享/展示数据","磁带消磁不彻底","机房断电"],"a":1,"e":"使用阶段的暴露面主要是人机交互与流转渠道（肩窥、错发邮件、截图外传等）。介质丢失属'存储/归档'阶段问题；消磁属'销毁'阶段。（OSG 第5章 数据生命周期）","f":"5 保护资产安全","v":[]},{"id":"v2d2-7","d":"域2 资产安全","w":3,"q":"企业要求数据在静止（存储）与传输中都受保护。对应的技术组合是？","o":["静态加密 + TLS/传输加密","备份 + 访问控制清单","令牌化 + 打印水印","哈希 + 日志审计"],"a":0,"e":"静止数据用加密（全盘/文件/数据库加密），传输数据用 TLS/IPsec 等信道加密。其余组合不直接提供这两种状态下的机密性。（OSG 第5章 数据保护）","f":"5 保护资产安全","v":[]},{"id":"v2d2-8","d":"域2 资产安全","w":3,"q":"关于加密、哈希与令牌化的区别，正确的是？","o":["哈希可逆，加密不可逆","加密可逆（有密钥可还原）；哈希不可逆；令牌化用随机替身并靠映射表还原","令牌化就是加密","三者完全等同"],"a":1,"e":"加密是可逆的机密性保护；哈希是单向的完整性校验；令牌化以无意义令牌替换敏感值，映射表单独保存。三者性质与用途各不相同。（OSG 第5章 数据保护技术）","f":"5 保护资产安全","v":[]},{"id":"v2d2-9","d":"域2 资产安全","w":3,"q":"为满足 PCI DSS'不得明文存储 PAN'要求，同时希望保留卡号可用于对账查询。最合适的方案是？","o":["直接加密保存并打印明文对账单","令牌化/格式保留加密（FPE），用令牌做日常引用","仅保存 CVV2 备查","用 MD5 哈希卡号"],"a":1,"e":"令牌化或格式保留加密可在不暴露明文的情况下保留可引用格式，是支付行业常用做法。CVV2 任何情况下不得存储；哈希不可逆且 MD5 不安全；打印明文违背目标。（OSG 第5章 数据保护/PCI）","f":"5 保护资产安全","v":[]},{"id":"v2d2-10","d":"域2 资产安全","w":3,"q":"数据脱敏（Masking）中，'静态脱敏'与'动态脱敏'的区别是？","o":["静态脱敏在数据副本上永久替换敏感值；动态脱敏在查询时按权限实时遮蔽原始数据","静态脱敏更慢所以淘汰了","动态脱敏只适用于纸质文件","两者没有区别"],"a":0,"e":"静态脱敏产出脱敏后的数据集（常用于测试环境），动态脱敏按访问者权限在读取时遮蔽生产数据。其余说法错误。（OSG 第5章 数据脱敏）","f":"5 保护资产安全","v":[]},{"id":"v2d2-11","d":"域2 资产安全","w":3,"q":"将生产数据导入测试环境前，最应执行的控制是？","o":["直接复制以保真","脱敏/合成化处理，使测试环境不接触真实敏感数据","仅在测试环境关闭日志","给测试环境换更强密码"],"a":1,"e":"测试环境防护通常弱于生产，必须脱敏或使用合成数据。关闭日志、改密码都不消除数据本身敏感性；直接复制扩大暴露面。（OSG 第5章 测试数据管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-12","d":"域2 资产安全","w":3,"q":"要'彻底'销毁 SSD 上的机密数据，以下哪种方法最可靠？","o":["快速格式化","删除文件并清空回收站","加密擦除（先全盘加密再销毁密钥）或物理粉碎/消解","覆盖写零一次"],"a":2,"e":"SSD 存在磨损均衡与预留空间，常规格式化/删除/单次覆写均无法保证覆盖所有物理单元；加密擦除（销毁密钥）或物理销毁才可靠。（OSG 第5章 数据销毁）","f":"5 保护资产安全","v":[]},{"id":"v2d2-13","d":"域2 资产安全","w":3,"q":"'消磁（Degaussing）'适用的介质与效果，正确的是？","o":["适用于 SSD，效果最好","适用于磁性介质（HDD/磁带），使其数据不可读且驱动器通常报废","适用于光盘","只是把文件名抹掉"],"a":1,"e":"消磁用强磁场破坏磁性介质数据，对 HDD/磁带有效但通常导致硬盘报废；SSD 是闪存不受磁场影响；光盘需粉碎。（OSG 第5章 介质销毁）","f":"5 保护资产安全","v":[]},{"id":"v2d2-14","d":"域2 资产安全","w":3,"q":"审计要求证明一批硬盘已按流程销毁。最有力的证据组合是？","o":["口头保证","销毁服务商的认证资质+链条监管记录（交接单、视频/证书）","购买新硬盘的发票","删除后的目录截图"],"a":1,"e":"可信销毁依赖受监管的完整证据链：有资质的销毁方、交接与销毁记录。口头保证与发票、截图均无证明力。（OSG 第5章 数据销毁管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-15","d":"域2 资产安全","w":3,"q":"数据保存（保留）策略的主要目标是？","o":["尽可能久地保存所有数据","在满足法律/业务要求的前提下界定保留期限，到期安全处置，降低泄露与成本风险","让员工自由决定删除时间","只保存最近一天的数据"],"a":1,"e":"保留策略平衡合规取证需要与最小化原则：法定期限内保留、到期安全销毁。无限保留扩大风险，随意删除违反法规。（OSG 第5章 数据保留）","f":"5 保护资产安全","v":[]},{"id":"v2d2-16","d":"域2 资产安全","w":3,"q":"DR 环境中的备份数据磁带需异地保管。'数据备份的异地存放'主要防范的风险是？","o":["备份数据被勒索软件加密","站点级灾难（火灾、水灾）导致本地备份与生产同时损毁","备份账号弱口令","磁带读取速度慢"],"a":1,"e":"异地备份保证站点性灾难后仍可恢复，是与生产地隔离的核心目的。勒索软件需靠隔离副本/不可变备份防范，属于另一维度。（OSG 第5章 备份管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-17","d":"域2 资产安全","w":3,"q":"勒索软件开始加密备份服务器。哪种备份特性最能保护副本不可被篡改？","o":["增量备份","不可变/离线（air-gapped）备份","压缩备份","加密备份"],"a":1,"e":"不可变存储或离线隔离副本使攻击者无法删改备份，是对抗勒索的关键。增量/压缩与不可篡改无关；仅加密备份时密钥管理在被攻破后同样失守。（OSG 第5章 备份安全）","f":"5 保护资产安全","v":[]},{"id":"v2d2-18","d":"域2 资产安全","w":3,"q":"员工用个人网盘同步含客户名单的工作文档。最合适的技术+管理组合控制是？","o":["封锁全部网络","企业级 DLP/内容识别 + 数据外发政策与审批流程","给员工发更大容量 U 盘","提高网速"],"a":1,"e":"DLP 识别并阻断敏感数据外发，配合政策界定允许的共享方式，兼顾可用性。全面封锁与发 U 盘、提速都不解决问题。（OSG 第5章 数据泄漏防护）","f":"5 保护资产安全","v":[]},{"id":"v2d2-19","d":"域2 资产安全","w":3,"q":"数据权利管理（DRM）/数字版权管理最典型的应用场景是？","o":["数据库高可用","保护电子书、音视频等数字内容的使用权限（打印/复制/时长限制）","服务器负载均衡","代码版本管理"],"a":1,"e":"DRM 通过许可与加密控制数字内容的复制、打印、有效期等使用方式，广泛用于出版与媒体。与高可用、负载均衡、代码管理无关。（OSG 第5章 DRM）","f":"5 保护资产安全","v":[]},{"id":"v2d2-20","d":"域2 资产安全","w":3,"q":"DLP 系统基于'特征匹配 16 位卡号'告警了大量误报。最有效的优化手段是？","o":["直接关闭该规则","引入上下文校验（如 Luhn 校验、关键词/临近词）提高准确率","把告警全标为已处理","缩短日志保存期"],"a":1,"e":"DLP 精度依赖内容识别算法：校验位、关键词、数据标识符组合可显著降低误报。关闭规则或忽略告警引入漏报风险。（OSG 第5章 DLP 调优）","f":"5 保护资产安全","v":[]},{"id":"v2d2-21","d":"域2 资产安全","w":3,"q":"打印水印（带接收者标识的隐形标记）主要提供的价值是？","o":["防止打印","泄露溯源与威慑","提高打印速度","替代加密"],"a":1,"e":"水印用于在泄露发生时追溯来源并形成威慑，属检测/威慑性控制，不能防止打印，也不替代机密性保护。（OSG 第5章 数据泄漏防护）","f":"5 保护资产安全","v":[]},{"id":"v2d2-22","d":"域2 资产安全","w":3,"q":"'数据最小化'原则要求？","o":["尽量少建数据库","仅收集与处理达到声明的业务目的所必需的个人信息","只存明文不加密","禁止一切数据共享"],"a":1,"e":"最小化指收集与保留限于必要范围（GDPR/PIPL 核心原则），以降低泄露影响。它不禁止共享，也不与加密对立。（OSG 第5章 隐私与数据管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-23","d":"域2 资产安全","w":3,"q":"资产管理中，为什么'CMDB/资产清单的准确性'是安全运营的前提？","o":["法规要求所有公司建 CMDB","无法保护你不知道存在的资产：漏洞修复、事件响应、补丁管理都依赖完整资产清单","CMDB 可以替代防火墙","资产清单能提高网速"],"a":1,"e":"影子资产是未打补丁、未监控的主要来源，完整准确的资产清单是漏洞与补丁管理、事件响应的基础。CMDB 是信息库，不是防护设备。（OSG 第5章 资产管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-24","d":"域2 资产安全","w":3,"q":"硬件资产的生命周期管理中，'交接/转岗'环节最应执行的是？","o":["设备留作纪念","清点收回设备与凭据、按新岗位重新授权（权限重置）","把旧设备直接发给新员工使用","格式化公共盘"],"a":1,"e":"人员流动时必须回收设备与凭据并按最小权限重新授权，防止旧权限滞留。直接转用设备会遗留前任数据与账户。（OSG 第5章 资产/介质管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-25","d":"域2 资产安全","w":3,"q":"隐私设计中'目的限制'原则的含义是？","o":["数据只能用于收集时声明的特定目的，不得挪作他用","数据一旦收集即可任意使用","目的限制只针对政府机构","数据可以出售给任何第三方"],"a":0,"e":"目的限制要求数据使用不得超出收集时告知的目的范围，是隐私保护基本原则（GDPR 第5条）。其余说法均违反该原则。（OSG 第5章 隐私原则）","f":"5 保护资产安全","v":[]},{"id":"v2d2-26","d":"域2 资产安全","w":3,"q":"组织在文档上标注'内部资料，禁止外传'但未配套任何技术控制。该标注的作用是？","o":["完整的机密性保护","明确了人员的合规义务（管理性控制），需辅以技术控制才有效","技术性访问控制","可以替代加密"],"a":1,"e":"安全标注属于管理性控制，告知义务与违规后果；真正阻止泄露还需 DLP、加密、权限等技术控制配合。（OSG 第5章 数据标注与控制）","f":"5 保护资产安全","v":[]},{"id":"v2d2-27","d":"域2 资产安全","w":3,"q":"对结构化与非结构化数据实施分类时，最常见的高风险盲区是？","o":["结构化数据库","非结构化数据（共享盘、网盘、邮件、聊天记录、个人终端）","备份系统","核心业务数据库"],"a":1,"e":"非结构化数据分散、复制快、治理弱，是分类与 DLP 的最大盲区。结构化库与备份通常有既定管控。（OSG 第5章 数据发现与分类）","f":"5 保护资产安全","v":[]},{"id":"v2d2-28","d":"域2 资产安全","w":3,"q":"'数据在云端，出境了么？'——关于数据驻留（Data Residency），正确的理解是？","o":["使用海外云服务必然导致数据出境，需评估目的地法律与跨境传输合规","云数据没有物理位置","数据驻留只是性能问题","只要加密就不存在数据驻留问题"],"a":0,"e":"数据驻留指数据物理存储所在司法辖区，使用海外区域云服务可能构成跨境传输，需满足目的地法律评估与传输机制。加密不消除管辖权问题。（OSG 第5章 云与数据主权）","f":"5 保护资产安全","v":[]},{"id":"v2d2-29","d":"域2 资产安全","w":3,"q":"公司允许 BYOD。为保护公司数据同时尊重个人隐私，最合适的方案是？","o":["全盘监控员工手机","容器化/工作区方案，仅管理企业容器内的数据并事先告知范围","禁止 BYOD","给员工手机装个人监控 App"],"a":1,"e":"容器化将企业数据隔离在受管空间，管理边界清晰且需隐私告知，平衡安全与隐私。全盘监控引发法律风险；一刀切禁止影响业务。（OSG 第5章 BYOD 与数据管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-30","d":"域2 资产安全","w":3,"q":"信息与数据的'生命周期'末端处置环节，对纸质机密文件应采用？","o":["普通垃圾袋丢弃","碎纸（交叉切割）或受控焚毁","卖给废品站","集中堆放待处理"],"a":1,"e":"纸质机密文件须交叉碎切或受控焚毁并留记录；丢弃/变卖造成'翻垃圾'泄露风险。（OSG 第5章 介质销毁）","f":"5 保护资产安全","v":[]},{"id":"v2d2-31","d":"域2 资产安全","w":3,"q":"'净化（Sanitization）'与'清除（Clearing）'的区别是？","o":["没有区别","清除用技术手段防基本键盘攻击恢复；净化更彻底，防实验室级恢复，可含销毁","净化就是删除文件","清除等于物理粉碎"],"a":1,"e":"术语上清除（覆写等）抵御普通恢复手段；净化（purging）强度更高（消磁、加密擦除、物理销毁），应对更高威胁的恢复能力。删除文件最弱；物理粉碎属于销毁（destroy），是净化手段之一而非'清除'。（OSG 第5章 介质净化）","f":"5 保护资产安全","v":[]},{"id":"v2d2-32","d":"域2 资产安全","w":3,"q":"云环境中，客户与云商的'共享责任模型'下，IaaS 中数据分类与访问控制的responsibility归属是？","o":["云服务商","客户","监管机构","云代理商"],"a":1,"e":"IaaS 中云商负责基础设施安全，数据、分类、身份与访问管理始终是客户责任。监管机构与代理商不承担该责任。（OSG 第5章 云安全责任）","f":"5 保护资产安全","v":[]},{"id":"v2d2-33","d":"域2 资产安全","w":3,"q":"关于'密钥管理属于数据安全'的说法，以下做法正确的是？","o":["密钥与加密数据存同一数据库便于管理","密钥与数据分离保管，轮换与访问受控并有应急恢复流程","把密钥写进代码注释","所有密钥用同一个并永不变更"],"a":1,"e":"密钥与密文分离存放是基本要求，配合轮换、访问控制与托管/恢复机制。同库存放、硬编码、单一密钥不换均属典型反模式。（OSG 第5章/第7章 密钥管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-34","d":"域2 资产安全","w":3,"q":"要向客户证明其个人数据在其要求下已被删除，除执行删除外还应？","o":["什么都不做","保留删除凭证/审计记录以提供合规证据","把删除任务转包给实习生","让客户自己查"],"a":1,"e":"隐私合规强调可问责性：删除请求的处理需有记录与证据链，以应对监管检查与用户争议。（OSG 第5章 隐私合规）","f":"5 保护资产安全","v":[]},{"id":"v2d2-35","d":"域2 资产安全","w":3,"q":"公司准备把含个人信息的旧数据库退役。以下步骤顺序正确的是？","o":["直接格式化","确认保留义务→依法处理用户权利（导出/删除）→备份留存合规期→净化/销毁并记录","先销毁再审批","发给开发部门当测试数据"],"a":1,"e":"退役前须先核对法定保留、响应用户权利请求，再按保留策略处理备份，最后净化销毁并留存证据；直接格式化、倒序操作或挪作测试都违规。（OSG 第5章 数据生命周期末端）","f":"5 保护资产安全","v":[]},{"id":"v2d2-36","d":"域2 资产安全","w":3,"q":"对备份介质标注与运输管理的最佳实践是？","o":["不标注以免泄密，运输无需记录","按分类标注（不含明文敏感内容），运输有交接记录与授权承运方","把密码写在介质标签上","由任何员工随身携带即可"],"a":1,"e":"介质应可识别但标签不泄露敏感内容；运输须有链条监管（交接记录、授权承运、加密）。无标注难以管理，密码上标签与随意携带是严重违规。（OSG 第5章 介质管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-37","d":"域2 资产安全","w":3,"q":"某员工把'机密'级文件通过公司邮箱发给自己的私人邮箱以便在家办公。从资产安全角度，正确处置与预防组合是？","o":["视而不见","按政策处置违规 + 部署 DLP 阻止邮件外发敏感附件 + 提供合规远程访问替代方案","全面封禁邮箱","给全员发警告邮件即可"],"a":1,"e":"技术（DLP）+ 管理（处置与政策）+ 替代方案（安全远程办公）三管齐下。视而不见和一刀切封禁均不当，仅发警告缺乏强制力。（OSG 第5章 数据防泄漏）","f":"5 保护资产安全","v":[]},{"id":"v2d2-38","d":"域2 资产安全","w":3,"q":"组织采用'公共/内部/受限'三级分类，后发现'内部'级别承载了从通信录到并购草案的一切内容。最佳改进是？","o":["把所有内容都升为'受限'","细化分类定义与判定标准（必要时增设级别），并对高频内容给出示例映射","删除分类体系","只给并购文件单独加密"],"a":1,"e":"一个级别过宽说明定义与判定标准不足，应细化并给出示例；全员升级或放弃分类都不可行，单点加密不解决体系问题。（OSG 第5章 数据分类管理）","f":"5 保护资产安全","v":[]},{"id":"v2d2-39","d":"域2 资产安全","w":3,"q":"在数据安全体系中，'谁最终决定某业务数据的分类级别'？","o":["安全管理员","该数据的数据所有者（业务负责人）","IT 运维","外部审计师"],"a":1,"e":"分类由对数据及其业务情境最了解的数据所有者决定；安全管理员与运维负责落实控制；审计师只做独立评估。（OSG 第5章 数据角色）","f":"5 保护资产安全","v":[]},{"id":"v2d2-40","d":"域2 资产安全","w":3,"q":"发现一台未登记的交换机上连着 HR 系统。从资产管理流程看，根因最可能是？","o":["交换机品牌不好","资产上线流程/变更管理缺失，绕过审批即可接入网络","网线质量问题","HR 系统漏洞"],"a":1,"e":"影子资产的出现说明上线需经登记与安全核验的流程未被强制执行，应通过 NAC 与变更管理闭环。品牌与网线无关；系统漏洞是另一问题。（OSG 第5章 资产管理流程）","f":"5 保护资产安全","v":[]},{"id":"v2d2-41","d":"域2 资产安全","w":3,"q":"为满足'跨境传输个人信息需单独同意/评估'的要求，公司最需要建立的机制是？","o":["数据出境合规评估流程（识别跨境场景、法律依据、告知同意与影响评估）","把服务器涂成蓝色","仅依赖云商的合规声明","禁止一切国际业务"],"a":0,"e":"出境合规要求组织自查跨境场景并履行评估、告知、同意等义务，云商声明不能替代控制者义务。（OSG 第5章 数据跨境）","f":"5 保护资产安全","v":[]},{"id":"v2d2-42","d":"域2 资产安全","w":3,"q":"'保持数据质量/准确性'作为隐私原则，其安全意义在于？","o":["数据越少越准，泄露影响越小且决策更可靠","准确性只关系营销效果","与安全无关","准确性要求保存所有历史版本"],"a":0,"e":"准确的、最小化的数据降低泄露影响并支撑正确决策，是隐私与安全的交集。其余表述片面或错误。（OSG 第5章 隐私原则）","f":"5 保护资产安全","v":[]},{"id":"v2d2-43","d":"域2 资产安全","w":3,"q":"磁带备份保存 7 年后到期，正确的处置是？","o":["直接扔进垃圾桶","按介质销毁流程消磁/粉碎并出具销毁证明","格式化后卖二手","捐赠给学校"],"a":1,"e":"到期磁带含敏感数据，应消磁或物理销毁并留证明；格式化磁带不适用且不彻底，变卖/捐赠造成泄露。（OSG 第5章 介质销毁）","f":"5 保护资产安全","v":[]},{"id":"v2d2-44","d":"域2 资产安全","w":3,"q":"客户要求'彻底删除账户及全部数据'，但反洗钱法规要求交易记录保留 5 年。正确的处理是？","o":["全部删除以尊重用户","在告知范围与依据后，删除非必要个人数据，依法保留义务数据并限制用途","拒绝删除任何数据","删除后从备份悄悄恢复"],"a":1,"e":"法定保留义务优先于删除请求，但须限定保留数据的用途并告知用户依据。全删违法，全拒过度，暗自恢复违背诚信。（OSG 第5章 隐私与保留义务）","f":"5 保护资产安全","v":[]},{"id":"v2d2-45","d":"域2 资产安全","w":3,"q":"对新采购的智能办公设备（带摄像头/麦克风）进行资产安全评估时，最应关注？","o":["设备外观","数据采集范围、传输加密、固件更新与供应商漏洞响应","价格与保修","是否流行"],"a":1,"e":"物联网设备的风险核心在采集的敏感数据及其全生命周期安全（传输、更新、漏洞响应）。外观、价格与流行度与风险无关。（OSG 第5章 资产与IoT）","f":"5 保护资产安全","v":[]},{"id":"v2d3-1","d":"域3 安全架构与工程","w":3,"q":"团队评估两个密码方案。方案A密钥 128 位、方案B密钥 256 位。关于密钥长度与安全的关系，正确的是？","o":["密钥越长安全性一定线性增强，应永远选最长","密钥长度需与算法设计匹配，超过设计的安全冗余后更长密钥不再带来实质安全提升","128 位对称密钥已可被暴力破解","密钥长度与安全无关"],"a":1,"e":"安全性由算法强度与密钥长度共同决定，128 位 AES 在可预见未来足够；超出算法安全级别的更长密钥收益递减。128 位暴力破解不可行。（OSG 第6章 密码学基础）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-2","d":"域3 安全架构与工程","w":3,"q":"为什么对称密码不适合直接在互联网上与陌生方交换密钥？","o":["对称密码速度太慢","对称密钥需双方事先安全共享，而互联网信道不安全，存在'密钥分发问题'","对称密码不能提供机密性","对称密码只能加密数字"],"a":1,"e":"对称算法快但要求双方已持有同一密钥，密钥分发本身需要安全信道——这正是非对称密码与 PKI 要解决的问题。对称加密可以提供机密性且速度更快。（OSG 第6章 对称密码）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-3","d":"域3 安全架构与工程","w":3,"q":"AES-128、AES-192、AES-256 三者的关系是？","o":["三种不同算法","同一 AES 算法的三种密钥长度变体，轮数不同","三种不同分组长度","只有 AES-256 是标准"],"a":1,"e":"AES 是单一标准算法（Rijndael），三种变体仅密钥长度不同并对应 10/12/14 轮。它们都是 FIPS 批准的标准。（OSG 第6章 AES）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-4","d":"域3 安全架构与工程","w":3,"q":"3DES 逐步被弃用的主要原因是？","o":["不能提供机密性","安全性裕度不足（64 位分组易受 Sweet32 等碰撞攻击）且性能差","密钥太长难以管理","被 AES 取代前从未是标准"],"a":1,"e":"3DES 的 64 位分组长度带来生日攻击风险且效率低，NIST 已将其弃用。它曾是标准且能提供机密性，问题在于强度与性能。（OSG 第6章 对称算法）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-5","d":"域3 安全架构与工程","w":3,"q":"工作因素（Work Factor）的含义是？","o":["密码算法的研发成本","破解密码所需付出的努力/资源，是衡量密码强度的实用指标","加密一份文件所需时间","密钥协商的轮数"],"a":1,"e":"工作因素指攻破密码体制所需的努力，随算力增长而变化，决定算法的退役时间。它不是研发成本或单次加解密耗时。（OSG 第6章 密码强度）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-6","d":"域3 安全架构与工程","w":3,"q":"公司需要在不可信通道上分发软件更新，并让设备能验证'确实来自厂商且未被篡改'。最合适的密码原语组合是？","o":["对称加密","数字签名（厂商私钥签名，设备用公钥验签）","哈希但无签名","Base64 编码"],"a":1,"e":"数字签名提供来源认证与完整性（不可否认）。单纯哈希可验证完整性但无法绑定身份；对称加密无身份验证；Base64 只是编码。（OSG 第7章 密码应用）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-7","d":"域3 安全架构与工程","w":3,"q":"RSA 与 ECC 相比，正确的说法是？","o":["ECC 用更短的密钥达到与 RSA 相当的安全强度，适合移动/物联网场景","RSA 密钥越短越安全","ECC 只能用于签名","RSA 已被立法禁止"],"a":0,"e":"ECC 以更短密钥（如 256 位 ≈ RSA 3072 位）提供同级安全，计算与带宽开销更小。RSA 仍广泛使用，ECC 也支持加密与密钥交换。（OSG 第7章 非对称密码）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-8","d":"域3 安全架构与工程","w":3,"q":"混合加密（如 TLS 中）使用非对称算法交换会话密钥、对称算法加密数据，原因是？","o":["对称算法不安全","兼顾非对称的密钥分发能力与对称的加解密性能","非对称算法已失效","法规强制要求"],"a":1,"e":"非对称解决密钥分发，对称提供高性能批量加密，二者结合是工程最优解，不是因为某一方不安全。（OSG 第7章 混合加密）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-9","d":"域3 安全架构与工程","w":3,"q":"数字证书中最核心的绑定关系是？","o":["IP 地址与端口","主体身份与其公钥（由 CA 私钥签名背书）","域名与服务器内存","用户与密码"],"a":1,"e":"X.509 证书将主体身份与公钥绑定，CA 签名提供第三方信任。证书不绑定端口、内存或口令。（OSG 第7章 数字证书）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-10","d":"域3 安全架构与工程","w":3,"q":"员工笔记本上的 Web 证书报错'无法吊销验证'。关于 CRL 与 OCSP，正确的是？","o":["CRL 是实时协议","OCSP 向指定响应者实时查询证书吊销状态，开销小于下载整张 CRL","两者都需下载完整吊销列表","吊销检查可有可无，直接忽略告警"],"a":1,"e":"OCSP 提供单证书实时吊销查询，CRL 是周期性发布的完整列表。忽略吊销错误可能导致使用已被吊销（如私钥泄露）的证书。（OSG 第7章 吊销机制）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-11","d":"域3 安全架构与工程","w":3,"q":"根 CA 私钥应如何保护？","o":["放在 Web 服务器上便于签发","离线保存（HSM/气隙环境），仅在必要时使用并严格记录","发给每位管理员一份备份","存在代码仓库"],"a":1,"e":"根 CA 是信任锚，其私钥必须离线严管（HSM、气隙、多人控制），日常签发由在线的从属/发证 CA 完成。放网上或散发备份会摧毁整个 PKI 信任。（OSG 第7章 PKI 管理）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-12","d":"域3 安全架构与工程","w":3,"q":"使用哈希加盐（salt）存储口令的主要目的是？","o":["加快登录验证","阻止彩虹表等预计算攻击，使相同口令产生不同哈希","让哈希可逆","减少存储空间"],"a":1,"e":"盐使预计算的彩虹表失效，同口令不同盐得到不同摘要。加盐不能使哈希可逆，也与速度、空间优化无关；慢哈希（bcrypt 等）进一步抗暴力破解。（OSG 第7章 口令保护）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-13","d":"域3 安全架构与工程","w":3,"q":"实现'不可否认性'最直接的密码手段是？","o":["对称加密","数字签名","哈希","隐写术"],"a":1,"e":"签名绑定签名者身份与内容，使其无法否认操作。对称加密双方共享密钥无法归责；哈希无身份；隐写只是隐藏存在。（OSG 第7章 不可否认性）","f":"7 PKI 和密码应用","v":[]},{"id":"v2d3-14","d":"域3 安全架构与工程","w":3,"q":"IPsec 的 AH 与 ESP 协议的主要区别是？","o":["AH 更快","ESP 提供机密性（加密），AH 只提供认证与完整性","AH 加密而 ESP 不加密","两者完全相同"],"a":1,"e":"ESP 可提供机密性+认证+完整性，AH 只认证与完整性（不加密，且与 NAT 冲突）。因此 ESP 应用更广。（OSG 第12章/IPsec）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d3-15","d":"域3 安全架构与工程","w":3,"q":"Bell-LaPadula 模型关注的焦点是？","o":["完整性","机密性：简单安全属性与*属性控制信息流（不上读、不下写）","可用性","审计"],"a":1,"e":"BLP 是机密性模型：no read up（简单属性）、no write down（星属性），防泄密。Biba 才管完整性。（OSG 第8章 安全模型）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-16","d":"域3 安全架构与工程","w":3,"q":"Biba 模型中'不下读、不上写'防止的是什么？","o":["机密数据外泄","完整性被破坏（低完整级数据污染高完整级对象）","拒绝服务","口令猜测"],"a":1,"e":"Biba 是完整性模型：主体不能读取更低完整级（不下读）、不能向更高完整级写入（不上写），防止脏数据污染。防泄密是 BLP 的目标。（OSG 第8章 安全模型）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-17","d":"域3 安全架构与工程","w":3,"q":"Clark-Wilson 模型的核心机制是？","o":["访问控制矩阵","TP（转换程序）、CDI（受约束数据项）与 IVP（完整性验证程序）三元组合，通过良定义事务保完整性","信息流格","状态机机密性"],"a":1,"e":"Clark-Wilson 用转换程序与验证程序约束数据操作，实现商业化完整性。矩阵与格分别是 HRU/BLP 等的概念。（OSG 第8章 安全模型）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-18","d":"域3 安全架构与工程","w":2,"q":"Chinese Wall（Brewer-Nash）模型解决的问题是？","o":["军事分级","利益冲突：主体访问某方数据后，被禁止访问其竞争方数据","数据库性能","网络分段"],"a":1,"e":"中国墙模型按访问历史动态调整权限，防止咨询/金融场景中的利益冲突。与分级、性能、分段无关。（OSG 第8章 安全模型）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-19","d":"域3 安全架构与工程","w":3,"q":"'纵深防御'的核心思想是？","o":["部署多层异构控制，使单一控制失效不致全局失守","把防火墙部署三层","只依赖最强的单一控制","加密所有数据"],"a":0,"e":"纵深防御是分层、多样的控制组合（管理/技术/物理），避免单点失效。多重相同设备≠纵深；依赖单一强控制违背该原则。（OSG 第8章 安全设计原则）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-20","d":"域3 安全架构与工程","w":3,"q":"Saltzer-Schroeder 设计原则中'最小特权'与'完全仲裁'分别是？","o":["每次访问都检查授权；权限最小化","权限最小化；每次对对象的访问都必须经过授权检查","加密最小化；日志完整化","分层防御；开放设计"],"a":1,"e":"最小特权=只授必要权限；完全仲裁=所有访问必须校验授权，不可有旁路。选项顺序要分清。（OSG 第8章 安全设计原则）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-21","d":"域3 安全架构与工程","w":3,"q":"安全设计原则'开放设计（Open Design）'的含义是？","o":["系统配置对所有人公开","系统安全性不应依赖算法或设计的保密（Kerckhoffs 原则），秘密只存在于密钥","源码必须开源","接口文档公开"],"a":1,"e":"开放设计主张安全不靠隐蔽（security through obscurity），仅密钥保密。与开源义务、文档公开无关。（OSG 第8章 设计原则）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-22","d":"域3 安全架构与工程","w":3,"q":"共用账号在多人间使用，最直接违反的设计/运营原则是？","o":["默认失败开放","责任无法绑定到个人（违背可归责性/不可否认）","开放设计","心理可接受性"],"a":1,"e":"共享账号使行为无法归责，破坏审计与不可否认性，应一人一账号。（OSG 第8章/第13章 身份与问责）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-23","d":"域3 安全架构与工程","w":3,"q":"TOCTOU（检查时刻与使用时刻）漏洞的成因是？","o":["加密密钥过短","授权检查与实际操作之间存在时间窗，对象状态可能被改变","口令太简单","日志没有加密"],"a":1,"e":"TOCTOU 指检查与使用之间资源被替换/修改，需通过原子操作/锁定等设计消除窗口。与密钥长度、口令强度无关。（OSG 第8/9章 系统弱点）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-24","d":"域3 安全架构与工程","w":3,"q":"'故障安全默认（Fail Securely）'原则要求系统在异常时如何表现？","o":["拒绝进入安全状态之外的操作（默认拒绝访问）","自动放行以保可用","重启后清除所有日志","切换为明文通信"],"a":0,"e":"异常/失败时应进入安全状态（默认拒绝），而非以可用性为代价开放访问。清除日志、降级明文都是危险行为。（OSG 第8章 设计原则）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-25","d":"域3 安全架构与工程","w":3,"q":"缓冲区溢出攻击的根本成因是？","o":["网络带宽不足","程序向固定长度缓冲区写入超过其容量的数据，覆盖相邻内存","密码算法弱","DNS 配置错误"],"a":1,"e":"溢出源于缺乏边界检查，可覆盖返回地址执行任意代码；对策包括安全语言、DEP/ASLR、堆栈保护等。（OSG 第9章/第21章 缓冲区溢出）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-26","d":"域3 安全架构与工程","w":3,"q":"DEP/NX、ASLR 等缓解措施的定位是？","o":["彻底消灭内存破坏漏洞","纵深防御中的缓解层，降低漏洞可利用性，不根除漏洞","替代安全编码","网络访问控制"],"a":1,"e":"编译器/OS 缓解措施提高利用难度，属纵深防御；根除需安全开发与打补丁。它们不替代安全编码。（OSG 第9章 系统加固）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-27","d":"域3 安全架构与工程","w":3,"q":"'沙箱'提供的安全能力是？","o":["加密沙箱内数据","限制代码可访问的资源与权限范围，隔离其失败/恶意行为","加速程序运行","防 DDoS"],"a":1,"e":"沙箱通过限制权限与隔离环境控制代码影响面，是最小特权的运行时实现。与加密、性能、抗 DDoS 无关。（OSG 第9章 隔离与沙箱）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-28","d":"域3 安全架构与工程","w":3,"q":"可信计算基（TCB）的定义是？","o":["系统中所有代码的总和","实现安全策略的所有硬件、固件与软件元件的集合","最贵的设备","防火墙规则集"],"a":1,"e":"TCB 是执行安全策略的核心集合，应尽量小且可验证。它不是全部代码，更与价格、防火墙无关。（OSG 第8章 可信计算基）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-29","d":"域3 安全架构与工程","w":3,"q":"'安全边界（Security Perimeter）'与 TCB 的关系是？","o":["安全边界是网络防火墙的别称","安全边界划分 TCB 与非 TCB 元件的界线，穿越边界的输入需受控校验","边界内不允许任何通信","边界就是机房围墙"],"a":1,"e":"安全边界是概念界线，分隔 TCB 与外部元件，穿越数据须校验，防旁路。它不是物理墙或防火墙本身。（OSG 第8章 TCB 与边界）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-30","d":"域3 安全架构与工程","w":3,"q":"参考监视器（Reference Monitor）概念要求是？","o":["可绕过的、可选的校验模块","不可绕过、防篡改且足够小到可验证，对每次访问做仲裁","只审计管理员操作","仅在网络层生效"],"a":1,"e":"参考监视器三性质：不可绕过（完全仲裁）、防篡改、可验证性。它是访问强制执行的抽象，须覆盖所有访问。（OSG 第8章 参考监视器）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-31","d":"域3 安全架构与工程","w":3,"q":"'状态机模型'证明系统安全的方法是？","o":["测试所有输入输出","证明系统在所有状态下均满足安全属性（安全状态间迁移），故始终安全","加密所有状态","禁止状态迁移"],"a":1,"e":"状态机安全模型通过证明初始状态安全且迁移保持安全属性，得到'始终安全'的形式化结论。测试无法穷举。（OSG 第8章 状态机模型）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-32","d":"域3 安全架构与工程","w":3,"q":"信息流模型（如 BLP）与'访问矩阵模型'的主要区别是？","o":["信息流模型关注信息在级别间的流动路径；访问矩阵刻画主体-客体权限关系","两者只是名称不同","信息流模型不涉及安全","访问矩阵只用于数据库"],"a":0,"e":"信息流模型（格模型）约束数据流向；访问矩阵（HRU/Take-Grant）描述主体对客体的权限。二者视角不同。（OSG 第8章 安全模型分类）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-33","d":"域3 安全架构与工程","w":3,"q":"某银行核心系统要求'任何一笔账务修改必须双人复核且留痕'。最贴合的安全模型是？","o":["Bell-LaPadula","Clark-Wilson（良定义事务+职责分离）","Brewer-Nash","Graham-Denning"],"a":1,"e":"Clark-Wilson 通过 TP、访问三元组和职责分离实现事务级完整性，与双人复核场景吻合。BLP 管机密性；中国墙管利益冲突。（OSG 第8章 完整性模型）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-34","d":"域3 安全架构与工程","w":3,"q":"关于'隐蔽通道（Covert Channel）'，正确的说法是？","o":["加密的通信线路","不通过正常访问控制机制传递信息的通路（如通过资源占用、时间差异传信）","光纤专线","备份通道"],"a":1,"e":"隐蔽通道绕过安全策略间接泄露信息（时间/存储通道），形式化模型也难以完全消除，只能限速与监控。与加密线路无关。（OSG 第8章 隐蔽通道）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-35","d":"域3 安全架构与工程","w":3,"q":"聚合攻击（aggregation）与推理（inference）的区别是？","o":["推理是从低级片段组合推导出高级信息；聚合是收集大量低敏感数据后整体价值升高","两者是同一概念的不同译名","聚合只针对个人数据","推理只发生在数据库内"],"a":0,"e":"推理：组合授权可见的细节推出受限信息；聚合：低价值数据海量汇聚后成为高价值目标。防推理靠上下文/历史控制，防聚合靠限集。（OSG 第8章 推理与聚合）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d3-36","d":"域3 安全架构与工程","w":3,"q":"虚拟化/容器环境中的'虚拟机逃逸'指？","o":["VM 被迁移到另一台宿主机","攻击者从客户 VM 突破 hypervisor 隔离获得宿主或其他 VM 权限","VM 网络断开","容器镜像被删除"],"a":1,"e":"逃逸即突破虚拟化隔离边界，危害宿主与同驻 VM，需 hypervisor 加固、补丁与最小暴露面。迁移、断网、删镜像均不是逃逸。（OSG 第9章 虚拟化风险）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-37","d":"域3 安全架构与工程","w":3,"q":"IoT 设备最常见的安全短板是？","o":["算力太强","弱默认口令、不更新固件、明文通信与管理接口暴露","价格便宜","颜色单一"],"a":1,"e":"IoT 风险集中在默认凭据、固件无人维护、明文协议与暴露管理面，需网络隔离与替换策略。算力与外观无关。（OSG 第9章 嵌入式与IoT）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-38","d":"域3 安全架构与工程","w":3,"q":"工业控制系统（ICS/SCADA）安全设计的首要原则通常是？","o":["优先保密性","优先可用性与安全性（SAFETY>可用），通过分层隔离（Purdue 模型）保护","优先匿名性","与 IT 完全同策略"],"a":1,"e":"ICS 中人身与生产安全优先，强调分区分层、深度防御与补丁窗口管理，不能照搬 IT 策略。匿名性不是目标。（OSG 第9章 工控安全）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-39","d":"域3 安全架构与工程","w":3,"q":"分布式系统中的'竞态条件'漏洞可通过哪种设计缓解？","o":["增加日志","使用锁/原子操作保证关键区互斥","更换编程语言即可彻底避免","提高 CPU 主频"],"a":1,"e":"竞态条件源于非原子的检查-使用序列，需互斥锁/事务等同步机制。日志只帮助发现，换语言/提频不解决并发正确性。（OSG 第9章 系统漏洞）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-40","d":"域3 安全架构与工程","w":3,"q":"某应用将用户输入拼进 SQL 查询。该漏洞类别与根治措施是？","o":["XSS；过滤输出","SQL 注入；参数化查询/预编译语句","CSRF；加令牌","越权；加防火墙"],"a":1,"e":"拼接 SQL 导致注入，根治是参数化查询+输入校验+最小权限数据库账号。XSS/CSRF 是其他类别。（OSG 第21章 应用攻击）","f":"9 安全漏洞、威胁和对策","v":[]},{"id":"v2d3-41","d":"域3 安全架构与工程","w":3,"q":"关于 Kerckhoffs 原则在现代系统中的体现，正确的是？","o":["AES 算法公开但密钥保密，安全性依赖密钥而非算法保密","公司应保密自研加密算法以保证安全","算法公开=系统不安全","仅军事系统适用该原则"],"a":0,"e":"现代密码学依赖公开评审的算法与保密的密钥；保密自研算法（security by obscurity）通常脆弱。算法公开正是强度经过检验的原因。（OSG 第6章 密码学原则）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-42","d":"域3 安全架构与工程","w":3,"q":"一次性密码本（OTP）'理论不可破'成立的前提不包括？","o":["密钥真随机","密钥只用一次","密钥与明文等长并安全分发","使用 AES 加密密钥"],"a":3,"e":"OTP 的无条件安全要求：密钥真随机、仅用一次、与明文等长且安全分发；与使用何种分组算法无关（OTP 是异或运算）。（OSG 第6章 一次性密码本）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-43","d":"域3 安全架构与工程","w":3,"q":"分组密码的'工作模式'（如 CBC、GCM）存在的意义是？","o":["美化标准名称","将分组算法扩展到任意长度消息并提供链接/认证等性质","替代密钥交换","降低密钥长度"],"a":1,"e":"工作模式处理多分组消息（链接、填充、并行）并可附加认证（GCM 的 AEAD）。它们不替代密钥交换，也不改变密钥长度。（OSG 第6章 密码模式）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-44","d":"域3 安全架构与工程","w":3,"q":"为什么 ECB 模式不适合加密任何结构化/图像数据？","o":["速度太慢","相同明文分组产生相同密文分组，泄露数据模式","不能加密长消息","不使用密钥"],"a":1,"e":"ECB 独立加密各分组，明文模式在密文中可见（经典'企鹅图'问题），应使用 CBC/CTR/GCM 等。（OSG 第6章 工作模式）","f":"6 密码学和对称密钥算法","v":[]},{"id":"v2d3-45","d":"域3 安全架构与工程","w":3,"q":"安全架构评审中，要求'以攻击者视角检验设计'的活动称为？","o":["漏洞扫描","威胁建模（如 STRIDE/攻击树）","渗透测试","合规审计"],"a":1,"e":"威胁建模在设计阶段系统枚举威胁并驱动对策，是架构级安全活动；扫描与渗透针对已实现系统；合规审计对照要求。（OSG 第8/20章 威胁建模）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"v2d4-1","d":"域4 通信与网络安全","w":3,"q":"按 OSI 模型，路由器、交换机、网桥分别工作在哪一层？","o":["物理/数据链路/网络","网络/数据链路/数据链路","传输/网络/会话","应用/表示/会话"],"a":1,"e":"路由器基于 IP 工作在网络层（第3层），交换机基于 MAC 工作在数据链路层（第2层），网桥同样是二层设备。（OSG 第11章 OSI 模型与设备）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-2","d":"域4 通信与网络安全","w":3,"q":"OSI 第4层（传输层）的两大核心协议 TCP 与 UDP 的关键区别是？","o":["UDP 面向连接且可靠","TCP 面向连接、可靠有序；UDP 无连接、轻量但不保证交付","两者完全相同","TCP 更快"],"a":1,"e":"TCP 有握手、确认与重传保证可靠有序；UDP 牺牲可靠性换取低开销，适合音视频/DNS。可靠性即来自重传机制，速度通常 UDP 更快。（OSG 第11章 传输层）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-3","d":"域4 通信与网络安全","w":3,"q":"TCP 三次握手的正确顺序是？","o":["SYN → SYN/ACK → ACK","ACK → SYN → SYN","SYN → ACK → SYN/ACK","三次 FIN"],"a":0,"e":"建立连接：客户端 SYN，服务端 SYN/ACK，客户端 ACK。其余顺序均不成立。（OSG 第12章 TCP 连接）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-4","d":"域4 通信与网络安全","w":3,"q":"SYN Flood 攻击利用的弱点是？","o":["DNS 缓存","三次握手中服务端为半开连接分配资源，攻击者不回 ACK 耗尽资源","TLS 证书验证","路由表溢出"],"a":1,"e":"SYN 泛洪制造大量半开连接耗尽服务端连接表，可用 SYN Cookie、代理或速率限制缓解。与 DNS/证书/路由无关。（OSG 第12章 拒绝服务）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-5","d":"域4 通信与网络安全","w":3,"q":"Smurf/Fraggle 类放大攻击主要滥用的机制是？","o":["将 ICMP/UDP 请求的源地址伪造成受害者，使大量主机回应受害者（放大与反射）","弱口令","明文口令传输","ARP 缓存"],"a":0,"e":"反射放大攻击伪造源 IP 让众多中间主机响应受害者，需运营商入口过滤（BCP38）与速率限制。与口令、ARP 无关。（OSG 第12章 DoS 攻击）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-6","d":"域4 通信与网络安全","w":3,"q":"ARP 欺骗（ARP spoofing）的攻击对象与位置是？","o":["同一二层广播域内的主机 ARP 缓存","跨 Internet 的路由表","DNS 权威服务器","TLS 会话"],"a":0,"e":"ARP 无认证，攻击者在同一广播域内冒充网关 MAC 实施中间人，缓解靠动态 ARP 检测、端口安全或加密。（OSG 第12章 网络攻击）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-7","d":"域4 通信与网络安全","w":3,"q":"攻击者向 DNS 解析器注入伪造响应，将用户引向恶意站点。这类攻击称为？","o":["DNS 缓存投毒（Pharming）","Vishing","Smishing","Typosquatting"],"a":0,"e":"DNS 投毒污染解析缓存实现劫持（Pharming）；Vishing/Smishing 是电话/短信钓鱼；Typosquatting 是仿冒域名注册。（OSG 第12章 网络攻击）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-8","d":"域4 通信与网络安全","w":3,"q":"NAT 的主要作用与附带安全效果是？","o":["加速路由；无安全作用","在私有地址与公网地址间转换以节约 IPv4 地址；附带隐藏内网结构","加密流量；防所有攻击","过滤应用层内容；防病毒"],"a":1,"e":"NAT 解决地址枯竭并映射端口，顺带隐藏内部拓扑，但它不是防火墙也不加密，不能视为安全控制本身。（OSG 第11章 网络地址转换）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-9","d":"域4 通信与网络安全","w":3,"q":"有状态防火墙与无状态包过滤的主要区别是？","o":["有状态防火墙跟踪连接状态（如已建立会话的回包直接放行），可实施更精细策略","有状态防火墙只能看端口","无状态防火墙更安全","有状态防火墙工作在应用层"],"a":0,"e":"状态表记录会话上下文，使回包匹配更准确并可阻断异常标志组合。它仍在网络/传输层，并非不如无状态。（OSG 第11章 防火墙类型）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-10","d":"域4 通信与网络安全","w":3,"q":"下一代防火墙（NGFW）区别于传统防火墙的核心能力是？","o":["更快的转发速率","集成应用识别、用户身份、IPS 与内容检测（应用层感知）","只能工作在二层","仅支持 IPv6"],"a":1,"e":"NGFW 在端口/协议之上做应用与用户感知、深度包检测与 IPS 联动，而不是单纯提速。（OSG 第11章 防火墙技术）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-11","d":"域4 通信与网络安全","w":3,"q":"微分段（Microsegmentation）的主要安全价值是？","o":["减少 IP 地址数量","将东西向流量按工作负载细粒度隔离，限制攻击者在内网的横向移动","替代终端杀毒","提高无线信号强度"],"a":1,"e":"微分段把边界细化到工作负载级，阻断横向移动；不替代终端防护，也与地址节约、无线无关。（OSG 第11章 网络分段）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-12","d":"域4 通信与网络安全","w":3,"q":"零信任网络的核心原则是？","o":["内网默认可信，外网不可信","永不信任、始终验证：对每次访问按身份、设备与上下文持续授权，不因位置而豁免","一次性登录后永久信任","只对远程办公启用 MFA"],"a":1,"e":"零信任否定隐式信任（含内网），基于身份+设备+环境持续评估授权。一次性信任与只保护远程都违背其原则。（OSG 第11章 零信任）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-13","d":"域4 通信与网络安全","w":3,"q":"蜜罐（Honeypot）在防御体系中的定位是？","o":["生产服务的高可用副本","诱捕与情报收集（检测/威慑），不承载真实业务","替代 IDS","加密网关"],"a":1,"e":"蜜罐以虚假目标吸引攻击，产出告警与攻击情报，属检测/研究类控制；它不承载业务也不能替代 IDS。（OSG 第11章 网络安全技术）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-14","d":"域4 通信与网络安全","w":3,"q":"IDS 与 IPS 的根本差异是？","o":["IDS 旁路部署、检测告警；IPS 串联部署、可阻断流量","IDS 比 IPS 更快","IPS 只能检测蠕虫","两者部署位置相同"],"a":0,"e":"部署方式决定能力：旁路 IDS 只告警，串联 IPS 可实时阻断（也因此有误断风险）。（OSG 第11章 IDS/IPS）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-15","d":"域4 通信与网络安全","w":3,"q":"基于特征的检测与基于异常的检测的优缺点对比，正确的是？","o":["特征检测误报低但漏检新威胁；异常检测可发现未知威胁但误报较多","特征检测能发现零日且无误报","异常检测从不误报","两者无差别"],"a":0,"e":"特征匹配准确但依赖已知签名；异常建模覆盖未知攻击却易受基线漂移影响产生误报，实践常结合使用。（OSG 第11章 检测技术）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-16","d":"域4 通信与网络安全","w":3,"q":"VPN 使用 IPSec 隧道模式与传输模式的区别是？","o":["隧道模式加密并封装整个原始 IP 包（新增外层头），常用于站点到站点；传输模式只保护载荷，常用于端到端","隧道模式不加密","传输模式隐藏源 IP","两者只是速度不同"],"a":0,"e":"隧道模式整体封装原始包，适合网关间互联；传输模式保留下原 IP 头只加密载荷，适合主机间。加密强度相同。（OSG 第12章 IPSec 模式）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-17","d":"域4 通信与网络安全","w":3,"q":"TLS 1.3 相对旧版本的安全改进不包括？","o":["删除弱密码套件（如 RSA 密钥交换、CBC、RC4）","强制前向保密","握手更快（1-RTT）","支持明文回退以兼容旧浏览器"],"a":3,"e":"TLS1.3 移除弱算法并强制 PFS、精简握手；不支持也不应提供明文回退，回退恰是被移除的风险。（OSG 第12章 TLS）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-18","d":"域4 通信与网络安全","w":3,"q":"为什么 SSH 应替代 Telnet/FTP 进行远程管理？","o":["SSH 更快","Telnet/FTP 明文传输口令与数据，SSH 提供加密与认证的通道","Telnet 已无客户端","FTP 不能传文件"],"a":1,"e":"Telnet/FTP/HTTP 等明文协议会泄露凭据，应换用 SSH/SFTP/HTTPS 等加密替代。速度与客户端 availability 不是原因。（OSG 第12章 安全通信）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-19","d":"域4 通信与网络安全","w":3,"q":"邮件防伪造的三种机制 SPF、DKIM、DMARC 的配合关系是？","o":["三者互不相干","SPF 验证发信 IP 授权、DKIM 签名验证内容完整性、DMARC 汇聚两者并规定失败处置与报告","DMARC 取代 SPF 与 DKIM","SPF 加密邮件正文"],"a":1,"e":"SPF 管发送源授权、DKIM 提供签名验证、DMARC 对齐两者并声明策略（隔离/拒绝）与报告。DMARC 依赖前两者而非取代。（OSG 第12章 电子邮件安全）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-20","d":"域4 通信与网络安全","w":3,"q":"无线安全：为什么开放 Wi-Fi 上直接输入网银口令风险大，而 HTTPS 能显著缓解？","o":["HTTPS 无风险","开放网络可被嗅探/劫持；HTTPS 端到端加密并验证服务器身份，防窃听与中间人","Wi-Fi 协议自带加密","HTTPS 隐藏你连了哪个网站"],"a":1,"e":"开放 Wi-Fi 无链路加密，攻击者可嗅探或劫持；TLS 提供机密性与服务器认证。HTTPS 并非无风险（仍需防钓鱼），也不隐藏目标域名（SNI/DNS 可见）。（OSG 第12章 安全通信）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-21","d":"域4 通信与网络安全","w":3,"q":"WPA3 相比 WPA2 的关键改进是？","o":["速度提升 10 倍","SAE 替代 PSK 抗离线字典攻击，并强制保护管理帧等","支持更多客户端","取消了预共享密钥"],"a":1,"e":"WPA3 用 SAE（同时认证）抵御离线口令猜测，并引入 PMF 等强化。速度与容量不是重点，也未取消口令机制。（OSG 第11章 无线安全）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-22","d":"域4 通信与网络安全","w":3,"q":"企业无线部署中，'邪恶双子（Evil Twin）'攻击指的是？","o":["克隆合法 AP 的 SSID 诱使终端连接，实施中间人","两个合法 AP 抢同一信道","双网卡负载均衡","MAC 随机化"],"a":0,"e":"伪造同名 AP 骗取关联后劫持流量，需 802.1X/证书验证网络身份（双向认证）防御。（OSG 第12章 无线攻击）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-23","d":"域4 通信与网络安全","w":3,"q":"802.1X 采用的架构中，'请求者、认证者、认证服务器'通常分别对应？","o":["客户终端；交换机/AP；RADIUS 服务器","交换机；路由器；DHCP","AP；终端；DNS","RADIUS；终端；交换机"],"a":0,"e":"802.1X 端口准入： supplicant（终端）、authenticator（交换机/AP）、authentication server（RADIUS）。（OSG 第11章/第14章 网络准入）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-24","d":"域4 通信与网络安全","w":3,"q":"SDN 架构将'控制平面'与'数据平面'分离带来的安全影响是？","o":["彻底消除网络攻击","控制器成为高价值单点，需重点保护其 API、认证与可用性","不再需要防火墙","流量不再需要加密"],"a":1,"e":"集中控制器是策略大脑，须防未授权 API 调用与 DoS；平面分离带来可编程性但引入新攻击面，并非消除攻击。（OSG 第11章 SDN）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-25","d":"域4 通信与网络安全","w":3,"q":"VLAN 的安全作用与局限是？","o":["VLAN 是安全边界，跨 VLAN 无需再防护","VLAN 提供广播域隔离，但同 VLAN 内流量可见且存在跳跃攻击风险，不能替代防火墙策略","VLAN 可以加密流量","VLAN 只用于无线网络"],"a":1,"e":"VLAN 做逻辑分段收敛广播域，但 VLAN 间仍需 ACL/防火墙，且需防 VLAN 跳跃（如双重标记）。VLAN 不加密。（OSG 第11章 分段与VLAN）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-26","d":"域4 通信与网络安全","w":3,"q":"跨站请求伪造（CSRF）与 XSS 的区别是？","o":["CSRF 利用浏览器自动携带 Cookie 冒充用户发起请求；XSS 向页面注入恶意脚本在受害者浏览器执行","两者相同","CSRF 是服务器被完全入侵","XSS 只偷密码，CSRF 只改密码"],"a":0,"e":"CSRF 是'借用户之手'发起被信任请求（防：CSRF 令牌、SameSite）；XSS 是注入脚本执行（防：输出编码、CSP）。（OSG 第21章 Web 攻击）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-27","d":"域4 通信与网络安全","w":3,"q":"DHCP 饥饿（DHCP Starvation）攻击的后果与缓解是？","o":["耗尽地址池使合法客户端无法入网；用 DHCP Snooping/端口限速缓解","加密 DHCP 流量","提高地址池容量即可根治","关闭 DHCP 改用手工配置无线客户端"],"a":0,"e":"攻击者耗尽租约拒绝服务，DHCP Snooping 信任端口+速率限制是标准缓解。扩容只是拖延。（OSG 第12章 网络攻击）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-28","d":"域4 通信与网络安全","w":3,"q":"MAC 泛洪攻击的目标是？","o":["使交换机 CAM 表溢出退化为泛洪，从而嗅探本端口外流量","修改路由协议","破解 WPA 密钥","耗尽 DNS 解析器"],"a":0,"e":"CAM 表被伪造源 MAC 填满后交换机广播所有帧，攻击者借机窃听；对策是端口安全限制可学 MAC 数。（OSG 第12章 二层攻击）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-29","d":"域4 通信与网络安全","w":3,"q":"企业计划把 Web 服务发布到互联网，应放置在哪个区域？","o":["内网核心区","DMZ（非军事区/边界子网）","办公终端 VLAN","管理网络"],"a":1,"e":"对外服务置于 DMZ，由边界防火墙分别控制外→DMZ 与 DMZ→内的最小化策略，避免直接暴露内网。（OSG 第11章 网络分区设计）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-30","d":"域4 通信与网络安全","w":3,"q":"网络隐蔽信道中，'域前置（Domain Fronting）'常被用于？","o":["加速 CDN 访问","恶意软件借助合法高信誉域名（如 CDN TLS SNI 差异）规避流量检测与封锁","压缩传输数据","DNS 负载均衡"],"a":1,"e":"域前置让流量看似访问知名域，绕过基于 SNI/Hostname 的管控，需要行为与内容层面的检测应对。（OSG 第12章 隐蔽通信）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-31","d":"域4 通信与网络安全","w":3,"q":"路由协议认证（如 OSPF/BGP MD5 或 TCP-AO）防的攻击是？","o":["口令嗅探","伪造路由通告/邻居会话（路由欺骗、黑洞、劫持）","MAC 泛洪","ARP 欺骗"],"a":1,"e":"为路由协议报文加认证可防攻击者伪装邻居注入恶意路由。它不直接防 ARP/MAC 这类二层攻击。（OSG 第11章 路由安全）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-32","d":"域4 通信与网络安全","w":3,"q":"IPv6 部署中常见的安全误区是？","o":["IPv6 天然加密所以无需防护","认为'没人用 IPv6'而忽视其暴露面，未对 IPv6 施加与 IPv4 同等的过滤与监控","IPv6 无地址可用","IPv6 不支持防火墙"],"a":1,"e":"双栈环境中 IPv6 常被遗漏管控形成绕行通道，应同等过滤、认证与监控。IPv6 不自动加密（IPsec 可选支持）。（OSG 第11章 IPv6 安全）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-33","d":"域4 通信与网络安全","w":3,"q":"负载均衡器实现高可用的同时，对安全的贡献是？","o":["加密所有流量","吸收部分流量型 DoS、隐藏后端真实 IP、可串联 WAF 卸载 SSL 统一检测","替代 IDS","自动修补漏洞"],"a":1,"e":"LB 可摊薄洪水攻击影响、保护后端拓扑并作为检测卸载点，但不加密流量本身、不替代 IDS 或补丁管理。（OSG 第11章 网络服务高可用）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-34","d":"域4 通信与网络安全","w":3,"q":"网络流量可视化'元数据'（五元组、DNS 查询、SNI）的安全价值是？","o":["侵犯隐私无价值","即使流量加密，元数据也可支撑 C2 通道检测、资产发现与调查取证","只能用于计费","可还原明文内容"],"a":1,"e":"加密普及后元数据是检测与取证的重要线索，但应按最小必要与隐私约束使用；元数据不能还原明文。（OSG 第11章 网络监控）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-35","d":"域4 通信与网络安全","w":3,"q":"PPTP 与 L2TP/IPSec、OpenVPN、WireGuard 的对比，正确的是？","o":["PPTP 最安全应优先使用","PPTP 存在严重设计缺陷已弃用，应使用 L2TP/IPSec、OpenVPN 或 WireGuard 等现代方案","WireGuard 不加密","L2TP 自身提供强加密"],"a":1,"e":"PPTP 的 MS-CHAPv2 等可被破解已淘汰；L2TP 本身不加密需配 IPSec；WireGuard 使用现代密码且代码精简。（OSG 第12章 VPN 技术）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-36","d":"域4 通信与网络安全","w":3,"q":"邮件网关拦截了带宏的 Office 附件。这类控制主要针对的攻击链是？","o":["鱼叉钓鱼投递→宏执行→恶意载荷下载（恶意软件初始访问）","DNS 反射放大","无线 Evil Twin","MAC 泛洪"],"a":0,"e":"带宏附件是钓鱼/勒索常见初始载体，网关需结合附件沙箱、宏禁用与用户意识多层防御。（OSG 第21章 恶意代码/第12章 邮件安全）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-37","d":"域4 通信与网络安全","w":3,"q":"IPS 阻断了正常业务并造成故障。复盘时最应优先审视的是？","o":["直接永久关闭该特征","签名调优：真伪阳性分析、例外管理、灰度（检测模式）上线流程","更换全部网络设备","指责厂商"],"a":1,"e":"阻断型控制需严谨的调优与灰度流程平衡风险与业务连续性。一关了之引入漏报，换设备与指责不解决问题。（OSG 第11章 IPS 运营）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-38","d":"域4 通信与网络安全","w":3,"q":"使用隐写术把数据藏进图片传输，检测手段最合适的是？","o":["端口扫描","文件异常分析（尺寸/熵/结构指纹）与出网内容审计（DLP）","ping 测试","MAC 地址过滤"],"a":1,"e":"隐写不改变网络行为，需内容层分析：熵异常、结构校验与基线比对，配合 DLP 与出口管控。端口扫描/ping 无效。（OSG 第12章 隐蔽通道）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-39","d":"域4 通信与网络安全","w":3,"q":"东西向流量与南北向流量的区别及其安全含义是？","o":["东西向是数据中心内部/服务器间流量，横向移动多发生在这一层，需要微分段与内部检测","东西向指外网到内网","南北向指楼与楼之间","两者加密方式不同"],"a":0,"e":"南北向是进出数据中心，东西向是内部互访；传统边界防护偏南北，防横向移动须东西向分段的零信任化。（OSG 第11章 流量模型与分段）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-40","d":"域4 通信与网络安全","w":3,"q":"DNS 隧道（DNS Tunneling）被攻击者用于？","o":["提高域名解析速度","绕过防火墙：借 DNS 查询外传数据或建立隐蔽 C2 通道","防止 DNS 劫持","减少域名费用"],"a":1,"e":"DNS 常被放行，攻击者把数据/指令编码进查询，需 DNS 层监控（查询长度/频率/异常域）与策略 DNS 出口。（OSG 第12章 隐蔽通信）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-41","d":"域4 通信与网络安全","w":3,"q":"虹吸式'网络禁区'设计中，管理网络的安全要求是？","o":["与业务网共用交换机以省成本","带外/隔离管理，强认证（跳板机+MFA）与严格访问控制","允许任何员工直连服务器管理口","管理流量走公网明文"],"a":1,"e":"管理面是最高价值目标，需带外管理、堡垒机、MFA 与白名单访问。共网、开放直连、明文公网均为严重隐患。（OSG 第11章 管理平面安全）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-42","d":"域4 通信与网络安全","w":3,"q":"公司发现内网出现伪造的 DHCP 服务器分发错误网关。除 DHCP Snooping 外还应启用？","o":["动态 ARP 检测（DAI）阻断利用伪造网关的 ARP 欺骗","关闭全部交换机","禁用 DHCP 协议","改用静态 ARP 全网"],"a":0,"e":" rogue DHCP 常配合中间人，Snooping 限定信任端口，DAI 依赖其绑定表拦截 ARP 欺骗，两者联动。（OSG 第12章 二层防护）","f":"12 安全通信与网络攻击","v":[]},{"id":"v2d4-43","d":"域4 通信与网络安全","w":3,"q":"全流量 PCAP 与 NetFlow 的取证价值差异是？","o":["完全相同","PCAP 提供完整报文可还原细节（重放/提取样本），NetFlow 提供轻量连接元数据便于大规模关联分析","NetFlow 可还原明文","PCAP 只能看 DNS"],"a":1,"e":"PCAP 细节全但存储代价高，适合定点深挖；Flow 元数据轻量适合全局狩猎。加密流量下两者均不能还原内容。（OSG 第11章 网络取证）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-44","d":"域4 通信与网络安全","w":3,"q":"SASE（安全访问服务边缘）的核心思想是？","o":["把 SD-WAN 与云交付安全（SWG/CASB/ZTNA/FWaaS）融合为统一服务，身份驱动就近接入","把所有服务器搬回机房","仅指更快的专线","一种新的无线协议"],"a":0,"e":"SASE 以云服务方式统一网络与安全能力，按身份与上下文策略就近交付，顺应远程办公与云化。（OSG 第11章 现代网络架构）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d4-45","d":"域4 通信与网络安全","w":3,"q":"某服务器只允许特定网段访问 443 端口、其余全部拒绝。实现该需求最直接的设备功能是？","o":["防火墙访问控制策略（默认拒绝+显式放行）","NAT 转换","VLAN 划分","负载均衡健康检查"],"a":0,"e":"这是典型的防火墙白名单策略（fail-safe default）。NAT 不控制主体，VLAN 只做分段，LB 与访问控制无关。（OSG 第11章 防火墙策略）","f":"11 安全网络架构和组件","v":[]},{"id":"v2d5-1","d":"域5 身份与访问管理","w":3,"q":"身份与访问管理的三个核心过程'标识（Identification）、认证（Authentication）、授权（Authorization）'的正确顺序与含义是？","o":["授权→认证→标识","标识声明身份→认证验证身份→授权决定能访问什么","认证→标识→授权","三者可任意顺序"],"a":1,"e":"主体先声称身份（ID），再凭因子证明，最后由系统按策略赋权；之后还有可问责（Accounting/Audit）。（OSG 第13章 IAM 基础）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-2","d":"域5 身份与访问管理","w":3,"q":"认证三因子中，'你有什么、你是什么、你知道什么'分别对应？","o":["令牌/智能卡；生物特征；口令/PIN","口令；令牌；生物特征","生物特征；口令；令牌","PIN；生物特征；口令"],"a":0,"e":"持有物因子=智能卡/令牌；生物因子=指纹/虹膜等；知识因子=口令/PIN。（OSG 第13章 认证因子）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-3","d":"域5 身份与访问管理","w":3,"q":"双因素认证（2FA）的正确构成是？","o":["口令 + PIN","口令 + 动态令牌（OTP）","指纹 + 虹膜","两个不同账号"],"a":1,"e":"2FA 要求来自不同类别的两个因子：知识（口令）+持有（OTP/智能卡）或 +生物。口令与 PIN 同属知识因子；指纹与虹膜同属生物因子。（OSG 第13章 多因素认证）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-4","d":"域5 身份与访问管理","w":2,"q":"生物识别中 FAR（误接受率）与 FRR（误拒绝率）的关系是？","o":["可同时降到零","此消彼长：阈值调严 FRR 升、FAR 降，需按场景权衡（高安全区偏重降 FAR）","完全独立","FAR 越高越安全"],"a":1,"e":"单一阈值下 FAR 与 FRR 权衡，CER（等错误率）是比较指标。高安全场景优先低 FAR；FAR 高意味着冒名者更易通过。（OSG 第13章 生物识别）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-5","d":"域5 身份与访问管理","w":3,"q":"生物特征模板被盗后无法'改密码'。针对该风险的最合理措施是？","o":["改用 4 位 PIN","保护模板存储（加密/不可逆变换）、多因素叠加与供应商层面防重放（活体检测）","禁止使用生物识别","每人注册全部手指"],"a":1,"e":"生物不可撤销，须从模板保护、叠加因子与呈现攻击检测入手全面加固。弃用生物过于极端；PIN 与多指纹不解决模板泄露。（OSG 第13章 生物识别安全）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-6","d":"域5 身份与访问管理","w":3,"q":"SSO 单点登录的主要收益与风险是？","o":["减少口令疲劳与重复凭据；但凭据一旦泄露波及所有系统，需配合 MFA 与会话治理","彻底消除认证风险","使每个系统口令更复杂","无需身份治理"],"a":0,"e":"SSO 改善体验并集中管控，同时放大单点失陷影响，因此必须叠加强认证、超时与条件访问。（OSG 第13章 单点登录）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-7","d":"域5 身份与访问管理","w":3,"q":"SAML、OAuth 2.0 与 OIDC 的典型用途区分是？","o":["SAML 常用于企业 Web SSO（XML 断言）；OAuth2 是授权框架；OIDC 在 OAuth2 上补认证层，广泛用于现代应用","三者都是认证协议且相同","OAuth2 本身就是认证协议","SAML 已被法律禁止"],"a":0,"e":"OAuth2 只管授权（委托访问），认证需 OIDC 扩展；SAML 以 XML 断言做联邦认证。混用'OAuth=认证'是最常见误区。（OSG 第13章 联合身份）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-8","d":"域5 身份与访问管理","w":3,"q":"Kerberos 认证中的'票据授予票据（TGT）'的作用是？","o":["用户口令的哈希","客户端向 KDC 的 TGS 申请服务票据的凭据，避免反复出示口令","服务的公钥证书","时间同步令牌"],"a":1,"e":"用户经 AS 认证获 TGT，再凭 TGT 向 TGS 换取各服务票据；依赖可信第三方 KDC 与时间同步防重放。（OSG 第13章 Kerberos）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-9","d":"域5 身份与访问管理","w":3,"q":"Kerberos 对时间高度敏感的原因是？","o":["票据含时间戳用于防重放，时钟偏差过大会认证失败","服务器按时间计费","密码按时间轮换","审计日志需要"],"a":0,"e":"票据与认证器带时间戳，KDC/服务校验时间窗防重放，因此域内要求时间同步（默认约 5 分钟容差）。（OSG 第13章 Kerberos）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-10","d":"域5 身份与访问管理","w":3,"q":"自助密码重置'忘记密码'流程最需要防范的弱点是？","o":["邮件延迟","安全问题答案可被社工/检索得到，用于冒充重置（需结合 MFA 与风险信号）","密码长度限制","重置页面样式"],"a":1,"e":"弱知识验证（母亲姓氏、生日）是账户接管高发入口，应以 MFA、设备/行为信号与冷却期加固。（OSG 第13章 口令生命周期）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-11","d":"域5 身份与访问管理","w":3,"q":"关于口令策略，现代指南（NIST SP 800-63B）的取向是？","o":["强制每月更换与复杂符号规则","允许长口令/短语、对照泄露库检查、不强制周期性更换（除非泄露），提高可用性与强度","禁止一切口令","口令最短 4 位以利记忆"],"a":1,"e":"研究表明强制频繁轮换导致弱模式口令；现代实践推崇长度、泄露黑名单与 MFA。（OSG 第13章 口令管理）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-12","d":"域5 身份与访问管理","w":3,"q":"智能卡+PIN 登录体现的原则是？","o":["双人控制","多因素：持有（卡）+ 知识（PIN）","匿名性","默认放行"],"a":1,"e":"卡与 PIN 分属两类因子，丢卡无 PIN 不可用、知 PIN 无卡也不可。它不是职责分离类控制。（OSG 第13章 智能卡）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-13","d":"域5 身份与访问管理","w":3,"q":"特权访问管理（PAM）中'密码保管库+自动轮换+会话录像'组合的主要目标是？","o":["加快特权操作","管控与审计特权账号使用，降低凭据滥用与内部风险","减少服务器数量","替代防火墙"],"a":1,"e":"PAM 集中保管、按需取出、动态轮换并记录会话，使特权可归责。它不追求提速，也不替代网络安全控制。（OSG 第14章 特权管理）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-14","d":"域5 身份与访问管理","w":3,"q":"DAC、MAC、RBAC 中，'数据的所有者决定谁能访问'属于？","o":["MAC（强制访问控制）","DAC（自主访问控制）","RBAC（基于角色）","ABAC（基于属性）"],"a":1,"e":"DAC 由资源所有者自主授权（如 NTFS 权限）；MAC 由系统级标签强制；RBAC 按角色赋权；ABAC 按属性策略。（OSG 第14章 访问控制模型）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-15","d":"域5 身份与访问管理","w":3,"q":"军事'绝密级人员只能读机密以上文件、且只能写入同级或更高密级文件'体现的模型是？","o":["Biba 完整性模型","Bell-LaPadula 机密性模型（不上读、不下写）","Clark-Wilson","Chinese Wall"],"a":1,"e":"BLP 星属性禁'下写'防泄密；Biba 恰好相反（不下读、不上写）护完整性。此场景是典型 MAC+BLP。（OSG 第14章 强制访问控制）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-16","d":"域5 身份与访问管理","w":3,"q":"角色爆炸（role explosion）问题最可能出现在？","o":["DAC 体系","RBAC 体系（角色数随岗位差异激增而失控）","MAC 体系","物理门禁"],"a":1,"e":"RBAC 为覆盖细粒度差异会派生海量角色导致治理失败，常需引入 ABAC 属性化策略缓解。（OSG 第14章 访问控制模型）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-17","d":"域5 身份与访问管理","w":3,"q":"ABAC 相比 RBAC 的优势是？","o":["按主体/客体/环境属性动态决策，能表达细粒度上下文策略（如时间、位置、设备合规）","完全不需要身份","只能用于数据库","审批更慢"],"a":0,"e":"ABAC 以属性+策略实时评估，适合零信任条件访问；它仍需要身份与属性来源，并非免身份。（OSG 第14章 ABAC）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-18","d":"域5 身份与访问管理","w":3,"q":"风险自适应/情境感知访问控制（如异地登录要求二次验证）体现的原则是？","o":["静态一次性授权","持续评估：将上下文风险纳入授权决策","默认信任内网","所有请求一律拒绝"],"a":1,"e":"条件访问根据位置/设备/行为风险动态加严，是零信任持续验证的核心实践。（OSG 第14章 动态访问控制）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-19","d":"域5 身份与访问管理","w":3,"q":"供应商需要在限定时间访问某台服务器。最符合最小权限的做法是？","o":["发放长期域管理员账号","临时账号+JIT 及时开通/到期回收，仅授该主机所需权限","共享 root 口令","开放整个管理网段"],"a":1,"e":"JIT+最小权限+审计可在满足运维需求的同时把暴露窗口压到最小。长期特权与共享账号违背可归责原则。（OSG 第14章 最小权限与JIT）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-20","d":"域5 身份与访问管理","w":3,"q":"权限'回收（Revocation）'最常被忽视的时机是？","o":["系统上线","人员转岗/项目结束/组织调整时的权限再评估","采购新设备","年度预算"],"a":1,"e":"权限蔓延（creep）多因转岗与项目收尾未回收，需要周期性权限复核（ACR）与流程钩子。（OSG 第14章 权限生命周期）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-21","d":"域5 身份与访问管理","w":3,"q":"定期'访问权复核（Access Review/Recertification）'的主要价值是？","o":["满足预算流程","发现并清除累积与过期的多余权限，保持权限与职责一致","测试系统性能","培训新员工"],"a":1,"e":"复核由数据/系统所有者确认仍需授权，是治理与审计的核心要求，直接对应最小权限。（OSG 第14章 权限治理）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-22","d":"域5 身份与访问管理","w":3,"q":"联网门禁系统中，'防反传（Anti-passback）'防的是什么？","o":["尾随进入（piggybacking）","一张卡在同一入口刷入两次（凭据传递/代刷）","火灾疏散","电梯超载"],"a":1,"e":"防反传要求先入后出、不得重复进入，抑制卡片共享；尾随需通道设计（旋转门/闸机）与人员意识。（OSG 第10章/第14章 物理访问控制）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-23","d":"域5 身份与访问管理","w":3,"q":" Kerberos 环境里服务需要验证客户端身份，同时客户端也要确认服务真实。这依赖的是？","o":["共享的对称密钥体系（主体与 KDC 各自共享长期密钥，票据相互加密验证）","公网匿名访问","明文口令广播","IP 白名单"],"a":0,"e":"Kerberos 中每个主体与 KDC 共享密钥，票据用目标服务密钥加密实现双向认证；IP 白名单不是身份认证。（OSG 第13章 Kerberos）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-24","d":"域5 身份与访问管理","w":3,"q":"联邦身份中 IdP 与 SP 的信任传递方式是？","o":["SP 直连用户数据库查询口令","用户在受信 IdP 完成认证，IdP 向 SP 签发经签名的断言/令牌（SAML/OIDC）","两者每夜同步全部账号","用户向每个 SP 重复交口令"],"a":1,"e":"联邦以签名断言建立跨域信任，SP 验签即可信任认证结果，避免口令扩散与重复账号。（OSG 第13章 联合身份）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-25","d":"域5 身份与访问管理","w":3,"q":"OIDC 的 access token 与 id token 的区别是？","o":["id token 是 JWT 携带用户认证声明；access token 用于向资源服务器证明授权访问","两者相同","id token 用于调用 API","access token 包含用户口令"],"a":0,"e":"id_token 面向客户端证明'用户是谁'（认证）；access_token 面向资源服务器表明'允许做什么'（授权）。（OSG 第13章 现代认证协议）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-26","d":"域5 身份与访问管理","w":3,"q":"发现某离职 3 个月的员工账号仍能登录 VPN。最能防止再发的组合是？","o":["增加密码长度","入离职流程与 IAM/AD 联动自动禁用 + 定期对账（HR 源与活跃账号比对）","每季度开一次安全会议","部署更多防火墙"],"a":1,"e":"账号生命周期须与 HR 主数据自动联动并辅以对账审计，人工流程必然遗漏。密码复杂度与防火墙不解决孤儿账号。（OSG 第14章 身份生命周期治理）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-27","d":"域5 身份与访问管理","w":3,"q":"服务账号（Service Account）管理的最大隐患是？","o":["名称太长","口令从不轮换、权限过大且无人负责，成为攻击者持久化首选","日志太多","占用了许可证"],"a":1,"e":"服务账号常被忽视：弱/永不变口令与超权限使其成为横向移动与持久化跳板，应纳管 PAM、限定权限并轮换。（OSG 第14章 非人类身份）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-28","d":"域5 身份与访问管理","w":3,"q":"'默认拒绝（implicit deny）'原则的含义是？","o":["默认拒绝所有访问，未显式授权的请求一律拒绝","默认允许内部用户","只拒绝已知恶意 IP","只在工作时间拒绝"],"a":0,"e":"访问控制策略应以白名单为基础，没有明确允许即拒绝，保证失败安全与最小权限。（OSG 第14章 访问控制原则）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-29","d":"域5 身份与访问管理","w":3,"q":"职责分离（SoD）在权限体系中的落地方式是？","o":["把冲突权限授予同一人以提高效率","识别冲突权限组合并在配置/角色层面禁止同一主体同时持有","只靠员工自觉","仅对新员工适用"],"a":1,"e":"SoD 需在角色与授权流程中编码冲突规则（如申请与审批分离），并检测既有冲突。（OSG 第14章 职责分离）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-30","d":"域5 身份与访问管理","w":3,"q":"需要两名管理员各自输入密钥片段才能解锁加密库。这种控制是？","o":["岗位轮换","双人控制/知识拆分（Split knowledge）","强制休假","背景调查"],"a":1,"e":"双人控制与知识拆分要求两人各持一半，防单人作恶；轮换与休假是检测性控制。（OSG 第14章 特权控制）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-31","d":"域5 身份与访问管理","w":3,"q":"RADIUS 与 TACACS+ 的常见区别是？","o":["RADIUS 加密仅覆盖口令、常用于网络准入与 VPN；TACACS+ 全报文加密、支持按命令授权，常用于设备管理","RADIUS 更安全且全加密","TACACS+ 只能用于无线","两者完全相同"],"a":0,"e":"RADIUS 只加密口令字段，融合认证授权；TACACS+ 分离 AAA、整体加密，适合对网络设备做细粒度命令级授权。（OSG 第13章 AAA 协议）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-32","d":"域5 身份与访问管理","w":3,"q":"密码喷洒（Password Spraying）与暴力破解的区别是？","o":["喷洒用少量常见口令横扫大量账号，规避锁定阈值；暴破对单账号穷举","喷洒只针对管理员","两者没有区别","喷洒必须离线进行"],"a":0,"e":"喷洒以'一密多号'绕过针对单账号的锁定，需口令黑名单、统一监控与自适应锁定防护。（OSG 第13章 口令攻击）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-33","d":"域5 身份与访问管理","w":3,"q":"Passkey（FIDO2/WebAuthn）抵御钓鱼的原理是？","o":["口令更长","凭据与注册域名绑定且为非对称挑战响应，假域名无法获得有效签名","需要短信验证码","只在内网可用"],"a":1,"e":"WebAuthn 将密钥绑定到源域，认证基于质询签名，钓鱼域拿不到可被接受的断言；短信码恰是可钓鱼的弱因子。（OSG 第13章 无口令认证）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-34","d":"域5 身份与访问管理","w":3,"q":"短信 OTP 被认为相对较弱的原因不包括？","o":["可被 SIM 交换劫持","可被钓鱼转发","运营商链路可被劫持","它属于知识因子"],"a":3,"e":"短信 OTP 属于'持有'因子（拥有该 SIM/号码），前三项才是其真实弱点。因此高危场景应优先 App 推送/Passkey。（OSG 第13章 MFA 强度）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-35","d":"域5 身份与访问管理","w":3,"q":"集中式身份权威（Authoritative Source）的意义是？","o":["减少服务器采购","以单一可信数据源（如 HR+IdP）驱动账号/权限创建与回收，避免多源漂移","加快网页加载","便于绩效考核"],"a":1,"e":"权威源保证'一个身份一个真相'，入职即建、离职即停，是 IAM 治理基础。（OSG 第13章 身份管理）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-36","d":"域5 身份与访问管理","w":3,"q":"'最小权限'与'需要知悉（Need to Know）'的关系是？","o":["两者对立","需要知悉是数据访问维度的最小权限：即使有访问级别，无业务必要也不得接触","两者等同且只用于军事系统","最小权限只针对管理员"],"a":1,"e":"最小权限是普适原则，需要知悉强调即使已获级别授权，仍须有业务必要才能接触特定信息。（OSG 第14章 访问原则）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-37","d":"域5 身份与访问管理","w":3,"q":"离职面谈中员工交出门禁卡但声称手机装了 Google Authenticator 已无法使用。IAM 侧应立即？","o":["等 30 天自动过期","注销其 MFA 设备注册与所有活跃会话/令牌","仅重置密码","发新卡"],"a":1,"e":"离职须即时吊销身份的所有因子与会话（refresh token、MFA 绑定），仅重置密码不终止已登录会话。（OSG 第14章 会话与凭据治理）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-38","d":"域5 身份与访问管理","w":3,"q":"云上为应用分配的 IAM 角色使用过宽的 '*' 权限。最合适的改造是？","o":["保持现状以保可用","按实际访问行为收敛为最小权限策略并定期复核","换成更长的根账号口令","关闭日志以减少费用"],"a":1,"e":"云 IAM 应按最小权限收敛策略并借助访问分析持续校正；根账号严禁日常使用，日志必须保留。（OSG 第14章 云端访问控制）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-39","d":"域5 身份与访问管理","w":3,"q":"用户抱怨每次出差登录都被要求 MFA 挑战。兼顾安全与体验的最佳做法是？","o":["关闭出差时的 MFA","采用风险自适应策略：常用设备/常规位置低摩擦，异常上下文强挑战","统一取消 MFA","每次都要求三种因子"],"a":1,"e":"条件/自适应访问在低风险降低摩擦、高风险加强验证，实现安全与可用性平衡；关闭 MFA 不可接受。（OSG 第14章 自适应认证）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-40","d":"域5 身份与访问管理","w":3,"q":"跨域信任中，为防止一个域失陷波及全局，应避免的做法是？","o":["限制信任范围与选择性认证","使用无约束委派/全域宽泛信任","定期复核信任关系","启用双因素认证"],"a":1,"e":"无约束委派与宽泛林间信任会放大失陷半径，应采用选择性认证、受限委派与最小信任面。（OSG 第13章 域信任）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-41","d":"域5 身份与访问管理","w":3,"q":"审计发现 4 名在职员工拥有财务系统'付款审批'与'供应商创建'两个冲突权限。最恰当的整改是？","o":["保留并要求员工签承诺书","撤销冲突组合：供应商创建与付款审批必须分配给不同角色/人员","删除财务系统日志","全员培训即可"],"a":1,"e":"SoD 冲突必须从授权上拆分，承诺与培训不能替代控制；删日志属违规。（OSG 第14章 职责分离）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-42","d":"域5 身份与访问管理","w":3,"q":"实施 zero trust 时，'设备健康'作为授权条件意味着？","o":["只看员工身份即可","终端合规（补丁/加密/EDR 状态）参与访问决策，不合规设备被限制或拒绝","设备品牌决定权限","禁止个人设备接入"],"a":1,"e":"零信任把身份与设备态势都纳入策略，不合规设备可被置于修复区而非直接全禁。（OSG 第14章 零信任访问）","f":"14 控制和监控访问","v":[]},{"id":"v2d5-43","d":"域5 身份与访问管理","w":3,"q":"某系统账号命名包含员工工号，员工转岗后旧账号被改给新人使用。这违反了？","o":["账号与自然人一一对应（可归责性）","开放设计原则","最小费用原则","网络分段原则"],"a":0,"e":"复用账号使审计无法区分行为人，账号应随人生命周期创建与注销。（OSG 第13章 身份管理）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-44","d":"域5 身份与访问管理","w":3,"q":"用户报告收到'验证您的账号'钓鱼邮件。除提醒删除外，组织层面最有效的预防是？","o":["统一改密","部署反钓鱼控件（DMARC/SPF、邮件网关、钓鱼演练与一键上报）","限制每人每天登录次数","关闭 Web 邮件"],"a":1,"e":"钓鱼是账号接管主入口，需要技术（发件认证、网关沙箱）+ 人（演练与上报）+ 流程（快速响应）体系化防御。（OSG 第13章 凭据攻击防御）","f":"13 管理身份和认证","v":[]},{"id":"v2d5-45","d":"域5 身份与访问管理","w":3,"q":"'认证（Authentication）'与'授权（Authorization）'混淆会导致的典型缺陷是？","o":["只验证了身份就赋予全部权限，未按角色/属性收敛授权","口令策略过严","日志保留过长","备份频率不足"],"a":0,"e":"认证回答'你是谁'，授权回答'你能做什么'；跳过细粒度授权直接全放行违背最小权限。（OSG 第13/14章 AAA）","f":"13 管理身份和认证","v":[]},{"id":"v2d6-1","d":"域6 安全评估与测试","w":3,"q":"漏洞扫描器报告某服务器存在'远程代码执行'漏洞，运维认为该端口仅内网可达。验证该漏洞真实可利用性的最佳方式是？","o":["直接相信扫描结果","经验证的利用尝试/渗透测试（在授权窗口内证实可达性与可利用性）","关闭扫描器","升级服务器内存"],"a":1,"e":"扫描结果含误报与不可达项，需经人工验证或授权渗透测试确认，才能确定风险等级与修复优先级。（OSG 第15章 漏洞评估）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-2","d":"域6 安全评估与测试","w":3,"q":"漏洞管理流程中'风险评级'应综合考虑的因素是？","o":["仅 CVSS 基础分","CVSS 基础分 + 环境因素（暴露面、业务关键性、有无利用代码/在野利用、补偿控制）","服务器品牌","机房温度"],"a":1,"e":"修复优先级必须结合环境上下文（如仅内网、已有 WAF 规则缓解），单纯基础分会导致资源错配。（OSG 第15章 漏洞管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-3","d":"域6 安全评估与测试","w":3,"q":"渗透测试与漏洞扫描的主要区别是？","o":["扫描更深入","渗透测试模拟攻击者实际利用漏洞，评估真实入侵路径与影响；扫描侧重发现与枚举漏洞","渗透测试不需要授权","两者完全相同"],"a":1,"e":"扫描广而浅、可自动化；渗透测试深而窄、验证可达性与危害。两者都必须在明确授权（Rules of Engagement）下进行。（OSG 第15章 测试类型）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-4","d":"域6 安全评估与测试","w":3,"q":"渗透测试的'交战规则（RoE）'中必须明确的内容不包括？","o":["测试范围与时间窗口","应急联系人及遇真实入侵时的处置","可否进行社工/DoS 等敏感手法","测试人员的薪资结构"],"a":3,"e":"RoE 界定范围、时间、手法边界、联络与升级路径，保护双方；薪资不属于授权内容。（OSG 第15章 渗透测试管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-5","d":"域6 安全评估与测试","w":3,"q":"内部红队演练发现 SOC 对横向移动无告警。该演练产出的最重要成果是？","o":["攻击者名单","检验检测与响应能力的证据 + 改进项（控制有效性验证）","新采购清单","员工处罚名单"],"a":1,"e":"红队/紫队的价值在于检验防御体系（假设检验）并驱动提升，而非展示攻击技巧或处罚员工。（OSG 第15章 红队/紫队）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-6","d":"域6 安全评估与测试","w":3,"q":"代码审查中，'静态分析（SAST）'与'动态分析（DAST）'的区别是？","o":["SAST 不运行程序、扫描源码/字节码找缺陷模式；DAST 运行中的黑盒测试，从外部探测行为","SAST 更慢且已淘汰","DAST 能发现全部逻辑漏洞","两者只差语言"],"a":0,"e":"SAST 白盒早期介入可发现注入等模式但误报多；DAST 黑盒贴近真实运行但难覆盖逻辑缺陷，应结合使用（IAST/软件成分分析补充）。（OSG 第15章/第20章 代码测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-7","d":"域6 安全评估与测试","w":3,"q":"SCA（软件成分分析）解决的问题是什么？","o":["自研代码风格","开源/第三方组件的已知漏洞与许可合规（依赖与 SBOM）","数据库性能","网络延迟"],"a":1,"e":"现代应用大量复用开源组件，SCA 识别依赖及其 CVE 与许可证风险，是供应链安全测试关键。（OSG 第15章/第20章 软件测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-8","d":"域6 安全评估与测试","w":3,"q":"模糊测试（Fuzzing）的原理与擅长发现的问题是？","o":["向程序输入大量随机/变异数据，观察崩溃与异常，发现输入处理类内存与解析漏洞","模拟用户点击界面","审查需求文档","检查配置基线"],"a":0,"e":"模糊测试以异常输入探测健壮性，擅长发现解析器/文件格式/协议处理的内存破坏缺陷。（OSG 第20章 软件安全测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-9","d":"域6 安全评估与测试","w":3,"q":"'误报（False Positive）'与'漏报（False Negative）'在 SOC 语境下的含义是？","o":["误报=把正常判为恶意；漏报=未检出真实威胁","误报=漏掉威胁；漏报=告警太多","两者相同","误报只发生在扫描器"],"a":0,"e":"误报消耗人力造成告警疲劳；漏报意味着入侵未被看见。调优要在两者间按风险权衡。（OSG 第15章 检测指标）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-10","d":"域6 安全评估与测试","w":3,"q":"基线比对（baseline comparison）与'偏差报告'主要用于发现？","o":["配置漂移与未授权变更","新漏洞 CVE","员工满意度","网络带宽峰值"],"a":0,"e":"以加固基线为参照比对现网配置可发现漂移（补丁回退、配置改动），是配置管理的核心检测手段。（OSG 第15章 配置管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-11","d":"域6 安全评估与测试","w":3,"q":"审计日志的'完整性'最需要哪种保障？","o":["日志文件用可写共享存放","集中收集、防篡改（WORM/签名）与时间同步（NTP）","日志加密后把密钥写进日志","仅本地保存一年"],"a":1,"e":"攻击者首要删改痕迹，日志须集中外送并防篡改、时间可信用；密钥入日志、本地留存与可写共享都是弱点。（OSG 第15章 审计与日志）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-12","d":"域6 安全评估与测试","w":3,"q":"'管理评审'（如年度安全体系评审）与'技术评估'的最主要区别是？","o":["管理评审由最高管理层主导，审视体系目标、绩效与改进方向；技术评估针对系统与技术控制","管理评审就是开会签到","技术评估不需要证据","两者没有区别"],"a":0,"e":"管理评审是治理层活动（输入绩效指标、审计结果，输出改进决策）；技术评估面向具体控制有效性。（OSG 第15章 管理评审）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-13","d":"域6 安全评估与测试","w":3,"q":"SOX 合规要求对财务系统变更进行'审计追踪'。最应验证的控制是？","o":["变更都经审批并留有不可抵赖的记录（谁、何时、改了什么、谁批准）","服务器双电源","机房门禁","防火墙吞吐"],"a":0,"e":"审计追踪关注可归责的完整变更链路。物理与网络控制是支撑但非本题核心。（OSG 第15章 审计控制测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-14","d":"域6 安全评估与测试","w":3,"q":"对备份的'恢复测试'最应该验证的是？","o":["备份文件大小","能否在 RTO 内、按 RPO 的数据完整度真实恢复业务（restore testing）","备份服务器 CPU 主频","磁带库容量"],"a":1,"e":"未经验证的备份等于没有备份：需定期真实恢复演练，校验时间目标与数据一致性。（OSG 第15章/第18章 备份验证）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-15","d":"域6 安全评估与测试","w":3,"q":"BIA/BCP 演练中，'桌面推演（tabletop exercise）'的特点是？","o":["真实切换生产到备用站点","相关方围坐讨论场景与决策流程，低成本验证计划与职责","删除生产数据做真实恢复","对外公开演练结果"],"a":1,"e":"桌面演练以情景问答检验流程与协调，是演练成熟度的入门级；更高级别有功能演练、切换演练等。（OSG 第3章/第18章 演练类型）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-16","d":"域6 安全评估与测试","w":3,"q":"'合成事务监控（synthetic transaction monitoring）'的用途是？","o":["模拟用户操作持续探测应用可用性与性能，先于真实用户发现问题","分析用户行为画像","生成测试数据","审计数据库权限"],"a":0,"e":"合成监控用脚本化事务主动探测（登录、下单），服务运营测试（OT）中的性能与可用性验证。（OSG 第15章 运营测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-17","d":"域6 安全评估与测试","w":3,"q":"漏洞修复 SLA 规定'严重漏洞 7 天内修复'。审计发现一台服务器超期未修，理由是'重启会影响业务'。最恰当的整改是？","o":["豁免该服务器","评估补偿控制与加急变更窗口，报风险负责人批准临时接受并限期修复","删除该漏洞工单","暂停扫描该网段"],"a":1,"e":"修复受阻时必须走风险例外流程：补偿控制+有期豁免+管理层担责，而不是永久豁免或隐瞒。（OSG 第15章 漏洞SLA治理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-18","d":"域6 安全评估与测试","w":3,"q":"负测试（negative testing）'验证的是？","o":["系统拒绝非法/越界输入的行为（失败安全）","系统在压力下的性能","界面美观度","代码行数"],"a":0,"e":"负测试检验异常与恶意输入下的防护（错误处理、授权拒绝），与正测试互补。（OSG 第20章 软件测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-19","d":"域6 安全评估与测试","w":3,"q":"'覆盖率'指标（代码/分支覆盖）用于评估什么？","o":["测试集对代码路径的执行比例，反映测试充分性","防火墙规则命中率","市场占有率","服务器 CPU 利用率"],"a":0,"e":"覆盖率是软件测试充分性的量化参考，但高覆盖率不等于无漏洞（逻辑与需求缺陷仍可能漏测）。（OSG 第20章 测试管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-20","d":"域6 安全评估与测试","w":3,"q":"渗透测试报告中'已验证（confirmed）'与'疑似（suspected）'漏洞分级差异的价值是？","o":["增加报告页数","帮助修复方区分真实风险与待验证项，合理分配资源","显得更专业","用于向厂商索赔"],"a":1,"e":"区分验证状态避免把误报当真，也避免低估未验证风险，是报告可用性的关键。（OSG 第15章 报告质量）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-21","d":"域6 安全评估与测试","w":3,"q":"第三方对组织的网站做年度渗透测试。为使其有效覆盖今年新增的 API，最需要更新的文件是？","o":["范围说明与授权书（RoE/Scope）","员工手册","机房平面图","备份策略"],"a":0,"e":"测试结论只在授权范围内有效，新增资产必须先纳入范围与授权，否则测试存在合规缺口。（OSG 第15章 第三方测试管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-22","d":"域6 安全评估与测试","w":3,"q":"'用例（test case）'与'用例追溯矩阵（traceability matrix）'的作用是？","o":["追溯需求-设计-测试的覆盖关系，确保需求都被验证","统计程序员产出","美化测试报告","替代渗透测试"],"a":0,"e":"追溯矩阵保证每项安全需求均有对应验证，防需求遗漏，是评估体系性的工具。（OSG 第15章/第20章 测试治理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-23","d":"域6 安全评估与测试","w":3,"q":"对安全意识进行'评估'的最直接量化手段是？","o":["统计培训签到","钓鱼模拟演练的点击率/上报率趋势","统计安全邮件数量","统计门禁刷卡次数"],"a":1,"e":"钓鱼演练点击率与上报率是可量化的行为指标；签到只证明出席不证明效果。（OSG 第15章/第2章 意识度量）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-24","d":"域6 安全评估与测试","w":3,"q":"CVSS 中'基础分、时间分、环境分'三组指标的含义是？","o":["基础分刻画漏洞固有属性；时间分随利用代码与补丁状态变化；环境分按资产重要性定制","三组分数总是相同","环境分由厂商决定，用户不能算","时间分只与年份有关"],"a":0,"e":"基础/时间/环境分层让组织按自身情境调整优先级，环境分由资产所有方计算。（OSG 第15章 漏洞评分）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-25","d":"域6 安全评估与测试","w":3,"q":"'日志审查'作为检测控制，其有效性的最大威胁是？","o":["日志字体太小","海量日志中告警被淹没（告警疲劳）与日志不完整/被删改","日志使用 JSON 格式","日志保存在异地"],"a":1,"e":"没人看的日志没有价值：需要集中化、关联分析、优先级分层的可运营日志体系。（OSG 第15章 审计有效性）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-26","d":"域6 安全评估与测试","w":3,"q":"审计发现 DLP 策略 8 个月未更新，新数据类型未纳管。暴露的评估缺口是？","o":["控制需要与业务/数据变化同步的持续评估与再认证","DLP 本身无效","应立即下线 DLP","换成纸质审批"],"a":0,"e":"控制的有效性随环境漂移，需要周期与事件驱动的再评估，而非否定控制本身。（OSG 第15章 持续评估）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-27","d":"域6 安全评估与测试","w":3,"q":"对员工进行'社会工程电话演练'属于哪类测试？","o":["技术漏洞扫描","人员/流程维度的安全评估（社工演练）","性能压测","代码审计"],"a":1,"e":"社工演练检验人员防线与上报流程，需事先设定边界与不惩罚原则。（OSG 第15章 社会工程测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-28","d":"域6 安全评估与测试","w":3,"q":"'回归测试'在安全语境下的意义是？","o":["验证修复与变更未引入新漏洞或使旧漏洞复发","回到旧版本系统","重复上次审计","统计返工工时"],"a":0,"e":"修复与补丁本身可能引入新缺陷，回归测试守住'不因修复而破坏'。（OSG 第20章 软件测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-29","d":"域6 安全评估与测试","w":3,"q":"'异常检测'用于账号行为时，'不可能旅行（impossible travel）'告警依据的是？","o":["两次登录地理位置切换时间物理上不可能，提示凭据泄露","用户常出差","IP 属地变化但同城市","账号密码过期"],"a":0,"e":"不可能旅行是经典的基于上下文的异常检测用例，提示会话/凭据可能被盗。（OSG 第15章 行为分析）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-30","d":"域6 安全评估与测试","w":3,"q":"第三方审计给出'保留意见'，最可能的原因是？","o":["审计范围受限或证据不足，无法对部分目标给出结论","被审计方太热情","审计师与厂商有利害关系需披露","审计工具未汉化"],"a":0,"e":"保留意见表达因范围或证据限制无法全面结论，组织应补足证据后复审。（OSG 第15章 审计意见类型）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-31","d":"域6 安全评估与测试","w":3,"q":"安全控制'有效性测试'与'合规性测试'的区别是？","o":["有效性测试验证控制确实拦截/检出威胁；合规性测试验证满足法规/标准条款","两者相同","合规测试更技术","有效性测试只查文档"],"a":0,"e":"形式合规（有政策有设备）不等于实际有效（真的拦得住），两类测试互补。（OSG 第15章 控制测试）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-32","d":"域6 安全评估与测试","w":3,"q":"为验证灾备切换能力，最接近真实的演练方式是？","o":["全员桌面推演","把部分真实流量切换到备用站点（并行/受控切换演练）","只检查备份数据存在","口头确认方案"],"a":1,"e":"受控的真实切换最能验证 RTO/RPO 与流程，但需充分准备与回退预案；演练应分级递进。（OSG 第18章 演练分级）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-33","d":"域6 安全评估与测试","w":3,"q":"扫描器凭据配置'无认证扫描'与'认证扫描'的差异是？","o":["认证扫描登录后检查可发现更多本地漏洞与配置缺陷，减少误报","无认证更全面","认证扫描违反法规","两者速度差异是唯一区别"],"a":0,"e":"带凭据扫描深入主机内部（补丁、配置、软件清单），结果更准；无认证只能看暴露面。（OSG 第15章 漏洞扫描）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-34","d":"域6 安全评估与测试","w":3,"q":"'入侵与攻击模拟（BAS）'的作用是？","o":["自动化持续验证检测/防御控制对真实攻击技战术（如 ATT&CK）的响应","替代员工培训","加密网络流量","管理补丁"],"a":0,"e":"BAS 以攻击模拟持续回归验证防御有效性，把一次性测试变成持续评估。（OSG 第15章 安全评估自动化）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-35","d":"域6 安全评估与测试","w":3,"q":"测试环境与生产'基本一致'但从未验证。生产事件中发现测试环境缺少关键网络策略，导致迁移演练失效。根本教训是？","o":["需要验证测试环境的代表性（配置一致性管理）","应取消测试环境","测试环境必须与生产共用账号","演练无价值"],"a":0,"e":"环境漂移使测试结论失真，需要配置一致性基线与差异审计；共用账号违背隔离。（OSG 第15章 测试环境管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-36","d":"域6 安全评估与测试","w":3,"q":"'度量（metrics）'与'原始数据'的区别在于？","o":["度量是围绕目标加工、可比较、支持决策的指标（如 MTTD/MTTR 趋势）","度量就是更多数据","原始数据即可决策","度量只用于绩效考核"],"a":0,"e":"有效安全度量应具可操作性与趋势可比性（MTTD、修复率、覆盖率），原始日志需提炼才有管理价值。（OSG 第15章 安全度量）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-37","d":"域6 安全评估与测试","w":3,"q":"对关键 KPI '平均检测时间（MTTD）'持续变差进行根因分析，最先应查看的是？","o":["告警量与告警处理时长的变化（告警疲劳/人手/规则质量）","办公室搬迁记录","食堂满意度","服务器保修期"],"a":0,"e":"MTTD 恶化通常源于告警泛滥、规则退化或人员瓶颈，需要从检测管线与响应负载入手。（OSG 第15章 度量运营化）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-38","d":"域6 安全评估与测试","w":3,"q":"软件保证'活动中，对供应链的测试应包含？","o":["构建管道完整性（签名校验、依赖锁定、最小权限 CI 凭据）与制品签名验证","仅单元测试","仅渗透测试","仅代码风格检查"],"a":0,"e":"构建系统成为高价值攻击面，需保证依赖可信、管道不可篡改、制品可验证（SLSA 思路）。（OSG 第20章 软件保证）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-39","d":"域6 安全评估与测试","w":3,"q":"渗透测试完成后，测试方应交付的核心内容是？","o":["可复现的发现（证据）、风险评级与可执行修复建议","攻击工具源码","客户员工个人信息","没有报告只给口头结论"],"a":0,"e":"报告价值在可复现证据与修复指引；交付物不应包含无关个人信息或攻击工具。（OSG 第15章 测试交付）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-40","d":"域6 安全评估与测试","w":3,"q":"'披露流程'中对外报告新发现漏洞（Coordinated Disclosure）的正确做法是？","o":["直接全网公布以督促修复","先私下通知厂商并给合理修复期，必要时再公开（协同披露）","卖给第三方","永久保密"],"a":1,"e":"协同披露平衡修复时间与公众知情，直接公开可能危害用户，交易漏洞或永久隐瞒均不当。（OSG 第19章 漏洞披露伦理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-41","d":"域6 安全评估与测试","w":3,"q":"合规评估发现 30 条 '部分符合'。处置优先级排序的最合理依据是？","o":["条款页码顺序","风险敞口与业务影响（先修高风险与关键条款）","字数最多","最容易汇报的"],"a":1,"e":"整改计划应按风险排序并明确责任人、时限与验收标准，而非文档便利。（OSG 第15章 合规评估管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-42","d":"域6 安全评估与测试","w":3,"q":"'配置审计'与'变更管理审计'配合的价值是？","o":["确保变更走审批且落地与批准一致（防未授权变更与漂移）","加快发布速度","减少会议","替代渗透测试"],"a":0,"e":"未授权变更是事故主因之一，变更单与实际配置比对可发现绕流程操作。（OSG 第15章/第16章 变更与配置管理）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-43","d":"域6 安全评估与测试","w":3,"q":"外部审计前，安全团队'预审（readiness assessment）'的目的是？","o":["提前发现证据缺口并整改，降低正式审计不通过风险","替审计师写报告","修改历史日志","向审计师送礼"],"a":0,"e":"预审对照标准自查证据与控制运行，属正当准备；篡改证据与不当影响属违规。（OSG 第15章 审计准备）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-44","d":"域6 安全评估与测试","w":3,"q":"安全测试报告中把'信息泄露'漏洞全部标为'低危'。从评估方法论看该做法的问题是什么？","o":["未结合上下文：泄露内容若含密钥/PII 或可链式利用，实际风险可能很高","低危不需要修复","评级只看 CVSS 就够","报告格式不统一"],"a":0,"e":"严重性需结合泄露内容与利用链评估；教条化套分会低估组合风险。（OSG 第15章 风险评级方法论）","f":"15 安全评估与测试","v":[]},{"id":"v2d6-45","d":"域6 安全评估与测试","w":3,"q":"'持续监控'相比'周期性评估'的优势是？","o":["及时反映控制状态与威胁变化，缩短'评估即过期'的窗口","完全替代人工","成本一定更低","不需要度量"],"a":0,"e":"持续监控（配置遥测、BAS、日志指标）使评估从快照变成实时，但并非免人工、也未必更省成本。（OSG 第15章 持续评估）","f":"15 安全评估与测试","v":[]},{"id":"v2d7-1","d":"域7 安全运营","w":3,"q":"SOC 值班分析师生成告警工单。工单中最重要的两个要素是？","o":["颜色与图标","可复现的证据与处置指引（下一步动作）","工号与签到","服务器外观照片"],"a":1,"e":"告警的价值在于可验证的证据和清晰的处置路径，否则无法形成闭环。视觉与行政字段是辅助。（OSG 第17章 事件响应流程）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-2","d":"域7 安全运营","w":3,"q":"事件响应'准备阶段'应完成的典型工作不包括？","o":["制定 playbook 与联络树","部署/校准检测与取证工具","演练与培训","对外发布公告否认事件"],"a":3,"e":"准备阶段建设能力（流程、工具、演练）；公告发布属检测后的通信环节，且隐瞒性公告不道德。（OSG 第17章 IR 生命周期）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-3","d":"域7 安全运营","w":3,"q":"NIST 事件响应生命周期'检测与分析→遏制 eradication→恢复'之间缺失的关键阶段是？","o":["加固边界防火墙","遏制（Containment）","数据备份","渗透测试"],"a":0,"e":"标准流程：准备→检测分析→遏制（短期/长期）→根除→恢复→经验教训。检测后先遏制扩散再做根除。（OSG 第17章 IR 生命周期）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-4","d":"域7 安全运营","w":3,"q":"发现失陷主机后，第一步优先'断网隔离'而非'直接重装'。原因是？","o":["重装太贵","先保留易失性证据（内存、连接、进程）并阻止扩散，再取证与根除","断网更省电","领导尚未批准重装"],"a":1,"e":"过早重装破坏证据且可能未清除持久化路径；隔离保住了证据并控制影响范围，是遏制的基本逻辑。（OSG 第17章 遏制与取证）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-5","d":"域7 安全运营","w":3,"q":"取证时对磁盘做校验的常用命令组合是？","o":["format + del","dd 逐位复制 + md5sum/sha256sum 记录哈希","ping + tracert","scp + gzip"],"a":1,"e":"取证镜像须逐位复制并计算哈希形成证据链，证明后续分析未改动证据。格式化/压缩/网络命令不具备证据保全作用。（OSG 第19章 数字取证）","f":"19 调查和道德","v":[]},{"id":"v2d7-6","d":"域7 安全运营","w":3,"q":"'证据保管链（Chain of Custody）'记录的核心内容是？","o":["证据从采集到呈堂的每一次移交：谁、何时、做了什么、如何存储","证据的价格","硬盘的购买发票","机房温度记录"],"a":0,"e":"保管链证明证据未被篡改且来源可信，缺失将导致证据可能不被采信。（OSG 第19章 取证证据管理）","f":"19 调查和道德","v":[]},{"id":"v2d7-7","d":"域7 安全运营","w":3,"q":"易失性证据的采集顺序（Ronald van der Knijff 次序）应遵循？","o":["先硬盘后内存","从最易失到最不易失：寄存器/内存→网络连接→进程→磁盘","随机顺序","只采集日志"],"a":1,"e":"断电即失的数据（内存、连接表）优先固定，磁盘等持久数据最后。（OSG 第19章 取证次序）","f":"19 调查和道德","v":[]},{"id":"v2d7-8","d":"域7 安全运营","w":3,"q":"DRP 与 BCP 的关系，最准确的表述是？","o":["两者互不相关","DRP 是 BCP 的组成部分，聚焦灾难后 IT 与关键流程的恢复","BCP 是 DRP 的子集","DRP 只管人员疏散"],"a":1,"e":"BCP 保证整体业务连续，DRP 聚焦灾难场景下的恢复（含 IT），BCP 范围更大。（OSG 第18章 灾难恢复）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-9","d":"域7 安全运营","w":3,"q":"备份策略' grandfather-father-son（GFS）'的含义是？","o":["按代际轮换保留多个时间尺度的备份（日/周/月），兼顾恢复点与介质复用","三代人审批备份","三份备份存同一机房","仅保留最新一份"],"a":0,"e":"GFS 多代轮换提供不同粒度恢复点并防单点介质故障，与人员或份数放置无直接关系。（OSG 第18章 备份策略）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-10","d":"域7 安全运营","w":3,"q":"备份方式全量/增量/差异的描述，正确的是？","o":["增量备份自上次全量以来的变化；差异备份自上次任意备份以来的变化","差异自上次全量以来；增量自上次任意备份以来","两者完全相同","增量比差异恢复更快"],"a":1,"e":"差异=相对上次全量，增量=相对上次任意备份；恢复速度：全量最快，增量最慢（需串联多份）。（OSG 第18章 备份类型）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-11","d":"域7 安全运营","w":3,"q":"RPO=15 分钟的订单系统最合适的备份/复制方案是？","o":["每日离线全量备份","准实时数据复制（同步/近同步）到灾备站点","每周磁带归档","手工导出 Excel"],"a":1,"e":"RPO 15 分钟意味着最多容忍 15 分钟数据丢失，必须近实时复制；日备/周备只能达到天级 RPO。（OSG 第18章 恢复目标与方案）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-12","d":"域7 安全运营","w":3,"q":"热站、温站、冷站的区别，正确的是？","o":["热站全配置可快速接管；温站部分设备需准备周期；冷站仅场地与基础设施","冷站切换最快","三者切换时间相同","温站最贵"],"a":0,"e":"就绪度与成本：热站>温站>冷站，切换速度同序递减，按 RTO 与预算选择。（OSG 第18章 备用站点）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-13","d":"域7 安全运营","w":3,"q":"多站点'active-active'与'active-passive'容灾的区别是？","o":["双活两站点同时服务可即时接管但复杂与成本高；主备平时闲置切换需时间","双活无切换能力","主备更贵","两者无差别"],"a":0,"e":"双活提供近零 RTO 但需解决数据一致性与复杂度；主备成本低但切换慢。（OSG 第18章 容灾架构）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-14","d":"域7 安全运营","w":3,"q":"互惠协议（reciprocal agreement）作为灾备策略的最大风险是？","o":["对方无义务且通常容量不足，真正灾难时可能无法兑现","价格太贵","违反国际法","无法签署书面协议"],"a":0,"e":"互助协议成本几乎为零但可靠性最差：对方可能同灾、容量不足或拒绝履约，只能作为补充。（OSG 第18章 备用方案）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-15","d":"域7 安全运营","w":3,"q":"变更管理的核心目标是？","o":["让变更更快上线","以受控方式实施变更：评估风险、审批、测试、可回滚，减少变更引发的事故","禁止一切变更","减少 IT 人员"],"a":1,"e":"大量事故源于变更；变更管理通过流程降低非计划中断，速度是次要目标。（OSG 第16章 变更管理）","f":"16 安全运营管理","v":[]},{"id":"v2d7-16","d":"域7 安全运营","w":3,"q":"'紧急变更'的正确处理是？","o":["跳过所有流程直接上线","走紧急通道快速审批并在事后补记录与复核","一律等到下次变更窗口","只发邮件通知"],"a":1,"e":"紧急变更允许压缩流程但保留授权与事后复盘，不能成为绕过管控的漏洞。（OSG 第16章 变更流程）","f":"16 安全运营管理","v":[]},{"id":"v2d7-17","d":"域7 安全运营","w":3,"q":"配置管理（CM）与变更管理的关系是？","o":["配置管理维护授权配置基线（CI 及其关系），变更管理控制对基线的修改","两者无关","配置管理只管硬件","变更管理包含于配置管理"],"a":0,"e":"CMDB 提供基线与影响分析输入，变更产生的状态更新回写 CMDB，两者闭环。（OSG 第16章 配置管理）","f":"16 安全运营管理","v":[]},{"id":"v2d7-18","d":"域7 安全运营","w":3,"q":"补丁管理的标准流程顺序是？","o":["评估→测试→审批→分批部署→验证与回滚准备","直接全员推送","先生产后测试","只在周末批量重启"],"a":0,"e":"补丁也属变更：先在测试环境验证，再灰度分批上线并监控；直推生产风险极高。（OSG 第16章 补丁管理）","f":"16 安全运营管理","v":[]},{"id":"v2d7-19","d":"域7 安全运营","w":3,"q":"安全运营中'最小特权'在运维层面的典型落地是？","o":["管理员日常使用域管理员账号","个人账号+按需提权（JIT/PAM 审批），特权操作留痕","共享 root 口令","所有运维都是管理员"],"a":1,"e":"日常低权+按需提权+审计是最小特权的运维实现；常驻特权与共享账号是最大反模式。（OSG 第16章 特权运维）","f":"16 安全运营管理","v":[]},{"id":"v2d7-20","d":"域7 安全运营","w":3,"q":"MTTD 与 MTTR 分别衡量？","o":["平均检测时间与平均响应/恢复时间","平均停机与平均温度","月度工单与月度培训","备份速度与恢复速度"],"a":0,"e":"MTTD 从发生到检测，MTTR 从检测（或发生）到响应/恢复，是 SOC 与运维核心度量。（OSG 第16章 运营度量）","f":"16 安全运营管理","v":[]},{"id":"v2d7-21","d":"域7 安全运营","w":3,"q":"SIEM 的核心价值是？","o":["集中汇聚日志并关联分析，把事件转化为可处置的告警与调查线索","替代防火墙","自动修复所有漏洞","加密所有流量"],"a":0,"e":"SIEM 聚合多源日志做关联与告警，是检测体系的中枢，但不自动解决所有问题。（OSG 第16章 安全监控）","f":"16 安全运营管理","v":[]},{"id":"v2d7-22","d":"域7 安全运营","w":3,"q":"SOAR 平台在 SOC 中的定位是？","o":["以剧本（playbook）自动化编排重复性响应动作，释放人力处理复杂事件","替代分析师做决策","只做日志存储","是另一种防火墙"],"a":0,"e":"SOAR 把富化、隔离、通报等动作剧本化自动执行，人仍保留关键决策。（OSG 第16章 安全自动化）","f":"16 安全运营管理","v":[]},{"id":"v2d7-23","d":"域7 安全运营","w":3,"q":"威胁情报在防御运营中的正确用法是？","o":["把所有 IOC 无脑封禁","将情报与自身资产/情境匹配，用于检测规则、优先级与狩猎方向","仅存档备查","转卖给竞争对手"],"a":1,"e":"情报需与资产关键性结合才有价值；盲目封禁伤及正常业务，情报质量也需要评分（如信任级别）。（OSG 第16章 威胁情报运营）","f":"16 安全运营管理","v":[]},{"id":"v2d7-24","d":"域7 安全运营","w":3,"q":"MITRE ATT&CK 框架的主要用途是？","o":["攻击者画像的知识库：以战术/技术分类攻击行为，用于差距评估、检测覆盖与对抗模拟","漏洞评分","密码强度评估","网络拓扑绘制"],"a":0,"e":"ATT&CK 提供对抗行为分类，支撑检测覆盖率评估与紫队演练设计。（OSG 第16章 威胁建模与框架）","f":"16 安全运营管理","v":[]},{"id":"v2d7-25","d":"域7 安全运营","w":3,"q":"事件'根除（Eradication）'阶段应完成的是？","o":["移除恶意软件与持久化机制、修补被利用漏洞、重置失陷凭据","对外发布新闻稿","删除相关告警","恢复业务并复盘"],"a":0,"e":"根除是彻底清除威胁存在与再入路径；恢复与复盘是后续阶段，删告警属违规。（OSG 第17章 根除阶段）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-26","d":"域7 安全运营","w":3,"q":"勒索事件中'恢复阶段'开始前必须确认的是？","o":["备份未被加密且干净（含入侵已根除），否则可能再次被加密","赎金已支付","新闻稿措辞","员工已道歉"],"a":0,"e":"带毒恢复会二次中招；需先验证备份完整性并确认攻击者已清除（含后门/凭据重置）。支付赎金非首选。（OSG 第17章 恢复阶段）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-27","d":"域7 安全运营","w":3,"q":"事件复盘'lessons learned'应在何时进行？","o":["事件关闭后尽快（记忆鲜活时），形成可执行改进项并跟踪","半年后","只在监管处罚后","无需复盘"],"a":0,"e":"复盘趁早且要产出带责任人与时限的改进项进入跟踪闭环，否则流于形式。（OSG 第17章 复盘）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-28","d":"域7 安全运营","w":3,"q":"疑似内部数据窃密案件的正确调查姿势是？","o":["当众搜查嫌疑人抽屉","按政策与法律授权（HR/法务参与）秘密且规范地收集证据，保护当事人权利与证据效力","全员邮件通报嫌疑人","直接报警并删除其账号"],"a":1,"e":"内部调查须有政策授权与程序正义，证据链合法才可用；公开羞辱与违法取证会反噬组织。（OSG 第19章 内部调查）","f":"19 调查和道德","v":[]},{"id":"v2d7-29","d":"域7 安全运营","w":3,"q":"'告警疲劳'最可能导致的后果是？","o":["真实告警被忽略（漏报上升）","告警数量下降","攻击者自动停止","预算增加"],"a":0,"e":"海量低价值告警使团队麻木，关键信号被淹没；需调优规则、分层优先级与自动化。（OSG 第16章 告警治理）","f":"16 安全运营管理","v":[]},{"id":"v2d7-30","d":"域7 安全运营","w":3,"q":"凌晨主机外连可疑域名的告警。分析师的第一步动作应是？","o":["直接格式化主机","富化与验证：查进程/用户/上下文与威胁情报匹配，判定真伪后再按剧本处置","立即全网断网","忽略等白天处理"],"a":1,"e":"先验证再行动：误报处置同样造成业务影响；分级响应按证据决定升级。（OSG 第17章 告警分诊）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-31","d":"域7 安全运营","w":3,"q":"'假设对手已在内网（assume breach）'理念带来的运营重点是？","o":["只强化边界防火墙","内部横向移动检测、身份与特权管控、分段与欺骗等纵深手段","放弃防护只做响应","购买更多终端杀毒"],"a":1,"e":"假设失陷推动从'防进入'转向'限移动、快检测'：零信任、狩猎与紫队常态化。（OSG 第16章 现代安全运营）","f":"16 安全运营管理","v":[]},{"id":"v2d7-32","d":"域7 安全运营","w":3,"q":"威胁狩猎（Threat Hunting）与被动检测的区别是？","o":["狩猎是主动基于假设在人/网络/终端数据中搜寻潜伏威胁，不依赖已有告警","狩猎就是渗透测试","狩猎只能用 AI","狩猎是被动等待告警"],"a":0,"e":"狩猎以分析师假设驱动主动查证，弥补检测规则盲区，产出反哺检测工程。（OSG 第16章 威胁狩猎）","f":"16 安全运营管理","v":[]},{"id":"v2d7-33","d":"域7 安全运营","w":3,"q":"外包 SOC '监控即服务'后，组织仍不可转移的责任是？","o":["最终风险责任、决策与供应商监督（合同、SLA、审计权）","值班排班","购买分析员工位","选择告警字体"],"a":0,"e":"安全责任可委托不可转移，甲方须保留治理、审计与最终决策权。（OSG 第16章 外包运营）","f":"16 安全运营管理","v":[]},{"id":"v2d7-34","d":"域7 安全运营","w":3,"q":"关键绩效之外，'运营就绪度'评估应覆盖的人的因素是？","o":["轮班与随叫随到（on-call）机制、知识传递（runbook）与人员冗余","员工星座","工位绿植","年会节目"],"a":0,"e":"7×24 运营依赖排班、runbook 化知识与单点人员风险消除，是 SOC 成熟度的重要维度。（OSG 第16章 运营管理）","f":"16 安全运营管理","v":[]},{"id":"v2d7-35","d":"域7 安全运营","w":3,"q":"灾难宣告（disaster declaration）决策应包含的关键要素是？","o":["宣告标准/阈值、有权决策人（及替补）与宣告后的启动流程","机房空调型号","供应商市值","员工生日"],"a":0,"e":"宣告需明确量化触发条件与授权链，避免延误或误宣告；这是 DRP 可执行性的核心。（OSG 第18章 灾难宣告）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-36","d":"域7 安全运营","w":3,"q":"DR 演练发现备用站点的网络带宽不足以在 RTO 内复制峰值数据。处置应？","o":["把 RTO 改成 72 小时以显示达标","提升链路/优化复制策略并复测，更新计划为经验证的目标","删除该演练记录","降低业务量"],"a":1,"e":"演练暴露差距应改进后复测并修订计划；改目标迁就缺陷或掩盖记录自欺欺人。（OSG 第18章 演练改进）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-37","d":"域7 安全运营","w":3,"q":"保留期届满的'电子证据'与常规数据的处置差异是？","o":["完全相同","涉诉/调查保全（legal hold）期间必须暂停例行销毁","证据应立即公开","证据可随意转发"],"a":1,"e":"法律保全令优先于保留期限销毁；证据公开与转发受权限与伦理约束。（OSG 第19章 证据保全）","f":"19 调查和道德","v":[]},{"id":"v2d7-38","d":"域7 安全运营","w":3,"q":"事件响应中与执法机构合作的正确姿态是？","o":["等执法通知后再行动","预先建立联络与流程，按法律建议保存证据链，在合规前提下协作","把全部客户数据打包发送","拒绝任何合作"],"a":1,"e":"预建关系与证据规范是有效协作前提；随意移交数据可能违反隐私法，全面拒绝则失去追责机会。（OSG 第19章 执法协作）","f":"19 调查和道德","v":[]},{"id":"v2d7-39","d":"域7 安全运营","w":3,"q":"'need to know'在事件通报中的体现是？","o":["向所有员工同步全部 IOC 细节","按角色最小化披露（必要时知悉），细节仅限响应与决策相关方","不通报任何人","把嫌疑人信息发朋友圈"],"a":1,"e":"通报需平衡透明与安全：过度披露泄露响应策略与隐私，过少披露贻误协同。（OSG 第17章 事件通信）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-40","d":"域7 安全运营","w":3,"q":"法规要求 72 小时内通报数据泄露。运营侧最需要的支撑能力是？","o":["快速判定受影响数据主体范围的证据与流程（检测→评估→通报链路演练）","更大的会议室","更多打印机","法务外包后无需准备"],"a":0,"e":"通报时限取决于识别、范围评估与通知流程的成熟度，需预先演练而非临时拼凑。（OSG 第17章 合规通报）","f":"17 事件的预防和响应","v":[]},{"id":"v2d7-41","d":"域7 安全运营","w":3,"q":"容量管理（capacity management）在安全运营中的意义是？","o":["确保日志/备份/检测系统在高峰与增长下不失能（如日志风暴撑爆 SIEM）","只关系电费","与安全无关","仅指办公室面积"],"a":0,"e":"攻击常伴随资源冲击（日志洪水），容量规划本身是可用性安全的一部分。（OSG 第16章 运营保障）","f":"16 安全运营管理","v":[]},{"id":"v2d7-42","d":"域7 安全运营","w":3,"q":"'红灯/绿灯式' SLA 报表掩盖了什么常见问题？","o":["只报达成率不报风险趋势与例外（如大量超期未修但被豁免）","颜色不美观","数据太多","字体太小"],"a":0,"e":"运营报表应呈现风险与趋势而非只显示合规绿灯，豁免堆积与超期项是关键盲区。（OSG 第16章 运营报告）","f":"16 安全运营管理","v":[]},{"id":"v2d7-43","d":"域7 安全运营","w":3,"q":"桌面推演中，关键角色缺席（如唯一知道恢复流程的人休假）。这暴露的问题是？","o":["单点知识与角色备份缺失，需在计划中设定代理人机制","演员不敬业","演练时间太长","推演脚本太简单"],"a":0,"e":"演练的价值正是暴露此类可运营性问题：关键岗位需有替补与文档化的 runbook。（OSG 第18章 演练目标）","f":"18 灾难恢复计划","v":[]},{"id":"v2d7-44","d":"域7 安全运营","w":3,"q":"资产'及时下线'为何是安全运营的关键环节？","o":["下线迟缓的系统往往失去补丁与监控，成为攻击跳板","下线浪费电","下线影响 KPI","下线需要审批"],"a":0,"e":"僵尸系统无人维护却仍联网，是典型的高风险资产，需要资产生命周期管理闭环。（OSG 第16章 资产运营）","f":"16 安全运营管理","v":[]},{"id":"v2d7-45","d":"域7 安全运营","w":3,"q":"从'事件响应'走向'事件管理'成熟化的标志是？","o":["以度量驱动持续改进（MTTD/MTTR 趋势、复盘闭环率、演练覆盖），流程制度化而非救火","买了更多显示器","招聘更多实习生","开会频率提高"],"a":0,"e":"成熟度体现在流程、度量、演练与复盘的制度化闭环，而非资源堆砌。（OSG 第16/17章 运营成熟度）","f":"16 安全运营管理","v":[]},{"id":"v2d8-1","d":"域8 软件开发安全","w":3,"q":"软件开发'安全左移（shift left）'的含义是？","o":["把代码仓库迁到北方机房","在开发生命周期尽可能早的阶段（需求/设计）引入安全活动，缺陷越早发现修复成本越低","只做上线前渗透测试","先写代码后定需求"],"a":1,"e":"越晚发现的缺陷修复成本指数上升；左移强调需求与设计阶段的安全分析（威胁建模、安全需求）。（OSG 第20章 安全开发）","f":"20 软件开发安全","v":[]},{"id":"v2d8-2","d":"域8 软件开发安全","w":3,"q":"SDLC 中'需求阶段'的安全活动最应产出的是？","o":["可测试的安全需求（认证强度、日志、隐私要求等），作为后续验收依据","完整源代码","上线公告","渗透测试报告"],"a":0,"e":"安全需求须明确、可验证并追溯到测试用例；代码与测试报告都是后续阶段产物。（OSG 第20章 SDLC）","f":"20 软件开发安全","v":[]},{"id":"v2d8-3","d":"域8 软件开发安全","w":3,"q":"微软 SDL 中，在设计阶段执行'威胁建模'的主要目的是？","o":["提前识别设计中的威胁与信任边界弱点并设计对策","统计代码行数","估算服务器成本","编写用户手册"],"a":0,"e":"威胁建模（如 STRIDE/DFD）在设计期发现攻击面与信任边界问题，是成本最低的干预点。（OSG 第20章 威胁建模/SDL）","f":"20 软件开发安全","v":[]},{"id":"v2d8-4","d":"域8 软件开发安全","w":3,"q":"DevSecOps 的核心实践不包括？","o":["安全测试自动化嵌入 CI/CD","基础设施即代码与基线扫描","安全责任共担（开发承担安全）","把安全检查全部留到发布前一天人工执行"],"a":3,"e":"DevSecOps 将安全左移并自动化、全员共担；集中到最后人工检查是反模式（瓶颈且太晚）。（OSG 第20章 DevSecOps）","f":"20 软件开发安全","v":[]},{"id":"v2d8-5","d":"域8 软件开发安全","w":3,"q":"能力成熟度模型（CMM）五级中'可重复/已定义/已管理/优化'的第三级'已定义'指？","o":["过程在组织级被标准化、文档化并跨项目采用","各项目各自为战","过程有量化度量与统计管控","持续改进与技术创新"],"a":0,"e":"CMM：1 初始→2 可重复（项目级）→3 已定义（组织级标准过程）→4 已管理（量化）→5 优化。（OSG 第20章 成熟度模型）","f":"20 软件开发安全","v":[]},{"id":"v2d8-6","d":"域8 软件开发安全","w":3,"q":"'环境分离（开发/测试/预发/生产）'的最主要安全意义是？","o":["防止生产数据与凭据泄露到弱防护环境，并隔离变更影响","提高编译速度","方便测试用真实客户数据","减少服务器数量"],"a":0,"e":"弱防护的测试环境若导入生产数据即成泄露源；用真实数据'方便测试'恰是违规做法。（OSG 第20章 环境管理）","f":"20 软件开发安全","v":[]},{"id":"v2d8-7","d":"域8 软件开发安全","w":3,"q":"代码库中发现生产数据库明文连接串。最应优先修复的问题是？","o":["界面配色","密钥/凭据管理：从代码与配置历史中移除并轮换，改用秘密管理服务","注释规范","数据库品牌"],"a":1,"e":"入库的凭据视为已泄露：须立即轮换并全历史清除（含 .git 历史），迁移到受管 secrets。（OSG 第20章 敏感信息管理）","f":"20 软件开发安全","v":[]},{"id":"v2d8-8","d":"域8 软件开发安全","w":3,"q":"'代码评审（peer review）'的安全价值是？","o":["多双眼睛发现缺陷与后门，传播安全知识并强制执行编码规范","加快编译","减少代码量","替代测试"],"a":0,"e":"评审是高性价比的缺陷发现渠道（含恶意代码审查），但不能替代自动化测试。（OSG 第20章 代码评审）","f":"20 软件开发安全","v":[]},{"id":"v2d8-9","d":"域8 软件开发安全","w":3,"q":"OWASP Top 10 中'失效的访问控制（Broken Access Control）'的典型缺陷是？","o":["界面按钮未隐藏","仅在前端隐藏功能，服务端未校验用户对资源的权限（水平/垂直越权）","登录页无验证码","使用 HTTP"],"a":1,"e":"访问控制必须在服务端对每次请求强制校验（IDOR、越权）；前端隐藏不是控制。验证码/HTTPS 属其他类别。（OSG 第21章 OWASP）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-10","d":"域8 软件开发安全","w":3,"q":"水平越权（IDOR）与垂直越权的区别是？","o":["水平=访问同级其他用户的资源；垂直=低权角色执行高权操作","水平=左右分屏；垂直=上下滚动","两者相同","水平只发生在移动端"],"a":0,"e":"IDOR 通过改 ID 看他人数据（同级）；垂直是冒用管理员能力。防护都靠服务端对象级授权检查。（OSG 第21章 访问控制缺陷）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-11","d":"域8 软件开发安全","w":3,"q":"XSS 的三种类型中，'存储型 XSS'的危害特点是？","o":["恶意脚本被持久化存入服务端（评论/资料），每个访问者都会执行","仅存在于构造的 URL 中","依靠伪造请求","只影响数据库性能"],"a":0,"e":"存储型影响所有浏览者且持久；反射型经 URL 即时反射；DOM 型在前端 JS 生成。防护靠输出编码+CSP。（OSG 第21章 XSS）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-12","d":"域8 软件开发安全","w":3,"q":"对 XSS 最根本的防御是？","o":["过滤输入关键字' script'","按上下文输出编码（HTML/属性/JS）+ CSP，输入校验为辅","禁用 JavaScript","加长密码"],"a":0,"e":"输出编码按渲染上下文转义不可信数据是根治手段，CSP 作纵深；单纯黑名单过滤易绕过。（OSG 第21章 XSS 防御）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-13","d":"域8 软件开发安全","w":3,"q":"CSRF 的标准防御是？","o":["抗 CSRF 令牌（或 SameSite Cookie）绑定会话与请求来源","双因素认证","IP 白名单","口令复杂度"],"a":0,"e":"CSRF 利用浏览器自动附 Cookie；令牌/SameSite 打破这一假设。MFA 与口令策略不阻断 CSRF。（OSG 第21章 CSRF）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-14","d":"域8 软件开发安全","w":3,"q":"SSRF（服务端请求伪造）的典型危害是？","o":["攻击者诱使服务器访问内网资源/元数据服务（云 169.254.169.254）导致凭据泄露","用户浏览器弹窗","数据库死锁","页面加载慢"],"a":0,"e":"SSRF 把服务器当跳板访问内网与云元数据，须校验/白名单化出网目标并禁用重定向跟随。（OSG 第21章 OWASP）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-15","d":"域8 软件开发安全","w":3,"q":"反序列化漏洞的成因是？","o":["程序对不可信数据执行反序列化时触发任意对象构造/代码执行","JSON 太长","密码强度弱","未使用 CDN"],"a":0,"e":"不可信反序列化可导致 RCE；对策：避免反序列化不可信数据、签名校验、使用安全格式。（OSG 第21章 应用漏洞）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-16","d":"域8 软件开发安全","w":3,"q":"'安全编码'中关于错误处理的要求是？","o":["把堆栈细节返回给用户便于报错","失败安全：向用户显示通用错误，详细日志仅记录在服务端","吞掉所有异常不记录","在生产页面上显示 SQL 语句"],"a":1,"e":"详细报错泄露技术细节助长攻击侦察；应通用提示+服务端详日志。完全不记录则无法排障取证。（OSG 第20章 安全编码实践）","f":"20 软件开发安全","v":[]},{"id":"v2d8-17","d":"域8 软件开发安全","w":3,"q":"API 安全中'过度暴露数据（Excessive Data Exposure）'指？","o":["接口返回了前端不需要的字段（含敏感信息），依赖前端过滤","返回 JSON 而非 XML","没有 SDK","缺少社交分享"],"a":0,"e":"API 应按需裁剪响应（字段级最小化），过滤必须在服务端。（OSG 第21章 API 安全）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-18","d":"域8 软件开发安全","w":3,"q":"软件物料清单（SBOM）在供应链安全中的作用是？","o":["列明组件及版本与许可，使新披露漏洞可快速定位受影响产品","加速编译","美化代码","替代测试"],"a":0,"e":"有 SBOM 才能在 CVE 出现时快速映射影响面（如 Log4j 事件），是供应链响应的基础。（OSG 第20章 供应链安全）","f":"20 软件开发安全","v":[]},{"id":"v2d8-19","d":"域8 软件开发安全","w":3,"q":"'依赖混淆（dependency confusion）'攻击利用的是？","o":["内部包名被攻击者在公共仓库抢先注册，构建机拉取恶意同名包","域名拼错","证书过期","口令复用"],"a":0,"e":"构建工具解析顺序被利用注入恶意包；对策：内部代理/仓库白名单与签名校验。（OSG 第20章 供应链攻击）","f":"20 软件开发安全","v":[]},{"id":"v2d8-20","d":"域8 软件开发安全","w":3,"q":"CI/CD 流水线的安全控制最应包括？","o":["构建凭据最小权限与短时效、代码/制品签名、不可变制品与变更审计","共享管理员口令","公开构建日志含密钥","跳过测试直接部署"],"a":0,"e":"流水线是供应链攻击核心目标，需凭据治理、签名与可追溯（可重现构建）。（OSG 第20章 CI/CD 安全）","f":"20 软件开发安全","v":[]},{"id":"v2d8-21","d":"域8 软件开发安全","w":3,"q":"'基础设施即代码（IaC）'的安全价值是？","o":["环境可版本化评审、基线可扫描（防漂移）、变更可审计可回滚","减少程序员","提高电费","替代需求分析"],"a":0,"e":"IaC 让安全策略（加密、网络规则）成为可评审代码，配合策略即代码实现规模化合规。（OSG 第20章 IaC）","f":"20 软件开发安全","v":[]},{"id":"v2d8-22","d":"域8 软件开发安全","w":3,"q":"变更发布的'蓝绿/金丝雀'策略对安全的意义是？","o":["小流量灰度限制缺陷/攻击影响面并提供快速回滚","让发布更炫酷","减少日志","绕过测试"],"a":0,"e":"渐进交付把爆炸半径控制在小部分用户，且保留快速回退能力，是韧性与安全的交汇。（OSG 第20章 发布工程）","f":"20 软件开发安全","v":[]},{"id":"v2d8-23","d":"域8 软件开发安全","w":3,"q":"开源组件引入治理的正确做法是？","o":["随意复制粘贴 Stack Overflow 代码","组件准入清单+版本与许可证管理+持续 CVE 监控与更新机制","一律禁止开源","只看 star 数选型"],"a":1,"e":"开源治理平衡复用效率与供应链风险：准入、SBOM、持续监控、及时升级。一刀切禁用不现实。（OSG 第20章 第三方组件治理）","f":"20 软件开发安全","v":[]},{"id":"v2d8-24","d":"域8 软件开发安全","w":3,"q":"数据库编程中防注入的参数化查询为什么有效？","o":["SQL 结构与数据分离，输入只作为数据绑定不会被解析为 SQL 语法","它加密了查询","它隐藏了表名","它限制了返回行数"],"a":0,"e":"预编译将语句结构固化，用户输入无法改变语义，从根上阻断注入。（OSG 第21章 注入防御）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-25","d":"域8 软件开发安全","w":3,"q":"文件上传功能的主要风险与对策是？","o":["上传 Webshell；校验类型/内容、重命名存储、隔离目录与禁执行权限","上传慢；加带宽","占空间；加硬盘","文件名乱码；统一编码"],"a":0,"e":"上传可执行内容是最直接的 RCE 途径之一，需多层校验与存储隔离（对象存储/无执行权限）。（OSG 第21章 文件上传攻击）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-26","d":"域8 软件开发安全","w":3,"q":"日志中记录用户明文口令以便'排查登录问题'。该做法的问题是？","o":["绝不记录明文口令；记录事件元数据（结果、来源、时间）即可且需脱敏策略","日志会太大","违反配色规范","口令含中文"],"a":0,"e":"口令属最高敏感数据，任何日志不得留存明文；敏感字段日志需脱敏与最小化。（OSG 第20章 安全日志实践）","f":"20 软件开发安全","v":[]},{"id":"v2d8-27","d":"域8 软件开发安全","w":3,"q":"'双态验证（dual validation/client+server）'要求输入校验在哪里执行？","o":["仅前端即可","服务端必须执行最终校验，前端校验只为体验","仅数据库触发器","无需校验"],"a":1,"e":"前端可被绕过（直接调接口），服务端校验是唯一可信防线；数据库约束作最后兜底。（OSG 第20章 输入验证）","f":"20 软件开发安全","v":[]},{"id":"v2d8-28","d":"域8 软件开发安全","w":3,"q":"恶意代码中'病毒、蠕虫、木马'的分类区别是？","o":["病毒需宿主文件传播；蠕虫自传播无需宿主；木马伪装成正常程序诱骗执行","三者完全相同","蠕虫必须邮件附件","木马会自复制"],"a":0,"e":"分类关键在传播与伪装机制：病毒依附宿主、蠕虫利用网络自治传播、木马靠社会工程伪装。（OSG 第21章 恶意代码类型）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-29","d":"域8 软件开发安全","w":3,"q":"勒索软件'双勒索'策略指的是？","o":["加密数据+窃取数据以公开为威胁，使'仅靠备份恢复'不再足够","两次加密同一文件","同时感染两台电脑","勒索两种货币"],"a":0,"e":"先窃后加密，即便有备份仍面临泄露压力，因此需防泄露（准入、DLP）而非仅备份。（OSG 第21章 勒索软件）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-30","d":"域8 软件开发安全","w":3,"q":"Ransomware 防御的'3-2-1 备份'原则是指？","o":["3 份副本、2 种介质、1 份异地（且至少一份不可变/离线）","3 个机房、2 家厂商、1 年保留","3 次加密、2 个口令、1 个密钥","3 层防火墙、2 个 DMZ、1 个 VPN"],"a":0,"e":"3-2-1 提供介质与地域冗余，配合不可变/离线副本抵御定向破坏备份的勒索。（OSG 第21章/第18章 备份原则）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-31","d":"域8 软件开发安全","w":3,"q":"RAT（远程访问木马）与合法远程运维工具的区别判定依据是？","o":["是否经授权部署、用途与管控（合法工具可被滥用为攻击通道）","图标是否可爱","是否收费","端口号码"],"a":0,"e":"技术本质可能相同，判别在授权与意图；因此 EDR 需识别未授权远程工具的使用。（OSG 第21章 恶意代码）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-32","d":"域8 软件开发安全","w":3,"q":"'逻辑炸弹'的触发特征是？","o":["满足特定条件（日期/事件/缺失条件）时执行恶意动作","按小时随机发作","只感染宏","必须联网"],"a":0,"e":"逻辑炸弹潜伏至条件满足（如离职账户被删），审计与权限收敛可降低植入风险。（OSG 第21章 恶意代码）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-33","d":"域8 软件开发安全","w":3,"q":"Web Shell 被发现于上传目录。除删除文件外还应做的根除动作是？","o":["溯源入侵路径并修补（上传漏洞/弱口令）、清除持久化、轮换凭据、全面排查","重装 Web 服务器","修改网站标题","关闭网站永久"],"a":0,"e":"Web shell 是结果不是原因；须封入侵入口并排查其他后门，仅删文件必复发。（OSG 第21章 应用攻击响应）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-34","d":"域8 软件开发安全","w":3,"q":"'点击劫持（Clickjacking）'的标准防御是？","o":["X-Frame-Options/CSP frame-ancestors 限制页面被嵌入","口令复杂度","验证码","HTTPS"],"a":0,"e":"点击劫持靠 iframe 覆盖诱导点击，用响应头禁止被嵌入即可有效阻断。（OSG 第21章 点击劫持）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-35","d":"域8 软件开发安全","w":3,"q":"'安全需求'中的'合规追溯'意味着？","o":["需求可映射到法规/标准条款与对应测试证据，支撑审计","需求文档越厚越好","需求只给开发看","需求不需要评审"],"a":0,"e":"可追溯性使合规审计时能从条款定位到实现与验证证据。（OSG 第20章 需求管理）","f":"20 软件开发安全","v":[]},{"id":"v2d8-36","d":"域8 软件开发安全","w":3,"q":"敏捷开发中'每个迭代含安全工作项（安全用户故事）'体现的思想是？","o":["安全作为持续的一等公民而非阶段性关卡","安全只在上线前做","安全与开发对立","安全只由安全团队负责"],"a":0,"e":"把安全纳入 backlog 与 DoD，使其随交付节奏持续推进，避免'最后冲刺式'安全。（OSG 第20章 敏捷安全）","f":"20 软件开发安全","v":[]},{"id":"v2d8-37","d":"域8 软件开发安全","w":3,"q":"'净化库/框架默认安全（secure by default）'的价值是？","o":["框架默认转义/参数化，开发者不显式操作也安全，减少人为遗漏","运行更快","界面更好看","代码更少收费更低"],"a":0,"e":"默认安全（如模板引擎自动转义、ORM 参数化）把安全兜底内置，显著降低出错面。（OSG 第20章 安全设计）","f":"20 软件开发安全","v":[]},{"id":"v2d8-38","d":"域8 软件开发安全","w":3,"q":"移动应用把 API 密钥硬编码在客户端。正确的认识是？","o":["客户端密钥即公开，应改为服务端代理与按设备/用户的短期令牌","混淆代码即可保护密钥","只发布 iOS 版就安全","密钥短一点就没事"],"a":0,"e":"客户端任何'秘密'都可被提取，混淆只增加成本；正确架构是密钥留服务端、客户端持可撤销的短期凭据。（OSG 第20章 密钥管理）","f":"20 软件开发安全","v":[]},{"id":"v2d8-39","d":"域8 软件开发安全","w":3,"q":"购入商业软件要求供应商提供'安全开发证明'。最有价值的证据是？","o":["第三方评估/认证（如 ISO 27001、渗透测试摘要、SBOM 与漏洞响应 SLA）","供应商获奖证书","销售承诺邮件","界面截图"],"a":0,"e":"需独立可验证的证据链：认证、测试摘要、SBOM 与漏洞响应承诺；营销材料无证明力。（OSG 第20章 采购与供应链）","f":"20 软件开发安全","v":[]},{"id":"v2d8-40","d":"域8 软件开发安全","w":3,"q":"关于'数据库安全编程'，最应避免的做法是？","o":["使用参数化与存储过程的权限边界","应用账号被授予 DBA/sysadmin 全权以便'少出权限问题'","最小权限的专用数据库账号","关键操作记录审计日志"],"a":1,"e":"应用连接使用 DBA 权限会放大注入危害（堆叠查询删库），应最小权限专用账号。（OSG 第21章 注入危害与数据库安全）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-41","d":"域8 软件开发安全","w":3,"q":"'仓库管理员（库管）式攻击'中攻击者直接向开源项目提交恶意提交（如 xz-utils 后门事件）。防御的关键是？","o":["维护者身份与提交审核、构建可重现与制品签名验证","禁止开源","只信任最新版本","关闭 issue"],"a":0,"e":"该类攻击考验上游信任链：代码评审严谨性、维护者账户保护、可重现构建与签名让下游可验真伪。（OSG 第20章 供应链安全）","f":"20 软件开发安全","v":[]},{"id":"v2d8-42","d":"域8 软件开发安全","w":3,"q":"应用安全测试中 DAST 无法有效发现的问题是？","o":["反射型 XSS 行为缺陷","业务逻辑漏洞（如越权流程绕过）因其需要理解业务语义","端口开放","证书过期"],"a":1,"e":"DAST 从外部探测，难以理解业务规则；逻辑漏洞需要人工/源码/业务级测试。（OSG 第15/20章 测试局限性）","f":"20 软件开发安全","v":[]},{"id":"v2d8-43","d":"域8 软件开发安全","w":3,"q":"'密码学误用'中最常见的开发错误是？","o":["使用 ECDSA/DSA 复用 nonce 导致私钥可推算、自造算法、固定 IV、ECB 模式","变量命名不佳","缺少注释","测试覆盖不足"],"a":0,"e":"密码学误用（固定 IV、ECB、自造协议、nonce 复用）是高危且常见；应使用成熟库的高层 API（AEAD）。（OSG 第20章 安全编码/密码学）","f":"20 软件开发安全","v":[]},{"id":"v2d8-44","d":"域8 软件开发安全","w":3,"q":"Web 会话管理中'会话固定（Session Fixation）'攻击的防御是？","o":["登录成功后重置会话 ID（并启用 HttpOnly/Secure/SameSite 属性）","使用更长会话 ID","定期清理数据库","开启 gzip"],"a":0,"e":"固定攻击诱使受害者使用攻击者预置的会话 ID；认证后必须更换 ID 并配合 Cookie 安全属性。（OSG 第21章 会话攻击）","f":"21 恶意代码和应用攻击","v":[]},{"id":"v2d8-45","d":"域8 软件开发安全","w":3,"q":"上线后曝出所依赖组件的 RCE 漏洞且已有在野利用。最优先的行动序列是？","o":["定位使用面（SBOM）→评估暴露与缓解（WAF/配置）→紧急补丁/升级（含回滚预案）→验证与通报","先开会给责任定性","等待厂商下个版本","关闭所有服务等待指示"],"a":0,"e":"供应链应急按'定位-缓解-修复-验证'推进；问责与等待只会扩大窗口，但修复也需回滚预案防次生故障。（OSG 第20章 供应链响应）","f":"20 软件开发安全","v":[]}];
var EXAMBANK=[{"id":"ex1","d":"域1 安全与风险管理","w":3,"q":"某上市公司董事会要求 CISO 每季度汇报'安全投入是否物有所值'。以下哪个汇报方式最能回答这个问题？","o":["列出已采购的安全产品清单","对比控制成本与风险降低（ALE 变化）的量化分析（ROSI）","汇报漏洞扫描总数","展示培训签到率"],"a":1,"e":"ROSI=（风险避免额-控制成本）/控制成本，用处置前后的 ALE 差证明价值。产品清单、漏洞数与签到率都不是价值论证。（OSG 第1章 安全投资回报）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex2","d":"域1 安全与风险管理","w":3,"q":"员工将客户数据上传至未授权的 SaaS 工具处理。这最直接违反的原则是？","o":["纵深防御","影子 IT 治理（未经审批的服务使用）","最小权限只针对管理员","默认放行"],"a":1,"e":"影子 IT 绕过数据治理与 DLP 覆盖，应通过 CASB/SSO 接管与审批流治理。其余选项与场景无关。（OSG 第1/5章 云服务治理）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex3","d":"域1 安全与风险管理","w":3,"q":"公司拟部署新 ERP。风险评估显示数据泄露 ALE 为 800 万，部署 DLP 后 ALE 降至 300 万，方案年成本 400 万。从纯量化角度应？","o":["不部署：成本高于收益","部署：年化收益 500 万 > 成本 400 万","两者无差别","必须买保险"],"a":1,"e":"风险避免额=800-300=500 万>400 万成本，量化上值得部署（还应结合定性因素）。（OSG 第1章 成本收益分析）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex4","d":"域1 安全与风险管理","w":3,"q":"审计委员会问：'我们接受了哪些剩余风险？'最恰当的回答来源是？","o":["工程师的技术博客","经管理层正式签署的风险登记册（Risk Register）中'已接受'条目","防火墙日志","厂商白皮书"],"a":1,"e":"剩余风险的接受必须被记录并经所有者/管理层批准，风险登记册是权威来源。（OSG 第1章 风险登记册）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex5","d":"域1 安全与风险管理","w":3,"q":"GDPR 下，公司聘请新供应商代为处理客户数据。签约前最关键的动作是？","o":["签保密协议即可","签订数据处理协议（DPA）并完成数据保护影响评估与尽职调查","把数据先脱敏","通知员工"],"a":1,"e":"处理者必须受 DPA 约束（处理目的、安全措施、子处理者、审计权等），并评估其合规能力。仅 NDA 不足以满足 GDPR 第28条。（OSG 第4章 隐私合规）","f":"4 法律、法规和合规","v":[]},{"id":"ex6","d":"域1 安全与风险管理","w":3,"q":"执法人员到前台要求带走一台正在运行的服务器。最恰当的第一步是？","o":["立即拔电源交出","联系法务/管理层核验法律文书（搜查令）范围，并做好证据交接记录","拒绝并驱逐","让运维删除敏感数据"],"a":1,"e":"应核验授权与范围、通知法务，全程记录链监管；断电毁证据、对抗或删数据都可能违法。（OSG 第19章/第4章 执法配合）","f":"4 法律、法规和合规","v":[]},{"id":"ex7","d":"域1 安全与风险管理","w":3,"q":"公司开始提供面向欧盟用户的在线服务。隐私合规上最优先落实的是？","o":["GDPR 要求：确定法律依据、隐私声明、数据主体权利流程与任命数据保护官（如适用）","部署 WAF","等保备案","员工着装规范"],"a":0,"e":"面向欧盟提供服务即落入 GDPR 属地管辖，须先落实核心义务再谈技术防护。WAF/等保是其他维度。（OSG 第4章 GDPR）","f":"4 法律、法规和合规","v":[]},{"id":"ex8","d":"域1 安全与风险管理","w":3,"q":"新任 CISO 发现组织没有任何成文安全政策。第一步应？","o":["立即购买全套安全产品","获得管理层授权，基于业务与风险评估制定分层政策体系","对全员进行渗透测试","先写操作规程"],"a":1,"e":"政策是治理起点，必须自上而下授权并与风险对齐；先买产品或先写底层规程都是本末倒置。（OSG 第1章 政策体系）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex9","d":"域1 安全与风险管理","w":3,"q":"董事会批准了'风险偏好声明'。它对一线安全团队的实际作用是？","o":["装饰性文件","为阈值设定与例外审批提供依据：超出偏好的风险必须升级处置","替代技术标准","用于计算工资"],"a":1,"e":"风险偏好指导可容忍风险边界，落到策略阈值（如可接受漏洞级别）与升级机制。（OSG 第1章 风险偏好）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex10","d":"域1 安全与风险管理","w":3,"q":"业务方质疑：'安全团队总说不行'。为改善安全与业务的协作，最有效的做法是？","o":["安全团队升格为独立王国","将安全嵌入业务决策流程（项目早期介入、提供分级可选方案而非单一否决）","减少安全人员","所有决策由安全团队拍板"],"a":1,"e":"治理层面应让安全成为业务使能者：早期介入+风险分级选项，把'行/不行'变成'怎么做行'。（OSG 第1章 安全治理成熟度）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex11","d":"域1 安全与风险管理","w":3,"q":"某组织将'所有系统每年做一次渗透测试'写入政策。更符合风险导向的改进是？","o":["全部系统每季度测试","按资产关键性与变更频率调整测试深度与周期（关键系统更高频）","取消渗透测试","只测试新系统"],"a":1,"e":"安全资源应随风险差异化配置；一刀切年度或一刀切季度都不经济，应基于风险分级。（OSG 第1/15章 基于风险的测试策略）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex12","d":"域1 安全与风险管理","w":3,"q":"供应链攻击频发，管理层问'我们的软件供应链风险有多大'。最恰当的评估起点是？","o":["清点软件资产与依赖（含 SBOM）、映射供应商与构建流程，识别单点与信任链","按营收给供应商排序","统计软件采购金额","询问 IT 是否'感觉安全'"],"a":0,"e":"供应链风险评估从资产/依赖/流程清点开始，才能定位关键信任节点。金额与感觉不是风险度量。（OSG 第2章 供应链风险管理）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"ex13","d":"域1 安全与风险管理","w":3,"q":"安全团队建议'禁止 USB 存储'被业务拒绝，因现场设备需拷贝日志。最佳实践是？","o":["强制禁用并接受业务中断","提供受控替代（专用加密 U 盘+审批/DLP 白名单）并记录剩余风险","放任不管","只禁普通员工"],"a":1,"e":"被拒绝的控制应寻找业务可行的替代方案并升级剩余风险决策，而非硬顶或放任。（OSG 第1章 控制与业务对齐）","f":"1 实现安全治理的原则和策略","v":[]},{"id":"ex14","d":"域1 安全与风险管理","w":3,"q":"人员风险控制'背景调查'的比例与深度应依据？","o":["统一最深标准人人平等","岗位敏感性与访问级别（特权/财务岗位更深、复检周期更短）","入职时间先后","员工自愿"],"a":1,"e":"背景调查应基于岗位风险分级，并注意合法性（授权与用途限制）。（OSG 第2章 背景调查）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"ex15","d":"域1 安全与风险管理","w":3,"q":"为防止开发人员离职时'带走'核心代码，最合理的组合控制是？","o":["离职时格式化其电脑","最小权限+代码库访问审计+DLP+知识产权协议（NDA/IP 归属）+权限随离职即时回收","禁止开发人员远程办公","代码只保存在个人电脑"],"a":1,"e":"组合管理（协议）与技术（权限、审计、DLP）+流程（离职回收）才能覆盖全周期；单点措施不足。（OSG 第2章 人员风险控制）","f":"2 人员安全和风险管理的概念","v":[]},{"id":"ex16","d":"域2 资产安全","w":3,"q":"公司数据分类标准只有'公开/机密'两级，导致日常内部文档大量被标'机密'。结果是？","o":["更安全了","分类失去区分度，保护资源错配（全按机密保护成本过高、放任又不合规）","减少存储成本","没有影响"],"a":1,"e":"过粗的分类使标签失去信息量，控制无法分层；应增设'内部'级并给出判定示例。（OSG 第5章 分类体系设计）","f":"5 保护资产安全","v":[]},{"id":"ex17","d":"域2 资产安全","w":3,"q":"客户要求'其全部数据在合同终止后 30 天内删除'。哪类数据可能依法除外？","o":["营销素材","受法定保留义务约束的记录（如交易/审计凭证）","公司内部 PPT","官网新闻稿"],"a":1,"e":"法定保留（税务、审计、反洗钱等）优先于合同删除，但应限定用途并告知客户。（OSG 第5章 数据保留与合同）","f":"5 保护资产安全","v":[]},{"id":"ex18","d":"域2 资产安全","w":3,"q":"DLP 部署后误报率高达 90%，业务抱怨审批工单淹没。最优先的改进步骤是？","o":["关闭 DLP","基于真实数据样本调优策略（置信度分级、白名单、分阶段阻断→告警）","全部门检讨","换厂商"],"a":1,"e":"DLP 成败在策略调优与运营（分阶段上线、置信分级），而不是推倒重来。（OSG 第5章 DLP 运营）","f":"5 保护资产安全","v":[]},{"id":"ex19","d":"域2 资产安全","w":3,"q":"要为'生产数据库导出到开发环境'建立安全流程。核心控制是？","o":["限制导出时间段","静态脱敏（或合成数据）+ 导出审批与记录","加大开发环境磁盘","开发人员签 NDA"],"a":0,"e":"以脱敏/合成数据消除敏感暴露，配流程审批与审计；NDA 与时段限制不能保护数据本身。（OSG 第5章 测试数据安全）","f":"5 保护资产安全","v":[]},{"id":"ex20","d":"域2 资产安全","w":3,"q":"员工笔记本丢失，其中存有未加密的客户名单。这构成？","o":["仅财产损失","个人数据泄露事件，可能触发法定通报与响应流程","无事件","内部管理问题无需上报"],"a":1,"e":"未加密 PII 丢失是安全事件：需评估范围、通知义务并复盘控制（全盘加密、远程擦除）。（OSG 第5章 终端数据保护/第17章 事件通报）","f":"5 保护资产安全","v":[]},{"id":"ex21","d":"域2 资产安全","w":3,"q":"公司准备销毁一批含 PHR（个人健康记录）的退役服务器硬盘。合规的做法是？","o":["格式化两遍","按 NIST 800-88 净化指南执行净化/销毁并留存记录（含验证与责任人）","转卖二手商并要求其删除","捐赠给学校前删除数据"],"a":1,"e":"敏感介质处置应遵循 NIST SP 800-88（清除/净化/销毁分级）并保留证据链；转卖捐赠不可接受。（OSG 第5章 介质净化）","f":"5 保护资产安全","v":[]},{"id":"ex22","d":"域2 资产安全","w":3,"q":"数据所有权长期'由 IT 代管'导致分类混乱。最佳整改是？","o":["IT 继续全权代管","按业务线任命数据所有者并明确分类与授权职责，IT 转任托管（Custodian）","每季度全员投票决定分类","取消分类"],"a":1,"e":"分类责任必须归于理解业务价值的所有者；IT 是执行者。治理角色清晰是数据安全前提。（OSG 第5章 数据治理角色）","f":"5 保护资产安全","v":[]},{"id":"ex23","d":"域2 资产安全","w":3,"q":"备份管理员为'提高备份成功率'将失败告警关闭。风险后果与正确做法是？","o":["无后果","静默失败会让'看似有备份'在恢复时才发现不可用；应恢复告警并定期恢复演练","把备份频率加倍","更换备份软件"],"a":1,"e":"备份只有经过恢复验证才可信；监控告警+周期性恢复测试是备份保障的双支柱。（OSG 第5/18章 备份保证）","f":"5 保护资产安全","v":[]},{"id":"ex24","d":"域2 资产安全","w":3,"q":"GDPR 下'数据处理记录（ROPA）'的用途是？","o":["向监管证明处理活动的可问责性（目的、依据、类别、流向、保护措施）","降低存储成本","计算员工绩效","加密数据库"],"a":0,"e":"ROPA 是 Article 30 义务，是审计与事件响应（判断影响范围）的基础文档。（OSG 第4/5章 隐私文档）","f":"5 保护资产安全","v":[]},{"id":"ex25","d":"域2 资产安全","w":3,"q":"公司允许在低等级系统中重用'脱敏后'的客户手机号做测试。安全团队应额外确认？","o":["无需确认","脱敏不可逆且不可关联（防重识别），符合用途限制与假名化要求","测试环境无需关注","手机号不属于个人信息"],"a":1,"e":"手机号是 PII；重用须确保防重识别（结合其他字段不能还原身份），否则仍属处理个人信息。（OSG 第5章 假名化与去标识化）","f":"5 保护资产安全","v":[]},{"id":"ex26","d":"域3 安全架构与工程","w":3,"q":"设计新支付系统时要求'任何单点失陷都不能同时发起与审批支付'。这属于哪种设计活动产出？","o":["威胁建模识别的滥用场景（abuse case）驱动的职责分离设计","性能压测需求","界面原型","容量规划"],"a":0,"e":"威胁建模把'如果被攻破会怎样'转化为设计约束（SoD、双人控制），是安全设计的核心方法。（OSG 第8章/第20章 威胁建模）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"ex27","d":"域3 安全架构与工程","w":3,"q":"选择文件完整性监控方案时，哈希算法应优先？","o":["MD5（速度快）","SHA-256 及以上（抗碰撞），配合可信基线与告警","CRC32","自定义算法保密"],"a":1,"e":"MD5/CRC32 已可碰撞，不适合完整性安全用途；且应保密的是密钥而非算法。（OSG 第7章 完整性机制）","f":"7 PKI 和密码应用","v":[]},{"id":"ex28","d":"域3 安全架构与工程","w":3,"q":"系统需对交易流水'可审计且不可篡改'。哈希链/默克尔树与数字签名组合的作用是？","o":["仅加速查询","任何人可验证记录序列完整性与来源，篡改可被发现","自动删除旧记录","压缩存储"],"a":1,"e":"链式哈希+签名使历史不可抵赖可验证（审计日志防篡改常用设计），非为性能或删除。（OSG 第7章 密码应用）","f":"7 PKI 和密码应用","v":[]},{"id":"ex29","d":"域3 安全架构与工程","w":3,"q":"密钥管理中'密钥分离（key separation）'原则指？","o":["一把密钥多用提高效率","不同用途（加密/签名/传输）使用不同密钥，避免一处失陷殃及全部","密钥越少越好","密钥必须每月公开轮换"],"a":1,"e":"密钥按用途与数据分类分离，缩小泄露影响面，是 KMS 设计基本原则。（OSG 第7章 密钥管理）","f":"7 PKI 和密码应用","v":[]},{"id":"ex30","d":"域3 安全架构与工程","w":3,"q":"证书到期导致全站故障后，运维要求'自动提醒'。除到期监控外，PKI 治理还应包括？","o":["证书清单/Inventory 与自动续期（ACME），消除手动管理盲区","把证书有效期改为 10 年","停用 HTTPS","每台服务器单独手工管理"],"a":0,"e":"证书治理=清单+监控+自动化续期+应急替换流程；超长期证书扩大失陷窗口且已被 CA/B 论坛限制。（OSG 第7章 PKI 运营）","f":"7 PKI 和密码应用","v":[]},{"id":"ex31","d":"域3 安全架构与工程","w":3,"q":"多租户 SaaS 的'租户数据隔离'最应从哪里实现？","o":["仅靠 UI 登录后过滤","架构与数据层强制隔离（独立 schema/库或行级租户标识+服务端强制校验）","租户名字不同即可","共享管理员账号"],"a":1,"e":"隔离必须是服务端/数据层结构性保证，UI 过滤可被绕过（跨租户越权）。（OSG 第8章 安全架构）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"ex32","d":"域3 安全架构与工程","w":3,"q":"为何'防火墙+杀毒'仍不能防住内部合法账号被冒用？说明的问题是？","o":["产品性能不足","边界防护无法覆盖身份层威胁，需 IAM 强认证与行为监控（零信任）","说明应购买更多防火墙","内部威胁无法防范"],"a":1,"e":"以身份为中心的攻击绕过边界模型，需要 MFA、最小权限与 UEBA 等身份层控制；'无法防范'是错误结论。（OSG 第8章 架构演进/第14章）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"ex33","d":"域3 安全架构与工程","w":3,"q":"安全架构评审要求标注系统的'信任边界'。其主要作用是？","o":["美观","明确数据/控制跨越信任级别时必须验证与校验的位置（攻击面分析单元）","用于计费","仅用于文档页数"],"a":1,"e":"信任边界是威胁建模的构件：跨边界必须认证、校验与最小化，边界识别直接驱动对策设计。（OSG 第8章 信任边界）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"ex34","d":"域3 安全架构与工程","w":3,"q":"设备固件签名校验失败时应'拒绝启动'而非'提示并继续'。这体现的原则是？","o":["可用性优先","故障安全（Fail Securely）默认拒绝","完全仲裁","心理可接受性"],"a":1,"e":"验证失败进入安全状态（拒绝运行）防止未授权固件执行，是 fail-secure 的体现。（OSG 第8章 设计原则）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"ex35","d":"域3 安全架构与工程","w":3,"q":"数据库'视图+存储过程'方式对外提供查询，其安全意义是？","o":["提高 SQL 性能","强制 mediation：用户只能经预定义路径访问数据，可嵌入授权与推理控制","方便 DBA 摸鱼","减少备份"],"a":1,"e":"视图/存储过程是参考监视器思想的数据库实现：收敛访问路径、防推理与越权查询。（OSG 第8章 数据库安全设计）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"ex36","d":"域3 安全架构与工程","w":3,"q":"产品团队想用'联网拍照识图'功能上传用户相册。隐私设计（PbD）要求他们先做什么？","o":["直接上线看反馈","进行隐私影响评估（PIA/DPIA），最小化采集并告知与征得同意","把照片存满再评估","仅匿名化文件名"],"a":1,"e":"隐私设计要求在设计期评估高风险处理的必要性与影响，最小化+透明+同意先行。（OSG 第5/8章 隐私设计）","f":"8 安全模型、设计和能力的原则","v":[]},{"id":"ex37","d":"域3 安全架构与工程","w":3,"q":"流密码（如 ChaCha20）与分组密码的适用差异，正确的是？","o":["流密码适合高速流式/低延迟场景，但 nonce 绝不能重复","流密码只能加密文本","分组密码不能加密视频","两者不能同时存在于一个系统"],"a":0,"e":"流密码性能好、无需填充，但密钥流重复即被破（nonce 管理）；分组密码配模式适合块数据。（OSG 第6章 密码算法）","f":"6 密码学和对称密钥算法","v":[]},{"id":"ex38","d":"域3 安全架构与工程","w":3,"q":"为什么'完整性'保护（如签名）不能防止攻击者截获并转发原始合法消息（重放）？","o":["签名验证会通过，需序列号/时间戳/nonce 等抗重放机制","签名太慢","哈希长度不够","加密强度不足"],"a":0,"e":"重放的消息本身签名有效，须在协议中加入新鲜性因子（nonce/时间窗/序号）。（OSG 第7章 抗重放）","f":"7 PKI 和密码应用","v":[]},{"id":"ex39","d":"域4 通信与网络安全","w":3,"q":"分支机构通过 IPSec 站点到站点 VPN 连接总部。IKE 的作用是？","o":["加密业务数据","协商并建立安全关联（SA），完成认证与密钥交换","转发数据包","分配 IP 地址"],"a":1,"e":"IKE 负责认证与协商 SA（算法、密钥），ESP/AH 用协商结果保护数据；DHCP 分配地址。（OSG 第12章 IPSec）","f":"12 安全通信与网络攻击","v":[]},{"id":"ex40","d":"域4 通信与网络安全","w":3,"q":"网站遭 CC 攻击（海量合法样式 HTTP 请求耗尽应用资源）。有效缓解组合是？","o":["扩容+速率限制+人机验证（挑战）+CDN/WAF 清洗","只加带宽","修改网站标题","关闭 HTTPS"],"a":0,"e":"应用层 DoS 需多层：识别与速率管控、挑战验证、边缘清洗与容量冗余；单纯加带宽不可持续。（OSG 第12章 应用层DoS）","f":"12 安全通信与网络攻击","v":[]},{"id":"ex41","d":"域4 通信与网络安全","w":3,"q":"BGP 劫持导致流量绕道。防护与发现手段是？","o":["RPKI/ROA 验证宣告合法性 + 路由监控（异常路径告警）","更换路由器品牌","关闭 BGP","加密所有路由器密码"],"a":0,"e":"BGP 劫持靠源验证（RPKI）与路由异常监测缓解；密码加密与品牌无关，也不能关闭 BGP。（OSG 第11章 路由安全）","f":"11 安全网络架构和组件","v":[]},{"id":"ex42","d":"域4 通信与网络安全","w":3,"q":"内网监控发现主机向境外 IP 周期性发送 DNS 查询且域名随机长串。最可能的判断与处置？","o":["正常解析行为","疑似 DNS 隧道 C2：隔离主机、抓包取证、查进程并按事件流程处置","直接重装系统","调大 DNS 超时"],"a":1,"e":"随机长域名+周期性外联是 DNS 隧道典型特征，应先取证分析再处置（防误伤与保证据）。（OSG 第12章 隐蔽通道/第17章 响应）","f":"12 安全通信与网络攻击","v":[]},{"id":"ex43","d":"域4 通信与网络安全","w":3,"q":"公司部署了 NGFW，但仍发生数据库被内网横向扫描。最可能缺失的措施？","o":["内网东西向分段与访问策略（微分段/内网防火墙策略）","更换 NGFW 品牌","增加公网带宽","部署打印机"],"a":0,"e":"边界设备不管内网东西向；需内部分段与最小互联策略。换品牌与带宽无关。（OSG 第11章 内网分段）","f":"11 安全网络架构和组件","v":[]},{"id":"ex44","d":"域4 通信与网络安全","w":3,"q":"员工在家办公访问内网系统。相比'开放系统直接暴露公网'，更好的方案是？","o":["ZTNA/VPN+MFA+终端合规检查，按身份与设备状态授权访问","把所有系统映射到公网 80 端口","共享一个远程账号","仅靠 IP 白名单"],"a":0,"e":"零信任接入（身份+设备+上下文）将暴露面收敛到按需会话；公网直曝、共享账号与静态白名单风险高。（OSG 第11章 远程访问安全）","f":"11 安全网络架构和组件","v":[]},{"id":"ex45","d":"域4 通信与网络安全","w":3,"q":"交换机端口安全配置为'每个端口最多 1 个 MAC'。防的攻击是？","o":["MAC 泛洪与非法接入点接入","IP 分片攻击","应用层注入","密码喷洒"],"a":0,"e":"端口 MAC 限制阻断 CAM 泛洪与私接设备；与分片/注入/账号攻击无关。（OSG 第12章 二层安全）","f":"12 安全通信与网络攻击","v":[]},{"id":"ex46","d":"域4 通信与网络安全","w":3,"q":"TLS 证书配置评估发现服务器支持 TLS1.0/1.1 与弱套件。风险与整改？","o":["无风险，兼容性好","旧版本存在已知弱点（BEAST/降级等），应禁用并仅启用 TLS1.2+强套件（前向保密）","升级网卡驱动","增加防火墙规则"],"a":1,"e":"过时协议版本是被利用的常见入口，应按现代基线（TLS1.2/1.3、AEAD、PFS）收紧。（OSG 第12章 传输加密）","f":"12 安全通信与网络攻击","v":[]},{"id":"ex47","d":"域4 通信与网络安全","w":3,"q":"网络分段将 OT（工控）网与 IT 网隔离，仅经单向网闸/严格防火墙白名单互通。这样设计的原因是？","o":["OT 协议太贵","OT 可用性/安全（safety）要求高、补丁窗口长，隔离降低 IT 侧威胁传导","提高 IT 网速","法规要求统一网络"],"a":1,"e":"Purdue 分层与最小互通保护 OT 免受 IT 侧勒索/蠕虫影响，兼顾可预测性。（OSG 第9章/第11章 工控网络）","f":"11 安全网络架构和组件","v":[]},{"id":"ex48","d":"域4 通信与网络安全","w":3,"q":"VPN 网关日志显示同一账号同时从两个国家登录。处置应为？","o":["正常现象","疑似凭据泄露：吊销会话、强制重认证、排查终端并重置凭据","等待用户自行下线","仅发提醒邮件"],"a":1,"e":"并发异地会话是典型失陷信号，需立即会话治理与凭据重置，再复核 MFA 是否被钓鱼绕过。（OSG 第13/17章 会话安全）","f":"12 安全通信与网络攻击","v":[]},{"id":"ex49","d":"域4 通信与网络安全","w":3,"q":"邮件安全网关已拦截恶意附件，但 CFO 仍收到'老板要求转账'的纯文本诈骗邮件。还需补强的措施是？","o":["针对性钓鱼演练+财务流程双人验证（转账变更需电话回拨确认）","提高网关灵敏度至全拦附件","封禁 CFO 邮箱","改用传真"],"a":0,"e":"BEC 无恶意附件，靠流程验证（回拨、双人）与高管定向演练防御；全拦附件误伤正常业务。（OSG 第2/12章 BEC 防御）","f":"12 安全通信与网络攻击","v":[]},{"id":"ex50","d":"域4 通信与网络安全","w":3,"q":"NAC 准入系统要求'个人手机检查合规后才能进 Wi-Fi'。这体现的控制逻辑是？","o":["身份+设备状态作为接入决策输入（零信任准入）","仅记录 MAC","按部门分配带宽","强制关机"],"a":0,"e":"NAC 将设备健康（补丁/越狱/EDR）纳入准入条件，实现基于状态的动态访问。（OSG 第11章 网络准入控制）","f":"11 安全网络架构和组件","v":[]},{"id":"ex51","d":"域4 通信与网络安全","w":3,"q":"跨地域多地部署时，DNS 轮询与全局负载均衡（GSLB）的可用性意义是？","o":["加快单次解析","用户被调度到健康就近站点，单站故障可切换（可用性设计）","隐藏 DNS 记录","替代证书"],"a":1,"e":"GSLB 结合健康检查实现站点级故障转移，是通信服务高可用设计（OSG 第11章 高可用）。（OSG 第11章 高可用架构）","f":"11 安全网络架构和组件","v":[]},{"id":"ex52","d":"域5 身份与访问管理","w":3,"q":"ERP 实施后 200 名用户权限直接照搬旧系统'全员可查全部订单'。最应先做的是？","o":["上线后再慢慢收","按角色重新设计权限（RBAC），以岗位与 SoD 原则映射并复核","让用户自行申报权限","关闭订单模块"],"a":1,"e":"新系统是收敛权限的机会；RBAC+SoD 设计+所有者复核可避免权限蔓延固化。（OSG 第14章 权限设计）","f":"14 控制和监控访问","v":[]},{"id":"ex53","d":"域5 身份与访问管理","w":3,"q":"员工在外网输入了域账号口令到钓鱼站。已重置口令。还需必须处理的是？","o":["无事可做","吊销所有活跃会话与令牌（Kerberos 票据、refresh token、MFA 重绑核查）","仅改回原口令","发内部通报点名"],"a":1,"e":"凭据泄露后已发放的票据/会话依然有效，必须吊销+检查 MFA 注册是否被篡改。（OSG 第13/14章 凭据事件响应）","f":"13 管理身份和认证","v":[]},{"id":"ex54","d":"域5 身份与访问管理","w":3,"q":"要求'外包人员访问受限且可审计'。最合适的方案是？","o":["并入员工 AD 账号体系","独立身份域/租户+受限权限+会话审计，按合同到期自动回收","发放访客 Wi-Fi 即可","共享外包主管账号"],"a":1,"e":"第三方身份需隔离治理：独立主体、最小权限、可审计、生命周期与合同对齐。（OSG 第14章 第三方访问）","f":"14 控制和监控访问","v":[]},{"id":"ex55","d":"域5 身份与访问管理","w":3,"q":"密码策略改为'16 位以上口令短语+泄露库校验'后，撞库攻击仍成功。原因最可能是？","o":["口令短语天然不安全","用户在别处复用了相同口令且该处泄露（撞库），需 MFA 而非仅改策略","长度不够","加密算法弱"],"a":1,"e":"撞库利用跨站复用；结构化防御靠 MFA 与泄露监测，而非一味提高复杂度。（OSG 第13章 凭据攻击）","f":"13 管理身份和认证","v":[]},{"id":"ex56","d":"域5 身份与访问管理","w":3,"q":"特权操作要求'可审计到人'，但夜里值班需用共享 break-glass 账号应急。平衡做法是？","o":["取消 break-glass","break-glass 口令封存（保险柜/HSM）、使用触发告警、事后强制复盘归责","口令写在白板","每人一份相同口令"],"a":1,"e":"应急账号要'可用且可归责'：受控取用、即时告警、事后审计，而非取消或滥用。（OSG 第14章 应急访问管理）","f":"14 控制和监控访问","v":[]},{"id":"ex57","d":"域5 身份与访问管理","w":3,"q":"OIDC 登录流程中 access token 被存入 localStorage 并随页面泄漏给 XSS。改进方向是？","o":["改存 sessionStorage","遵循 token 最小暴露：短期令牌+HttpOnly Cookie（带 SameSite）或 BFF 模式，配合 CSP","token 加密后存 localStorage","换用 SAML"],"a":1,"e":"令牌暴露面设计（HttpOnly/短时效/BFF）+ XSS 防御比换存储位置更根本；SAML 同样有此类问题。（OSG 第13章 现代认证安全）","f":"13 管理身份和认证","v":[]},{"id":"ex58","d":"域5 身份与访问管理","w":3,"q":"用户画像显示某财务账号凌晨批量下载工资表。除技术阻断外，管理上最重要的动作是？","o":["按事件响应流程处理并判断是否内部滥用（HR/法务介入标准）","直接解雇","公开批评","忽略（可能是加班）"],"a":0,"e":"可疑行为需走分诊：技术取证+按政策升级 HR/法务，程序正义与证据完整并重。（OSG 第17/19章 内部威胁响应）","f":"14 控制和监控访问","v":[]},{"id":"ex59","d":"域5 身份与访问管理","w":3,"q":"为什么'加入域的员工 PC 上保存的缓存的 Kerberos 票据'是攻击者的重要目标？","o":["票据可被窃取并在有效期内重放（Pass-the-Ticket），实现免口令横向移动","票据包含口令明文","票据可跨林通用","票据永不过期"],"a":0,"e":"票据窃取（PtT）是 AD 横移常用手法，依赖 EDR、特权最小化与票据超时收敛。（OSG 第13章 Kerberos 攻击）","f":"13 管理身份和认证","v":[]},{"id":"ex60","d":"域5 身份与访问管理","w":3,"q":"Kerberos'黄金票据'攻击利用的是什么？","o":["krbtgt 账户密钥被攻破后可伪造任意 TGT","用户口令太短","时间不同步","DNS 投毒"],"a":0,"e":"掌握 krbbtgt 密钥即可自铸 TGT；域控失陷后必须重置 krbtgt（两次）以切断后门。（OSG 第13章 AD 攻击）","f":"13 管理身份和认证","v":[]},{"id":"ex61","d":"域5 身份与访问管理","w":3,"q":"'一年一次权限复核'导致复核流于形式（全选批准）。改进措施是？","o":["取消复核","将复核范围聚焦高风险权限与异常使用（基于使用日志的智能再认证）","增加表单字段","延长复核周期"],"a":1,"e":"以使用行为数据聚焦真正需要复核的授权，提升有效性；取消或形式化都失职。（OSG 第14章 访问再认证）","f":"14 控制和监控访问","v":[]},{"id":"ex62","d":"域5 身份与访问管理","w":3,"q":"员工角色变化后旧权限未清，称'迟早还用得上'。治理上的正确原则是？","o":["保留以备不时之需","转岗即触发权限再评估（transfer 事件驱动），不用的权限立即回收","权限只增不减","由员工自行决定"],"a":1,"e":"权限随职责变化（事件驱动）+定期复核，权限蔓延是内部风险主要来源。（OSG 第14章 权限生命周期）","f":"14 控制和监控访问","v":[]},{"id":"ex63","d":"域5 身份与访问管理","w":3,"q":"为降低'离职员工账号仍可访问 SaaS'风险，最系统的措施是？","o":["离职当天群发邮件提醒","建立 SaaS 目录与 SSO/SCIM 自动开通注销，并定期用登录日志比对在职名单","禁止使用 SaaS","手工逐个检查"],"a":1,"e":"身份联邦+自动化供给（SCIM）保证'一处离职、处处失效'，日志比对兜底。（OSG 第13章 身份供给）","f":"13 管理身份和认证","v":[]},{"id":"ex64","d":"域5 身份与访问管理","w":3,"q":"审计要求说明'谁能访问客户数据库'。最可靠的证据来源是？","o":["DBA 的记忆","IAM/数据库授权导出+最近复核记录（与实际权限导出一致）","岗位说明书","网络拓扑图"],"a":1,"e":"证据应来自可验证的系统导出与复核记录，而非人员记忆或描述性文件。（OSG 第14章 访问审计）","f":"14 控制和监控访问","v":[]},{"id":"ex65","d":"域6 安全评估与测试","w":3,"q":"渗透测试范围讨论中，客户要求'不要碰生产'。测试方应？","o":["口头答应后仍偷偷测生产","在 RoE 中明确排除项与替代验证方式（测试环境/时间窗/只读验证），双方签署","拒绝测试","只做端口扫描充数"],"a":1,"e":"范围边界必须文档化并遵守；越界测试违法且破坏信任，可通过替代手段部分补偿覆盖。（OSG 第15章 RoE）","f":"15 安全评估与测试","v":[]},{"id":"ex66","d":"域6 安全评估与测试","w":3,"q":"漏洞周报显示'平均修复时间 12 天'达标，但个别严重漏洞挂起 90 天。报告改进是？","o":["维持平均值汇报","按严重级别分档展示 SLA 达成与超期豁免清单（暴露长尾风险）","删除超期项","只报好消息"],"a":1,"e":"平均值掩盖长尾；分级 SLA+超期豁免透明化才能反映真实风险。（OSG 第15章 度量报告）","f":"15 安全评估与测试","v":[]},{"id":"ex67","d":"域6 安全评估与测试","w":3,"q":"开发团队质疑'扫描器报的 XXE 漏洞不存在'。最专业的处理是？","o":["直接关闭工单","提供可复现验证（payload 与响应证据）；确属误报则调整规则并记录","改低漏洞等级了事","要求开发自行证明"],"a":0,"e":"以可复现证据定真伪：确认为误报的应优化检测并留档，避免报告可信度下降。（OSG 第15章 漏洞验证）","f":"15 安全评估与测试","v":[]},{"id":"ex68","d":"域6 安全评估与测试","w":3,"q":"'安全控制测试'中验证备份有效性的最佳证据是？","o":["备份成功率报表","最近一次真实恢复演练的记录（恢复时长、数据一致性校验结果）","备份容量趋势","磁带购买发票"],"a":1,"e":"恢复能力只有通过真实演练才能证明，成功率不代表可恢复。（OSG 第15/18章 备份测试）","f":"15 安全评估与测试","v":[]},{"id":"ex69","d":"域6 安全评估与测试","w":3,"q":"为满足 PCI DSS 季度扫描要求而'为扫而扫'。更符合目的的做法是？","o":["把扫描纳入变更闭环：重大变更触发即扫 + 季度全量，结果进入修复跟踪","扫描前临时关服务","扫描报告改分数","外包后不再过问"],"a":0,"e":"合规扫描的价值在于结果被处置：事件驱动+周期结合并跟踪闭环。（OSG 第15章 合规扫描运营化）","f":"15 安全评估与测试","v":[]},{"id":"ex70","d":"域6 安全评估与测试","w":3,"q":"新上线前评估仅做了功能测试。加入哪项安全测试最紧迫？","o":["渗透测试","针对互联网暴露面的 DAST+关键组件 SCA（已知漏洞与暴露验证）","代码行数统计","性能压测"],"a":1,"e":"上线窗口内性价比最高的是外部可见面验证与依赖漏洞核查；渗透可随后按风险安排。（OSG 第15/20章 上线安全验证）","f":"15 安全评估与测试","v":[]},{"id":"ex71","d":"域6 安全评估与测试","w":3,"q":"SOC 想证明'检测能力覆盖主流攻击'。最合适的评估方法？","o":["数告警总量","以 ATT&CK 为框架做覆盖映射并用 BAS/紫队验证检测有效性","统计误报率即可","问卷自评"],"a":1,"e":"ATT&CK 映射+攻击模拟验证把'有没有检测'变成可测试命题。（OSG 第15章 检测评估）","f":"15 安全评估与测试","v":[]},{"id":"ex72","d":"域6 安全评估与测试","w":3,"q":"第三方渗透测试报告仅给'高危 3 个'无细节。客户应？","o":["接受即可","要求提供证据级发现（复现步骤/截图/请求响应）与修复验证复测条款","自己复现所有漏洞","起诉测试方"],"a":1,"e":"无证据的等级无法指导修复；合同应约定证据交付与复测。（OSG 第15章 测试交付）","f":"15 安全评估与测试","v":[]},{"id":"ex73","d":"域6 安全评估与测试","w":3,"q":"审计'日志控制有效性'最应检查的是？","o":["日志文件大小","关键操作的日志是否被生成、集中保护、定期审阅且有证据（审阅记录）","日志字体","保留天数是否最长"],"a":1,"e":"日志控制三要素：生成、保护、审阅；只看留存时长或容量不构成有效控制。（OSG 第15章 审计日志测试）","f":"15 安全评估与测试","v":[]},{"id":"ex74","d":"域6 安全评估与测试","w":3,"q":"企业希望评估'钓鱼演练效果'。比点击率更有价值的指标是？","o":["邮件发送总量","上报率（发现即报）与点击率的比值趋势、上报响应时长","剧本长度","主题行字数"],"a":1,"e":"上报文化是关键韧性指标：高上报低点击才是健康态。（OSG 第15章 意识度量）","f":"15 安全评估与测试","v":[]},{"id":"ex75","d":"域6 安全评估与测试","w":3,"q":"'代码审计发现硬编码密钥'但系统已运行多年。正确的处置顺序？","o":["忽略（历史遗留）","评估影响→立即轮换密钥→清理代码与历史→改用秘密管理并验证无中断","直接删除代码上线","仅写报告"],"a":1,"e":"密钥视为已泄露：先轮换止损再改架构，验证业务连续性，闭环防止再犯。（OSG 第15/20章 审计整改）","f":"15 安全评估与测试","v":[]},{"id":"ex76","d":"域6 安全评估与测试","w":3,"q":"监管检查前两周，组织想'补齐证据'。可持续的正确姿势是？","o":["突击补造历史记录","建立证据常态化归集（控制运行记录自动留存），检查只是展示","临时聘请律师","关闭系统规避检查"],"a":1,"e":"证据应在日常运营中持续生成；补造记录属欺诈，风险更大。（OSG 第15章 合规运营化）","f":"15 安全评估与测试","v":[]},{"id":"ex77","d":"域7 安全运营","w":3,"q":"周五 18:00 发现面向互联网的系统存在已被在野利用的 RCE。应急决策应优先？","o":["等周一变更窗口","启动紧急变更：评估缓解措施（WAF 规则/下线功能）与补丁风险，管理层按影响决策","关闭全网","只发邮件通知"],"a":1,"e":"在野利用要求立即行动：先缓解（虚拟补丁/功能开关）再走紧急补丁流程，风险决策升级到管理层。（OSG 第16章 紧急补丁管理）","f":"16 安全运营管理","v":[]},{"id":"ex78","d":"域7 安全运营","w":3,"q":"事件调查需要审计一名员工的终端。依据是？","o":["怀疑即可动手","事前同意的使用政策（监控告知与授权）+ HR/法务批准+范围最小化","任何员工可随时查看他人终端","无需依据"],"a":1,"e":"监控与调查的合法性来自预先告知的政策与授权程序，且范围最小化保护隐私。（OSG 第19章 调查合规）","f":"19 调查和道德","v":[]},{"id":"ex79","d":"域7 安全运营","w":3,"q":"备份数据被勒索者同步加密，因为备份系统与生产同域管理。整改重点是？","o":["加快备份频率","备份体系隔离：独立凭据/域、不可变或离线副本、删除/加密备份需双人控制","更换备份品牌","增加备份次数"],"a":1,"e":"勒索定向攻击备份，隔离与不可变是根本；频率与品牌不解决同域失陷。（OSG 第18章 备份安全）","f":"18 灾难恢复计划","v":[]},{"id":"ex80","d":"域7 安全运营","w":3,"q":"DR 演练发现 RTO 无法达成的最大原因是'关键人员不知道如何切换'。最有效的改进？","o":["招聘更多专家","文档化 runbook+定期分角色演练与交叉培训，降低单点依赖","延长 RTO 目标","购买更多 licenses"],"a":0,"e":"人员能力是恢复能力核心：runbook 化+演练+备份人员是标准解法；延长目标自欺。（OSG 第18章 演练改进）","f":"18 灾难恢复计划","v":[]},{"id":"ex81","d":"域7 安全运营","w":3,"q":"变更后系统宕机，回滚又失败。暴露的变更管理缺陷是？","o":["回滚预案未经测试验证","变更通知不及时","服务器太旧","人员太少"],"a":0,"e":"每个变更必须有经过演练的回滚方案；本次事故根因在回滚未被验证。（OSG 第16章 变更回滚）","f":"16 安全运营管理","v":[]},{"id":"ex82","d":"域7 安全运营","w":3,"q":"SOC 二线建议'把所有中危告警也自动封 IP'。潜在问题是？","o":["没有问题","误报导致的自动阻断可能瘫痪正常业务（NAT 出口/合作伙伴），需分级置信与人工复核机制","会减少告警","更省钱"],"a":1,"e":"自动化响应须与置信度匹配：低置信动作应弱（限速/观察），高置信才阻断，且要有申诉白名单。（OSG 第16章 自动化响应治理）","f":"16 安全运营管理","v":[]},{"id":"ex83","d":"域7 安全运营","w":3,"q":"取证时发现关键主机日志只保留 7 天。对调查的影响与改进？","o":["无影响","证据缺失难以还原时间线；按调查/合规需求延长关键日志保留并集中存储","关闭日志","只保留告警"],"a":1,"e":"日志留存应覆盖检测延迟与法规要求；集中化与分层保留是标准做法。（OSG 第15/19章 日志保留）","f":"19 调查和道德","v":[]},{"id":"ex84","d":"域7 安全运营","w":3,"q":"事件响应中'谁负责对外沟通'最应由谁决定？","o":["值班分析师","按预先定义的危机沟通计划（指定发言人、法务/PR 参与口径审批）","论坛发帖者","任意高管"],"a":1,"e":"沟通失控（多口径/泄密）会放大事件伤害；发言人制度与口径审批应预先建立。（OSG 第17章 事件沟通）","f":"17 事件的预防和响应","v":[]},{"id":"ex85","d":"域7 安全运营","w":3,"q":"受监管机构要求 72 小时通报重大事件。'时间起算点'通常是什么？","o":["攻击发生时间","知悉（awareness）时间，需有知悉记录与评估流程支撑","通报获批时间","事件关闭时间"],"a":1,"e":"多数法规以'知悉'起算，组织需留存发现时间证据与快速影响评估能力。（OSG 第17章 法定通报）","f":"17 事件的预防和响应","v":[]},{"id":"ex86","d":"域7 安全运营","w":3,"q":"红蓝紫队演练中，'紫队'的价值是？","o":["只进攻不防守","把红队发现与蓝队检测打通：快速反馈迭代检测工程（attack-detect-improve 循环）","只写报告","代替管理层决策"],"a":1,"e":"紫队是协作模式而非第三方队伍，核心是闭环提升检测与响应。（OSG 第15/17章 紫队）","f":"17 事件的预防和响应","v":[]},{"id":"ex87","d":"域7 安全运营","w":3,"q":"M&A 尽调发现目标公司曾发生未披露数据泄露。安全团队的正确角色是？","o":["帮忙隐瞒","独立评估风险暴露与整改成本，为交易决策提供安全尽调意见","拒绝参与","抬高自己团队预算"],"a":1,"e":"安全尽调（网络尽调）量化目标风险与债务，是并购决策必要输入；隐瞒失职违法。（OSG 第1章/第19章 治理与道德）","f":"19 调查和道德","v":[]},{"id":"ex88","d":"域7 安全运营","w":3,"q":"运维用'计划任务+域管账号'跑批处理脚本。最小化风险的做法？","o":["保留现状（能跑就行）","专用低权服务账号+精确权限脚本+凭据保管（PAM）+执行审计","把脚本交给每个管理员手动跑","删除脚本"],"a":1,"e":"自动化任务常驻特权是典型隐患：专用最小权限账号与凭据治理是标准整改。（OSG 第16章 特权自动化治理）","f":"16 安全运营管理","v":[]},{"id":"ex89","d":"域7 安全运营","w":3,"q":"事件升级到'灾难'级别后，首要的协调机制是？","o":["各团队自行发挥","启动危机指挥架构（EOT/危机小组）：明确决策人、通报树与战情室机制","等待客户投诉","直接宣布破产"],"a":1,"e":"灾难场景需要集中指挥与清晰授权，避免多头与真空；指挥体系应在计划中预先定义并演练。（OSG 第18章 危机管理）","f":"18 灾难恢复计划","v":[]},{"id":"ex90","d":"域7 安全运营","w":3,"q":"'安全运营中心'与'IT 服务台'割裂导致事件信息不同步。改进方向？","o":["合并成一支队伍","建立事件联动流程与共享工单（安全事件影响评估联动变更/恢复）","各自加密数据","定期互相批评"],"a":1,"e":"安全事件常需 IT 变更配合（隔离、重启、回滚），流程与工具层联动是成熟 SOC 标志。（OSG 第16章 运营协同）","f":"16 安全运营管理","v":[]},{"id":"ex91","d":"域7 安全运营","w":3,"q":"某控制的有效性声明为'防火墙规则季度评审'。审计发现评审签字齐全但无人比对实际配置。结论？","o":["控制有效（有签字）","控制设计有效但运行无效（未实质执行比对），属形式合规","控制无效因为防火墙太旧","无法判断"],"a":1,"e":"审计关注运行有效性：签了字没干活=未有效运行，需整改执行证据（比对记录与差异闭环）。（OSG 第15章 控制有效性）","f":"15 安全评估与测试","v":[]},{"id":"ex92","d":"域8 软件开发安全","w":3,"q":"上线前安全测试发现越权漏洞，业务方要求'先上线后修复'。最稳妥的决策依据？","o":["上线压力大小","风险量化（暴露面、数据敏感度、利用难度）+补偿控制可行性+管理层书面风险接受","开发团队工期","厂商建议"],"a":1,"e":"带病上线必须走风险决策：量化+补偿控制+正式接受与期限，而非凭压力拍板。（OSG 第20章 发布风险管理）","f":"20 软件开发安全","v":[]},{"id":"ex93","d":"域8 软件开发安全","w":3,"q":"App 商店上架要求证明'未集成恶意第三方 SDK'。最有力的证据是？","o":["开发者书面承诺","SBOM/依赖清单+扫描报告（SCA）与构建可追溯证明","下载量截图","用户好评"],"a":1,"e":"依赖清点+自动扫描+可重现构建构成可验证的供应链证据链。（OSG 第20章 移动供应链安全）","f":"20 软件开发安全","v":[]},{"id":"ex94","d":"域8 软件开发安全","w":3,"q":"微服务间互相用长期 API Key 调用。更好的方案是？","o":["把 Key 加长到 256 位","短期令牌（mTLS/服务身份）+按服务授权，密钥自动轮换","所有服务共享一个 Key","Key 写进环境变量即可"],"a":1,"e":"服务网格/mTLS 提供身份化、短时效、可撤销的服务间认证，优于静态长密钥。（OSG 第20章 服务间安全）","f":"20 软件开发安全","v":[]},{"id":"ex95","d":"域8 软件开发安全","w":3,"q":"产品需求'用户能看自己的订单'被实现为'接口返回该用户全部字段+同租户他人订单 ID'。测试应重点验证？","o":["响应速度","对象级授权（BOLA/IDOR）：字段最小化与资源归属校验","页面配色","并发数"],"a":1,"e":"需求映射到授权测试用例：字段最小化+归属校验，防止 API 过度暴露与越权。（OSG 第21章 API 安全测试）","f":"21 恶意代码和应用攻击","v":[]},{"id":"ex96","d":"域8 软件开发安全","w":3,"q":"安全团队被要求'给开发做一次安全培训'。最能改变行为的培训设计是？","o":["两小时通用 PPT","结合团队实际技术栈的动手内容（漏洞复现+修复练习）与考核纳入 DoD","发放 PDF 自学","年度一次性网课"],"a":1,"e":"成人学习与行为改变依赖相关性（自己栈的漏洞）与实践；通用宣贯效果差。（OSG 第20章 开发安全能力建设）","f":"20 软件开发安全","v":[]},{"id":"ex97","d":"域8 软件开发安全","w":3,"q":"CI 集群被攻陷可能'污染所有制品'。纵深防御应包含？","o":["仅修改 CI 密码","构建环境隔离与最小权限、制品签名+部署端验签、可重现构建与依赖锁定","把 CI 藏在内网即可","禁止自动化"],"a":1,"e":"供应链纵深=入口防护（凭据/隔离）+产物验证（签名）+可重现性；单改密码或藏内网不足。（OSG 第20章 构建安全）","f":"20 软件开发安全","v":[]},{"id":"ex98","d":"域8 软件开发安全","w":3,"q":"第三方报告我司 App 存在隐私合规问题（超范围收集）。处置第一步？","o":["下架 App 永久","核实报告：复现与影响评估，按披露流程回应与整改","起诉报告人","置之不理"],"a":1,"e":"对外披露先核实再行动，按协同披露与合规整改闭环回应。（OSG 第19/20章 漏洞与隐私披露响应）","f":"20 软件开发安全","v":[]},{"id":"ex99","d":"域8 软件开发安全","w":3,"q":"'安全需求'评审时开发问'日志该记什么'。最合理的回答？","o":["全部请求与响应明文","足以支撑审计与调查的元数据：主体、操作、对象、结果、时间（敏感字段脱敏），集中收集","不用记日志","只记错误"],"a":1,"e":"日志需求按'可调查性'设计：五要素齐全+脱敏+集中化，兼顾取证与隐私。（OSG 第20章 安全日志需求）","f":"20 软件开发安全","v":[]},{"id":"ex100","d":"域8 软件开发安全","w":3,"q":"旧系统依赖已停维护的库。工程上正确的安全策略是？","o":["永不改动","封装隔离+补偿控制（WAF/输入校验）+制定替换路线图与风险接受期限","删除依赖看报错","等待厂商复活"],"a":1,"e":"遗留依赖需'控制风险+限期替换'双轨：临时缓解可买时间但不能成为永久方案。（OSG 第20章 遗留系统安全）","f":"20 软件开发安全","v":[]},{"id":"ex101","d":"域8 软件开发安全","w":3,"q":"安全左移后，安全团队成为瓶颈（评审排队）。规模化解决方向是？","o":["加人无限扩编","安全即代码：把检查自动化进流水线（策略即代码/ASVS 检查项），人只处理高价值判断","取消评审","延长发布周期"],"a":1,"e":"规模化靠自动化与赋能（平台化安全能力），专家聚焦设计评审与复杂风险。（OSG 第20章 安全规模化）","f":"20 软件开发安全","v":[]},{"id":"ex102","d":"域8 软件开发安全","w":3,"q":"审计发现生产环境有人直接改数据库'救火'。最需要补齐的是？","o":["更严格的口令","受控的数据修复流程：变更单+双人执行+审计留痕，事后复核纳入例会","禁用数据库","给 DBA 涨薪"],"a":0,"e":"紧急数据操作也须受控可审计（break-glass 式流程），否则等于无限后门。（OSG 第16/20章 生产变更治理）","f":"20 软件开发安全","v":[]}];
